  const [selectedGroup, setSelectedGroup] = useState<Group | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showInviteForm, setShowInviteForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRole, setFilterRole] = useState<'all' | 'organizer' | 'member'>('all');

  // Filter groups based on search and role
  const filteredGroups = groups.filter(group => {
    const matchesSearch = group.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         group.description.toLowerCase().includes(searchTerm.toLowerCase());

    if (filterRole === 'all') return matchesSearch;

    const currentMember = group.members.find(m => m.id === currentUserId);
    return matchesSearch && currentMember?.role === filterRole;
  });

  // Get current user's role in selected group
  const getCurrentUserRole = (group: Group): GroupMember['role'] | null => {
    const member = group.members.find(m => m.id === currentUserId);
    return member?.role || null;
  };

  // Check if current user can perform admin actions
  const canManageGroup = (group: Group): boolean => {
    const role = getCurrentUserRole(group);
    return role === 'organizer';
  };

  // Handle group creation
  const handleCreateGroup = async (formData: FormData) => {
    setLoading(true);
    setError(null);

    try {
      const groupData = {
        name: formData.get('name') as string,
        description: formData.get('description') as string,
        members: [{
          id: currentUserId,
          name: 'Current User', // This would come from user context
          email: 'user@example.com', // This would come from user context
          role: 'organizer' as const,
          status: 'active' as const,
          joinedAt: new Date(),
          preferences: {
            notifications: true,
            emailUpdates: true,
            smsUpdates: false
          },
          skills: []
        }],
        settings: {
          isPrivate: formData.get('isPrivate') === 'on',
          requireApproval: formData.get('requireApproval') === 'on',
          allowMemberInvites: formData.get('allowMemberInvites') === 'on',
          maxMembers: parseInt(formData.get('maxMembers') as string) || 50
        }
      };

      await onCreateGroup(groupData);
      setShowCreateForm(false);
