                  errors.startDate ? 'border-[rgb(239,68,68)]' : 'border-[rgb(226,232,240)]'
                }`}
                aria-describedby={errors.startDate ? 'start-date-error' : undefined}
              />
              {errors.startDate && (
                <p id="start-date-error" className="mt-1 text-sm text-[rgb(239,68,68)]" role="alert">
                  {errors.startDate}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="end-date" className="block text-sm font-semibold text-[rgb(15,23,42)] mb-2">
                <Calendar className="inline w-4 h-4 mr-1" />
                End Date
              </label>
              <input
                id="end-date"
                type="date"
                value={formData.endDate}
                onChange={(e) => handleInputChange('endDate', e.target.value)}
                min={formData.startDate || new Date().toISOString().split('T')[0]}
                className={`w-full px-4 py-3 rounded-lg border-2 bg-[rgb(255,255,255)] text-[rgb(15,23,42)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors ${
                  errors.endDate ? 'border-[rgb(239,68,68)]' : 'border-[rgb(226,232,240)]'
                }`}
                aria-describedby={errors.endDate ? 'end-date-error' : undefined}
              />
              {errors.endDate && (
                <p id="end-date-error" className="mt-1 text-sm text-[rgb(239,68,68)]" role="alert">
                  {errors.endDate}
                </p>
              )}
            </div>
          </div>

          {/* Location */}
          <div className="relative">
            <label htmlFor="location" className="block text-sm font-semibold text-[rgb(15,23,42)] mb-2">
              <MapPin className="inline w-4 h-4 mr-1" />
              Location
            </label>
            <input
              id="location"
              type="text"
              value={locationQuery}
              onChange={(e) => handleLocationSearch(e.target.value)}
              onFocus={() => locationSuggestions.length > 0 && setShowLocationSuggestions(true)}
              placeholder="Search for a location"
              className={`w-full px-4 py-3 rounded-lg border-2 bg-[rgb(255,255,255)] text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)] placeholder-opacity-50 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors ${
                errors.location ? 'border-[rgb(239,68,68)]' : 'border-[rgb(226,232,240)]'
              }`}
              aria-describedby={errors.location ? 'location-error' : undefined}
              aria-expanded={showLocationSuggestions}
              aria-haspopup="listbox"
              role="combobox"
            />

            {showLocationSuggestions && locationSuggestions.length > 0 && (
              <div className="absolute z-10 w-full mt-1 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg shadow-lg max-h-60 overflow-y-auto">
                {locationSuggestions.map((location) => (
                  <button
                    key={location.id}
                    type="button"
                    onClick={() => selectLocation(location)}
                    className="w-full px-4 py-3 text-left hover:bg-[rgb(248,250,252)] focus:bg-[rgb(248,250,252)] focus:outline-none transition-colors"
                    role="option"
                  >
                    <div className="font-semibold text-[rgb(15,23,42)]">{location.name}</div>
                    <div className="text-sm text-[rgb(15,23,42)] opacity-70">{location.address}</div>
                  </button>
                ))}
              </div>
            )}

            {errors.location && (
              <p id="location-error" className="mt-1 text-sm text-[rgb(239,68,68)]" role="alert">
                {errors.location}
              </p>
            )}
          </div>

          {/* Max Participants */}
          <div>
            <label htmlFor="max-participants" className="block text-sm font-semibold text-[rgb(15,23,42)] mb-2">
              <Users className="inline w-4 h-4 mr-1" />
              Maximum Participants
            </label>
            <input
              id="max-participants"
              type="number"
              min="2"
              max="50"
              value={formData.maxParticipants}
              onChange={(e) => handleInputChange('maxParticipants', parseInt(e.target.value) || 0)}
              className={`w-full px-4 py-3 rounded-lg border-2 bg-[rgb(255,255,255)] text-[rgb(15,23,42)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors ${
                errors.maxParticipants ? 'border-[rgb(239,68,68)]' : 'border-[rgb(226,232,240)]'
              }`}
              aria-describedby={errors.maxParticipants ? 'max-participants-error' : undefined}
            />
            {errors.maxParticipants && (
              <p id="max-participants-error" className="mt-1 text-sm text-[rgb(239,68,68)]" role="alert">
                {errors.maxParticipants}
              </p>
            )}
          </div>

          {/* Difficulty Level */}
          <div>
            <label className="block text-sm font-semibold text-[rgb(15,23,42)] mb-3">
              Difficulty Level
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {difficultyLevels.map((level) => (
                <button
                  key={level.value}
                  type="button"
                  onClick={() => handleInputChange('difficulty', level.value)}
                  className={`p-4 rounded-lg border-2 text-left transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 ${
                    formData.difficulty === level.value
                      ? `border-[${level.color}] bg-[${level.color}] bg-opacity-10 focus:ring-[${level.color}]`
                      : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] hover:border-[rgb(34,139,34)] focus:ring-[rgb(34,139,34)]'
                  }`}
                  aria-pressed={formData.difficulty === level.value}
                >
                  <div className="font-semibold text-[rgb(15,23,42)]">{level.label}</div>
                  <div className="text-sm text-[rgb(15,23,42)] opacity-70 mt-1">{level.description}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Vehicle Requirements */}
          <div>
            <label className="block text-sm font-semibold text-[rgb(15,23,42)] mb-3">
              Vehicle Requirements
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {vehicleOptions.map((option) => (
                <button
                  key={option.id}
                  type="button"
                  onClick={() => toggleVehicleRequirement(option.id)}
                  className={`p-3 rounded-lg border-2 text-left transition-all focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 ${
                    formData.vehicleRequirements.includes(option.id)
                      ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)] bg-opacity-10'
                      : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] hover:border-[rgb(34,139,34)]'
                  }`}
                  aria-pressed={formData.vehicleRequirements.includes(option.id)}
                >
                  <div className="flex items-center gap-2">
                    <span className="text-lg">{option.icon}</span>
                    <span className="font-semibold text-[rgb(15,23,42)]">{option.label}</span>
                    {formData.vehicleRequirements.includes(option.id) && (
                      <div className="ml-auto w-5 h-5 rounded-full bg-[rgb(34,139,34)] flex items-center justify-center">
                        <div className="w-2 h-2 bg-[rgb(255,255,255)] rounded-full"></div>
                      </div>
                    )}
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Submit Button */}
          <div className="pt-6">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-[rgb(34,139,34)] text-[rgb(255,255,255)] font-semibold py-4 px-6 rounded-lg hover:bg-[rgb(34,139,34)] hover:bg-opacity-90 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
              aria-describedby="submit-button-description"
            >
              {isSubmitting ? (
                <div className="flex items-center justify-center gap-2">
                  <div className="w-5 h-5 border-2 border-[rgb(255,255,255)] border-t-transparent rounded-full animate-spin"></div>
                  Creating Trip...
                </div>
              ) : (
                <div className="flex items-center justify-center gap-2">
                  <Plus className="w-5 h-5" />
                  Create Trip
                  <ChevronRight className="w-5 h-5" />
                </div>
              )}
            </button>
            <p id="submit-button-description" className="sr-only">
              Create your off-road trip and start planning with your group
            </p>
          </div>
        </form>
      </div>
    </div>
  )
}

