'use client';

import React, { useState, useEffect } from 'react';
import { Calendar, Clock, Users, Plus, Edit2, Trash2, ChefHat, MapPin } from 'lucide-react';

// TypeScript Interfaces
interface MenuItem {
  id: string;
  name: string;
  description?: string;
  servingTime: string;
  servingDate: string;
  assignedTo: string[];
  ingredients: string[];
  dietary: string[];
  estimatedCost: number;
  prepTime: number;
  servingSize: number;
  category: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  location?: string;
}

interface MenuModelProps {
  tripId: string;
  isOpen: boolean;
  onClose: () => void;
  onSave: (menuItem: MenuItem) => void;
  editingItem?: MenuItem | null;
  groupMembers: Array<{ id: string; name: string; email: string }>;
}

interface FormData {
  name: string;
  description: string;
  servingTime: string;
  servingDate: string;
  assignedTo: string[];
  ingredients: string[];
  dietary: string[];
  estimatedCost: number;
  prepTime: number;
  servingSize: number;
  category: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  location: string;
}

const MenuModel: React.FC<MenuModelProps> = ({
  tripId,
  isOpen,
  onClose,
  onSave,
  editingItem,
  groupMembers
}) => {
  const [formData, setFormData] = useState<FormData>({
    name: '',
    description: '',
    servingTime: '',
    servingDate: '',
    assignedTo: [],
    ingredients: [],
    dietary: [],
    estimatedCost: 0,
    prepTime: 30,
    servingSize: 4,
    category: 'dinner',
    location: ''
  });

  const [newIngredient, setNewIngredient] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dietaryOptions = [
    'Vegetarian', 'Vegan', 'Gluten-Free', 'Dairy-Free', 'Nut-Free', 'Keto', 'Paleo'
  ];

  const categories = [
    { value: 'breakfast', label: 'Breakfast', icon: '🌅' },
    { value: 'lunch', label: 'Lunch', icon: '☀️' },
    { value: 'dinner', label: 'Dinner', icon: '🌙' },
    { value: 'snack', label: 'Snack', icon: '🥨' }
  ];

  useEffect(() => {
    if (editingItem) {
      setFormData({
        name: editingItem.name,
        description: editingItem.description || '',
        servingTime: editingItem.servingTime,
        servingDate: editingItem.servingDate,
        assignedTo: editingItem.assignedTo,
        ingredients: editingItem.ingredients,
        dietary: editingItem.dietary,
        estimatedCost: editingItem.estimatedCost,
        prepTime: editingItem.prepTime,
        servingSize: editingItem.servingSize,
        category: editingItem.category,
        location: editingItem.location || ''
      });
    } else {
      resetForm();
    }
  }, [editingItem, isOpen]);

  const resetForm = () => {
    setFormData({
      name: '',
      description: '',
      servingTime: '',
      servingDate: '',
      assignedTo: [],
      ingredients: [],
      dietary: [],
      estimatedCost: 0,
      prepTime: 30,
      servingSize: 4,
      category: 'dinner',
      location: ''
    });
    setErrors({});
    setNewIngredient('');
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Meal name is required';
    }

    if (!formData.servingDate) {
      newErrors.servingDate = 'Serving date is required';
    }

    if (!formData.servingTime) {
      newErrors.servingTime = 'Serving time is required';
    }

    if (formData.assignedTo.length === 0) {
      newErrors.assignedTo = 'At least one person must be assigned';
    }

    if (formData.ingredients.length === 0) {
      newErrors.ingredients = 'At least one ingredient is required';
    }

    if (formData.servingSize < 1) {
      newErrors.servingSize = 'Serving size must be at least 1';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const menuItem: MenuItem = {
        id: editingItem?.id || `menu-${Date.now()}`,
        ...formData
      };

      await onSave(menuItem);
      resetForm();
      onClose();
    } catch (error) {
      console.error('Error saving menu item:', error);
      setErrors({ submit: 'Failed to save menu item. Please try again.' });
    } finally {
      setIsSubmitting(false);
    }
  };

  const addIngredient = () => {
    if (newIngredient.trim() && !formData.ingredients.includes(newIngredient.trim())) {
      setFormData(prev => ({
        ...prev,
        ingredients: [...prev.ingredients, newIngredient.trim()]
      }));
      setNewIngredient('');
    }
  };

  const removeIngredient = (ingredient: string) => {
    setFormData(prev => ({
      ...prev,
      ingredients: prev.ingredients.filter(i => i !== ingredient)
    }));
  };

  const toggleAssignment = (memberId: string) => {
    setFormData(prev => ({
      ...prev,
      assignedTo: prev.assignedTo.includes(memberId)
        ? prev.assignedTo.filter(id => id !== memberId)
        : [...prev.assignedTo, memberId]
    }));
  };

  const toggleDietary = (option: string) => {
    setFormData(prev => ({
      ...prev,
      dietary: prev.dietary.includes(option)
        ? prev.dietary.filter(d => d !== option)
        : [...prev.dietary, option]
    }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg shadow-lg w-full max-w-2xl max-h-[90vh] overflow-y-auto m-4">
        <div className="sticky top-0 bg-white border-b border-[rgb(226, 232, 240)] px-6 py-4 rounded-t-lg">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <ChefHat className="w-6 h-6 text-green-600" />
              <h2 className="text-xl font-semibold text-[rgb(15, 23, 42)]">
                {editingItem ? 'Edit Meal' : 'Add New Meal'}
              </h2>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-[rgb(241, 245, 249)] rounded-lg transition-colors"
              aria-label="Close modal"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          {/* Basic Information */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium text-[rgb(15, 23, 42)]">Basic Information</h3>

            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-2">
                Meal Name *
              </label>
              <input
                type="text"
                id="name"
                value={formData.name}
                onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 ${
                  errors.name ? 'border-red-500' : 'border-gray-300'
                }`}
                placeholder="e.g., Campfire Chili"
                aria-describedby={errors.name ? 'name-error' : undefined}
              />
              {errors.name && (
                <p id="name-error" className="mt-1 text-sm text-[rgb(255, 255, 255)]">{errors.name}</p>
              )}
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-2">
                Description
              </label>
              <textarea
                id="description"
                value={formData.description}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500"
                placeholder="Describe the meal, cooking method, or special notes..."
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="category" className="block text-sm font-medium text-gray-700 mb-2">
                  Category *
                </label>
                <select
                  id="category"
                  value={formData.category}
                  onChange={(e) => setFormData(prev => ({ ...prev, category: e.target.value as any }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500"
                >
                  {categories.map(cat => (
                    <option key={cat.value} value={cat.value}>
                      {cat.icon} {cat.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="location" className="block text-sm font-medium text-gray-700 mb-2">
                  Location
                </label>
                <input
                  type="text"
                  id="location"
                  value={formData.location}
                  onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500"
                  placeholder="e.g., Main campsite, Trail head"
                />
              </div>
            </div>
          </div>

          {/* Timing */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium text-[rgb(15, 23, 42)]">Timing</h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="servingDate" className="block text-sm font-medium text-gray-700 mb-2">
                  Serving Date *
                </label>
                <input
                  type="date"
                  id="servingDate"
                  value={formData.servingDate}
                  onChange={(e) => setFormData(prev => ({ ...prev, servingDate: e.target.value }))}
                  className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 ${
                    errors.servingDate ? 'border-red-500' : 'border-gray-300'
                  }`}
                  aria-describedby={errors.servingDate ? 'date-error' : undefined}
                />
                {errors.servingDate && (
