'use client';

import { useState, useEffect, useRef } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface ChatMessage {
  id: string;
  trip_id: string;
  user_id: string;
  message: string;
  created_at: string;
  user_name: string;
  user_avatar?: string;
}

interface ChatAPIProps {
  tripId: string;
  userId: string;
  userName: string;
  onMessageSent?: (message: ChatMessage) => void;
  onError?: (error: string) => void;
}

interface ChatAPIResponse {
  data?: ChatMessage[];
  error?: string;
}

interface SendMessageResponse {
  data?: ChatMessage;
  error?: string;
}

// Chat API Component
export default function ChatAPI({ 
  tripId, 
  userId, 
  userName, 
  onMessageSent, 
  onError 
}: ChatAPIProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isOnline, setIsOnline] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const supabase = createClientComponentClient();

  // Network status monitoring
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Fetch messages
  const fetchMessages = async (): Promise<ChatAPIResponse> => {
    try {
      setIsLoading(true);
      setError(null);

      const { data, error } = await supabase
        .from('chat_messages')
        .select(`
          id,
          trip_id,
          user_id,
          message,
          created_at,
          profiles:user_id (
            name,
            avatar_url
          )
        `)
        .eq('trip_id', tripId)
        .order('created_at', { ascending: true });

      if (error) throw error;

      const formattedMessages: ChatMessage[] = data?.map(msg => ({
        id: msg.id,
        trip_id: msg.trip_id,
        user_id: msg.user_id,
        message: msg.message,
        created_at: msg.created_at,
        user_name: msg.profiles?.name || 'Unknown User',
        user_avatar: msg.profiles?.avatar_url
      })) || [];

      setMessages(formattedMessages);
      return { data: formattedMessages };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to fetch messages';
      setError(errorMessage);
      onError?.(errorMessage);
      return { error: errorMessage };
    } finally {
      setIsLoading(false);
    }
  };

  // Send message
  const sendMessage = async (message: string): Promise<SendMessageResponse> => {
    if (!message.trim() || !isOnline) return { error: 'Cannot send message' };

    try {
      setIsSending(true);
      setError(null);

      const newMsg = {
        trip_id: tripId,
        user_id: userId,
        message: message.trim(),
        created_at: new Date().toISOString()
      };

      // Optimistic update
      const optimisticMessage: ChatMessage = {
        id: `temp-${Date.now()}`,
        ...newMsg,
        user_name: userName
      };
      setMessages(prev => [...prev, optimisticMessage]);

      const { data, error } = await supabase
        .from('chat_messages')
        .insert([newMsg])
        .select(`
          id,
          trip_id,
          user_id,
          message,
          created_at,
          profiles:user_id (
            name,
            avatar_url
          )
        `)
        .single();

      if (error) throw error;

      const formattedMessage: ChatMessage = {
        id: data.id,
        trip_id: data.trip_id,
        user_id: data.user_id,
        message: data.message,
        created_at: data.created_at,
        user_name: data.profiles?.name || userName,
        user_avatar: data.profiles?.avatar_url
      };

      // Replace optimistic message with real one
      setMessages(prev => 
        prev.map(msg => 
          msg.id === optimisticMessage.id ? formattedMessage : msg
        )
      );

      onMessageSent?.(formattedMessage);
      return { data: formattedMessage };
    } catch (err) {
      // Remove optimistic message on error
      setMessages(prev => prev.filter(msg => !msg.id.startsWith('temp-')));

      const errorMessage = err instanceof Error ? err.message : 'Failed to send message';
      setError(errorMessage);
      onError?.(errorMessage);
      return { error: errorMessage };
    } finally {
      setIsSending(false);
    }
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const messageToSend = newMessage;
    setNewMessage('');
    await sendMessage(messageToSend);
  };

  // Auto-scroll to bottom
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initial load and real-time subscription
  useEffect(() => {
    fetchMessages();

    // Subscribe to real-time updates
    const channel = supabase
      .channel(`chat-${tripId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'chat_messages',
          filter: `trip_id=eq.${tripId}`
        },
        async (payload) => {
          const { data } = await supabase
            .from('chat_messages')
            .select(`
              id,
              trip_id,
              user_id,
              message,
              created_at,
              profiles:user_id (
                name,
                avatar_url
              )
            `)
            .eq('id', payload.new.id)
            .single();

          if (data && data.user_id !== userId) {
            const newMessage: ChatMessage = {
              id: data.id,
              trip_id: data.trip_id,
              user_id: data.user_id,
              message: data.message,
              created_at: data.created_at,
              user_name: data.profiles?.name || 'Unknown User',
              user_avatar: data.profiles?.avatar_url
            };
            setMessages(prev => [...prev, newMessage]);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tripId, userId, supabase]);

  // Format timestamp
  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffInHours = (now.getTime() - date.getTime()) / (1000 * 60 * 60);

    if (diffInHours < 24) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } else {
      return date.toLocaleDateString([], { month: 'short', day: 'numeric' });
    }
  };

  // Loading skeleton
  const MessageSkeleton = () => (
    <div className="flex gap-3 p-4">
      <div className="w-8 h-8 bg-[rgb(241,245,249)] rounded-full animate-pulse" />
      <div className="flex-1 space-y-2">
        <div className="h-4 bg-[rgb(241,245,249)] rounded animate-pulse w-24" />
        <div className="h-4 bg-[rgb(241,245,249)] rounded animate-pulse w-full" />
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-[rgb(255,255,255)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)]">
        <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Group Chat</h2>
        <div className="flex items-center gap-2">
          <div 
            className={`w-2 h-2 rounded-full ${
              isOnline ? 'bg-[rgb(34,139,34)]' : 'bg-[rgb(239,68,68)]'
            }`}
            aria-label={isOnline ? 'Online' : 'Offline'}
          />
          <span className="text-sm text-[rgb(100,116,139)]">
            {isOnline ? 'Online' : 'Offline'}
          </span>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {isLoading ? (
          <>
            <MessageSkeleton />
            <MessageSkeleton />
            <MessageSkeleton />
          </>
        ) : messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8">
            <div className="w-16 h-16 bg-[rgb(248,250,252)] rounded-full flex items-center justify-center mb-4">
              <svg 
                className="w-8 h-8 text-[rgb(100,116,139)]" 
                fill="none" 
                stroke="currentColor" 
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <path 
                  strokeLinecap="round" 
                  strokeLinejoin="round" 
                  strokeWidth={2} 
                  d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" 
                />
              </svg>
            </div>
            <h3 className="text-lg font-medium text-[rgb(15,23,42)] mb-2">
              Start the conversation
            </h3>
            <p className="text-[rgb(100,116,139)] max-w-sm">
              Send the first message to get your group chat started. Share updates, ask questions, or just say hello!
            </p>
          </div>
        ) : (
          messages.map((message) => (
            <div 
              key={message.id} 
              className={`flex gap-3 ${
                message.user_id === userId ? 'flex-row-reverse' : ''
              }`}
            >
              <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center flex-shrink-0">
                {message.user_avatar ? (
                  <img 
                    src={message.user_avatar} 
                    alt={message.user_name}
                    className="w-8 h-8 rounded-full object-cover"
                  />
                ) : (
                  <span className="text-sm font-medium text-[rgb(255,255,255)]">
                    {message.user_name.charAt(0).toUpperCase()}
                  </span>
                )}
              </div>
              <div 
                className={`flex-1 max-w-xs sm:max-w-sm ${
                  message.user_id === userId ? 'text-right' : ''
                }`}
              >
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-sm font-medium text-[rgb(15,23,42)]">
                    {message.user_name}
                  </span>
                  <span className="text-xs text-[rgb(100,116,139)]">
                    {formatTime(message.created_at)}
                  </span>
                </div>
                <div 
                  className={`p-3 rounded-lg ${
                    message.user_id === userId
                      ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                      : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
                  }`}
                >
                  <p className="text-sm break-words">{message.message}</p>
                </div>
              </div>
            </div>
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Error Message */}
      {error && (
        <div className="mx-4 mb-4 p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
          <div className="flex items-center gap-2">
            <svg 
              className="w-4 h-4 text-[rgb(239,68,68)]" 
              fill="none" 
              stroke="currentColor" 
              viewBox="0 0 24 24"
              aria-hidden="true"
            >
              <path 
                strokeLinecap="round" 
                strokeLinejoin="round" 
                strokeWidth={2} 
                d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" 
              />
            </svg>
            <p className="text-sm text-[rgb(239,68,68)]">{error}</p>
            <button
              onClick={() => setError(null)}
              className="ml-auto text-[rgb(239,68,68)] hover:text-[rgb(220,38,38)] transition-colors"
              aria-label="Dismiss error"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>
      )}

      {/* Message Input */}
      <form onSubmit={handleSubmit} className="p-4 border-t border-[rgb(226,232,240)]">
        <div className="flex gap-2">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder={isOnline ? "Type a message..." : "You're offline"}
            disabled={!isOnline || isSending}
            className="flex-1 px-4 py-3 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 disabled:bg-[rgb(241,245,249)] disabled:cursor-not-allowed text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)]"
            aria-label="Type your message"
          />
          <button
            type="submit"
            disabled={!newMessage.trim() || !isOnline || isSending}
            className="px-6 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium hover:bg-[rgb(22,101,22)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 disabled:bg-[rgb(156,163,175)] disabled:cursor-not-allowed transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center"
            aria-label="Send message"
          >
            {isSending ? (
              <svg 
                className="w-4 h-4 animate-spin" 
                fill="none" 
                stroke="currentColor" 
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <path 
                  strokeLinecap="round" 
                  strokeLinejoin="round" 
                  strokeWidth={2} 
                  d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" 
                />
              </svg>
            ) : (
              <svg 
                className="w-4 h-4" 
                fill="none" 
                stroke="currentColor" 
