'use client'

import { useState, useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Badge } from '@/components/ui/badge'
import { Switch } from '@/components/ui/switch'
import { Calendar, Send, Users, MapPin, Clock, CheckCircle, XCircle, AlertCircle } from 'lucide-react'
import { toast } from 'sonner'

interface TripMember {
  id: string
  name: string
  email: string
  phone?: string
  role: 'organizer' | 'member'
}

interface TripDetails {
  id: string
  title: string
  description: string
  location: string
  startDate: string
  endDate: string
  organizer: string
}

interface InvitationData {
  tripId: string
  recipientEmail: string
  recipientName: string
  personalMessage?: string
  includeCalendarEvent: boolean
  reminderEnabled: boolean
  reminderDays: number
}

interface InvitationStatus {
  id: string
  email: string
  name: string
  status: 'pending' | 'accepted' | 'declined' | 'expired'
  sentAt: string
  respondedAt?: string
}

interface InvitationServiceProps {
  tripDetails: TripDetails
  members: TripMember[]
  onInvitationSent: (invitation: InvitationStatus) => void
  onBulkInvite: (invitations: InvitationStatus[]) => void
}

export default function InvitationService({
  tripDetails,
  members,
  onInvitationSent,
  onBulkInvite
}: InvitationServiceProps) {
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [newMemberEmail, setNewMemberEmail] = useState('')
  const [newMemberName, setNewMemberName] = useState('')
  const [personalMessage, setPersonalMessage] = useState('')
  const [includeCalendar, setIncludeCalendar] = useState(true)
  const [reminderEnabled, setReminderEnabled] = useState(true)
  const [reminderDays, setReminderDays] = useState(3)
  const [isLoading, setIsLoading] = useState(false)
  const [invitationStatuses, setInvitationStatuses] = useState<InvitationStatus[]>([])

  const handleMemberToggle = useCallback((memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }, [])

  const handleSelectAll = useCallback(() => {
    const allMemberIds = members.filter(m => m.role !== 'organizer').map(m => m.id)
    setSelectedMembers(prev => 
      prev.length === allMemberIds.length ? [] : allMemberIds
    )
  }, [members])

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  const sendSingleInvitation = async (invitationData: InvitationData): Promise<InvitationStatus> => {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1000))

    const invitation: InvitationStatus = {
      id: `inv_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      email: invitationData.recipientEmail,
      name: invitationData.recipientName,
      status: 'pending',
      sentAt: new Date().toISOString()
    }

    return invitation
  }

  const handleSendToSelected = async () => {
    if (selectedMembers.length === 0) {
      toast.error('Please select at least one member to invite')
      return
    }

    setIsLoading(true)
    try {
      const selectedMemberData = members.filter(m => selectedMembers.includes(m.id))
      const invitations: InvitationStatus[] = []

      for (const member of selectedMemberData) {
        const invitationData: InvitationData = {
          tripId: tripDetails.id,
          recipientEmail: member.email,
          recipientName: member.name,
          personalMessage,
          includeCalendarEvent: includeCalendar,
          reminderEnabled,
          reminderDays
        }

        const invitation = await sendSingleInvitation(invitationData)
        invitations.push(invitation)
      }

      setInvitationStatuses(prev => [...prev, ...invitations])
      onBulkInvite(invitations)
      setSelectedMembers([])
      setPersonalMessage('')

      toast.success(`Invitations sent to ${invitations.length} members`)
    } catch (error) {
      toast.error('Failed to send invitations. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleSendToNewMember = async () => {
    if (!newMemberEmail || !newMemberName) {
      toast.error('Please enter both name and email')
      return
    }

    if (!validateEmail(newMemberEmail)) {
      toast.error('Please enter a valid email address')
      return
    }

    setIsLoading(true)
    try {
      const invitationData: InvitationData = {
        tripId: tripDetails.id,
        recipientEmail: newMemberEmail,
        recipientName: newMemberName,
        personalMessage,
        includeCalendarEvent: includeCalendar,
        reminderEnabled,
        reminderDays
      }

      const invitation = await sendSingleInvitation(invitationData)
      setInvitationStatuses(prev => [...prev, invitation])
      onInvitationSent(invitation)

      setNewMemberEmail('')
      setNewMemberName('')
      setPersonalMessage('')

      toast.success(`Invitation sent to ${newMemberName}`)
    } catch (error) {
      toast.error('Failed to send invitation. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusIcon = (status: InvitationStatus['status']) => {
    switch (status) {
      case 'accepted':
        return <CheckCircle className="h-4 w-4 text-[rgb(34,139,34)]" />
      case 'declined':
        return <XCircle className="h-4 w-4 text-[rgb(239,68,68)]" />
      case 'expired':
        return <AlertCircle className="h-4 w-4 text-[rgb(245,158,11)]" />
      default:
        return <Clock className="h-4 w-4 text-[rgb(100,116,139)]" />
    }
  }

  const getStatusColor = (status: InvitationStatus['status']) => {
    switch (status) {
      case 'accepted':
        return 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
      case 'declined':
        return 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]'
      case 'expired':
        return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const existingMembers = members.filter(m => m.role !== 'organizer')
  const allSelected = selectedMembers.length === existingMembers.length

  return (
    <div className="space-y-6 p-4 max-w-4xl mx-auto">
      {/* Trip Overview */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader className="pb-4">
          <CardTitle className="text-xl font-semibold text-[rgb(15,23,42)] flex items-center gap-2">
            <MapPin className="h-5 w-5 text-[rgb(34,139,34)]" />
            {tripDetails.title}
          </CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            {tripDetails.description}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
            <Calendar className="h-4 w-4" />
            <span>
              {new Date(tripDetails.startDate).toLocaleDateString()} - {new Date(tripDetails.endDate).toLocaleDateString()}
            </span>
          </div>
          <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
            <MapPin className="h-4 w-4" />
            <span>{tripDetails.location}</span>
          </div>
        </CardContent>
      </Card>

      {/* Invite Existing Members */}
      {existingMembers.length > 0 && (
        <Card className="border-[rgb(226,232,240)] shadow-md">
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)] flex items-center gap-2">
              <Users className="h-5 w-5 text-[rgb(34,139,34)]" />
              Invite Existing Members
            </CardTitle>
            <CardDescription className="text-[rgb(100,116,139)]">
              Select members to send trip invitations
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <Button
                variant="outline"
                size="sm"
                onClick={handleSelectAll}
                className="border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)]"
              >
                {allSelected ? 'Deselect All' : 'Select All'}
              </Button>
              <span className="text-sm text-[rgb(100,116,139)]">
                {selectedMembers.length} of {existingMembers.length} selected
              </span>
            </div>

            <div className="grid gap-3 max-h-64 overflow-y-auto">
              {existingMembers.map((member) => (
                <div
                  key={member.id}
                  className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-colors ${
                    selectedMembers.includes(member.id)
                      ? 'border-[rgb(34,139,34)] bg-[rgb(248,250,252)]'
                      : 'border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)]'
                  }`}
                  onClick={() => handleMemberToggle(member.id)}
                  role="checkbox"
                  aria-checked={selectedMembers.includes(member.id)}
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault()
                      handleMemberToggle(member.id)
                    }
                  }}
                >
                  <div>
                    <p className="font-medium text-[rgb(15,23,42)]">{member.name}</p>
                    <p className="text-sm text-[rgb(100,116,139)]">{member.email}</p>
                  </div>
                  <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                    selectedMembers.includes(member.id)
                      ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]'
                      : 'border-[rgb(226,232,240)]'
                  }`}>
                    {selectedMembers.includes(member.id) && (
                      <CheckCircle className="h-3 w-3 text-white" />
                    )}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Invite New Member */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader>
          <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)]">
            Invite New Member
          </CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            Add someone new to the trip
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="new-member-name" className="text-sm font-medium text-[rgb(15,23,42)]">
                Name
              </Label>
              <Input
                id="new-member-name"
                value={newMemberName}
                onChange={(e) => setNewMemberName(e.target.value)}
                placeholder="Enter member name"
                className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="new-member-email" className="text-sm font-medium text-[rgb(15,23,42)]">
                Email
              </Label>
              <Input
                id="new-member-email"
                type="email"
                value={newMemberEmail}
                onChange={(e) => setNewMemberEmail(e.target.value)}
                placeholder="Enter email address"
                className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Invitation Settings */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader>
          <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)]">
            Invitation Settings
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="personal-message" className="text-sm font-medium text-[rgb(15,23,42)]">
              Personal Message (Optional)
            </Label>
            <Textarea
              id="personal-message"
              value={personalMessage}
              onChange={(e) => setPersonalMessage(e.target.value)}
              placeholder="Add a personal note to the invitation..."
              className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[80px]"
              maxLength={500}
            />
            <p className="text-xs text-[rgb(100,116,139)]">
              {personalMessage.length}/500 characters
            </p>
          </div>

          <div className="flex items-center justify-between">
            <div className="space-y-1">
              <Label className="text-sm font-medium text-[rgb(15,23,42)]">
                Include Calendar Event
              </Label>
              <p className="text-xs text-[rgb(100,116,139)]">
                Automatically add trip dates to their calendar
              </p>
            </div>
            <Switch
              checked={includeCalendar}
              onCheckedChange={setIncludeCalendar}
              className="data-[state=checked]:bg-[rgb(34,139,34)]"
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="space-y-1">
              <Label className="text-sm font-medium text-[rgb(15,23,42)]">
                Send Reminder
              </Label>
              <p className="text-xs text-[rgb(100,116,139)]">
                Send a reminder before the trip
              </p>
            </div>
            <Switch
              checked={reminderEnabled}
              onCheckedChange={setReminderEnabled}
              className="data-[state=checked]:bg-[rgb(34,139,34)]"
            />
          </div>

          {reminderEnabled && (
            <div className="space-y-2">
              <Label htmlFor="reminder-days" className="text-sm font-medium text-[rgb(15,23,42)]">
                Reminder Days Before Trip
              </Label>
              <Input
                id="reminder-days"
                type="number"
                min="1"
                max="30"
                value={reminderDays}
                onChange={(e) => setReminderDays(parseInt(e.target.value) || 3)}
                className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 w-24"
              />
            </div>
          )}
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <div className="flex flex-col sm:flex-row gap-3">
        {selectedMembers.length > 0 && (
          <Button
            onClick={handleSendToSelected}
            disabled={isLoading}
            className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white font-medium min-h-[44px] flex-1"
          >
            <Send className="h-4 w-4 mr-2" />
            {isLoading ? 'Sending...' : `Send to ${selectedMembers.length} Selected`}
          </Button>
        )}

        {newMemberEmail && newMemberName && (
          <Button
            onClick={handleSendToNewMember}
            disabled={isLoading}
            variant="outline"
            className="border-[rgb(34,139,34)] text-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)] hover:text-white font-medium min-h-[44px] flex-1"
          >
            <Send className="h-4 w-4 mr-2" />
            {isLoading ? 'Sending...' : 'Send to New Member'}
          </Button>
        )}
      </div>

      {/* Invitation Status */}
      {invitationStatuses.length > 0 && (
        <Card className="border-[rgb(226,232,240)] shadow-md">
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)]">
              Invitation Status
            </CardTitle>
            <CardDescription className="text-[rgb(100,116,139)]">
              Track responses to your invitations
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {invitationStatuses.map((invitation) => (
                <div
                  key={invitation.id}
                  className="flex items-center justify-between p-3 rounded-lg border border-[rgb(226,232,240)]"
                >
                  <div className="flex items-center gap-3">
                    {getStatusIcon(invitation.status)}
                    <div>
                      <p className="font-medium text-[rgb(15,23,42)]">{invitation.name}</p>
                      <p className="text-sm text-[rgb(100,116,139)]">{invitation.email}</p>
                    </div>
                  </div>
                  <Badge className={`${getStatusColor(invitation.status)} font-medium`}>
                    {invitation.status.charAt(0).toUpperCase() + invitation.status.slice(1)}
                  </Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/use-toast';
import { MapPin, Star, Search, Heart, Navigation, Wifi, WifiOff } from 'lucide-react';

interface Location {
  id: string;
  name: string;
  coordinates: {
    lat: number;
    lng: number;
  };
  address: string;
  terrain: 'easy' | 'moderate' | 'difficult' | 'extreme';
  difficulty: number; // 1-10 scale
  description: string;
  amenities: string[];
  rating: number;
  reviews: number;
  distance?: number; // in miles
  isFavorite: boolean;
  tags: string[];
  images: string[];
  weatherInfo?: {
    temperature: number;
    condition: string;
    humidity: number;
  };
}

interface LocationSearchFilters {
  terrain?: string;
  maxDifficulty?: number;
  maxDistance?: number;
  amenities?: string[];
}

interface LocationServiceProps {
  onLocationSelect?: (location: Location) => void;
  showFavoritesOnly?: boolean;
  enableSearch?: boolean;
  className?: string;
}

const MOCK_LOCATIONS: Location[] = [
  {
    id: '1',
    name: 'Moab Desert Trail',
    coordinates: { lat: 38.5733, lng: -109.5498 },
    address: 'Moab, UT 84532',
    terrain: 'difficult',
    difficulty: 7,
    description: 'Challenging desert terrain with stunning red rock formations and technical obstacles.',
    amenities: ['Camping', 'Restrooms', 'Water'],
    rating: 4.8,
    reviews: 324,
    isFavorite: true,
    tags: ['desert', 'technical', 'scenic'],
    images: ['/images/moab-1.jpg'],
    weatherInfo: {
      temperature: 75,
      condition: 'Sunny',
      humidity: 25
    }
  },
  {
    id: '2',
    name: 'Pine Ridge Forest',
    coordinates: { lat: 40.7589, lng: -111.8883 },
    address: 'Salt Lake City, UT 84101',
    terrain: 'moderate',
    difficulty: 4,
    description: 'Beautiful forest trails with moderate elevation changes and creek crossings.',
    amenities: ['Camping', 'Fire Pits', 'Hiking Trails'],
    rating: 4.5,
    reviews: 156,
    isFavorite: false,
    tags: ['forest', 'family-friendly', 'water'],
    images: ['/images/pine-ridge-1.jpg'],
    weatherInfo: {
      temperature: 68,
      condition: 'Partly Cloudy',
      humidity: 45
    }
  },
  {
    id: '3',
    name: 'Rocky Mountain Pass',
    coordinates: { lat: 39.7392, lng: -104.9903 },
    address: 'Denver, CO 80202',
    terrain: 'extreme',
    difficulty: 9,
    description: 'Expert-level mountain terrain with steep climbs and technical rock sections.',
    amenities: ['Emergency Services', 'Parking'],
    rating: 4.9,
    reviews: 89,
    isFavorite: true,
    tags: ['mountain', 'expert', 'challenging'],
    images: ['/images/rocky-mountain-1.jpg'],
    weatherInfo: {
      temperature: 52,
      condition: 'Cloudy',
      humidity: 65
    }
  }
];

const TERRAIN_COLORS = {
  easy: 'bg-green-100 text-green-800',
  moderate: 'bg-yellow-100 text-yellow-800',
  difficult: 'bg-orange-100 text-orange-800',
  extreme: 'bg-red-100 text-red-800'
};

export default function LocationService({
  onLocationSelect,
  showFavoritesOnly = false,
  enableSearch = true,
  className = ''
}: LocationServiceProps) {
  const [locations, setLocations] = useState<Location[]>(MOCK_LOCATIONS);
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(MOCK_LOCATIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [filters, setFilters] = useState<LocationSearchFilters>({});
  const [isLoading, setIsLoading] = useState(false);
  const [isOnline, setIsOnline] = useState(true);
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null);

  // Check online status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Get user location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
        },
        (error) => {
          console.warn('Location access denied:', error);
        }
      );
    }
  }, []);

  // Calculate distance between two coordinates
  const calculateDistance = useCallback((lat1: number, lng1: number, lat2: number, lng2: number): number => {
    const R = 3959; // Earth's radius in miles
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLng = (lng2 - lng1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLng / 2) * Math.sin(dLng / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }, []);

  // Update locations with distances
  useEffect(() => {
    if (userLocation) {
      const locationsWithDistance = locations.map(location => ({
        ...location,
        distance: calculateDistance(
          userLocation.lat,
          userLocation.lng,
          location.coordinates.lat,
          location.coordinates.lng
        )
      }));
      setLocations(locationsWithDistance);
    }
  }, [userLocation, calculateDistance]);

  // Filter and search locations
  useEffect(() => {
    let filtered = [...locations];

    // Apply favorites filter
    if (showFavoritesOnly) {
      filtered = filtered.filter(location => location.isFavorite);
    }

    // Apply search query
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(location =>
        location.name.toLowerCase().includes(query) ||
        location.address.toLowerCase().includes(query) ||
        location.tags.some(tag => tag.toLowerCase().includes(query))
      );
    }

    // Apply terrain filter
    if (filters.terrain) {
      filtered = filtered.filter(location => location.terrain === filters.terrain);
    }

    // Apply difficulty filter
    if (filters.maxDifficulty) {
      filtered = filtered.filter(location => location.difficulty <= filters.maxDifficulty);
    }

    // Apply distance filter
    if (filters.maxDistance && userLocation) {
      filtered = filtered.filter(location => 
        location.distance ? location.distance <= filters.maxDistance! : true
      );
    }

    // Sort by distance if available, then by rating
    filtered.sort((a, b) => {
      if (a.distance && b.distance) {
        return a.distance - b.distance;
      }
      return b.rating - a.rating;
    });

    setFilteredLocations(filtered);
  }, [locations, searchQuery, filters, showFavoritesOnly, userLocation]);

  const handleSearch = useCallback((query: string) => {
    setSearchQuery(query);
  }, []);

  const toggleFavorite = useCallback(async (locationId: string) => {
    try {
      setLocations(prev => prev.map(location =>
        location.id === locationId
          ? { ...location, isFavorite: !location.isFavorite }
          : location
      ));

      // Optimistic update
      const location = locations.find(l => l.id === locationId);
      if (location) {
        toast({
          title: location.isFavorite ? 'Removed from favorites' : 'Added to favorites',
          description: location.name,
        });
      }

      // Simulate API call
      if (isOnline) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    } catch (error) {
      // Revert on error
      setLocations(prev => prev.map(location =>
        location.id === locationId
          ? { ...location, isFavorite: !location.isFavorite }
          : location
      ));

      toast({
        title: 'Error',
        description: 'Failed to update favorite status',
        variant: 'destructive',
      });
    }
  }, [locations, isOnline]);

  const handleLocationSelect = useCallback((location: Location) => {
    onLocationSelect?.(location);
    toast({
      title: 'Location selected',
      description: location.name,
    });
  }, [onLocationSelect]);

  const getDifficultyColor = (difficulty: number): string => {
    if (difficulty <= 3) return 'text-green-600';
    if (difficulty <= 6) return 'text-yellow-600';
    if (difficulty <= 8) return 'text-orange-600';
    return 'text-[rgb(255, 255, 255)]';
  };

  return (
    <div className={`w-full space-y-4 ${className}`}>
      {/* Online Status Indicator */}
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">
          {showFavoritesOnly ? 'Favorite Locations' : 'Discover Locations'}
        </h2>
        <div className="flex items-center gap-2">
          {isOnline ? (
            <Wifi className="w-4 h-4 text-[rgb(34,139,34)]" aria-label="Online" />
          ) : (
            <WifiOff className="w-4 h-4 text-[rgb(239,68,68)]" aria-label="Offline" />
          )}
          <span className="text-sm text-[rgb(100,116,139)]">
            {isOnline ? 'Online' : 'Offline'}
          </span>
        </div>
      </div>

      {/* Search Bar */}
      {enableSearch && (
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(100,116,139)]" />
          <Input
            type="text"
            placeholder="Search locations, terrain, or tags..."
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            className="pl-10 h-12 text-base border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            aria-label="Search locations"
          />
        </div>
      )}

      {/* Quick Filters */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {['easy', 'moderate', 'difficult', 'extreme'].map((terrain) => (
          <Button
            key={terrain}
            variant={filters.terrain === terrain ? 'default' : 'outline'}
            size="sm"
            onClick={() => setFilters(prev => ({
              ...prev,
              terrain: prev.terrain === terrain ? undefined : terrain
            }))}
            className={`whitespace-nowrap capitalize min-h-[44px] ${
              filters.terrain === terrain 
                ? 'bg-[rgb(34,139,34)] text-white' 
                : 'border-[rgb(226,232,240)] text-[rgb(15,23,42)]'
            }`}
          >
            {terrain}
          </Button>
        ))}
      </div>

      {/* Loading State */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <Card key={i} className="p-4 animate-pulse">
              <div className="space-y-3">
                <div className="h-4 bg-[rgb(241,245,249)] rounded w-3/4"></div>
                <div className="h-3 bg-[rgb(241,245,249)] rounded w-1/2"></div>
                <div className="flex gap-2">
                  <div className="h-6 bg-[rgb(241,245,249)] rounded w-16"></div>
                  <div className="h-6 bg-[rgb(241,245,249)] rounded w-20"></div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}

      {/* Locations List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredLocations.length === 0 ? (
            <Card className="p-8 text-center border-[rgb(226,232,240)]">
              <MapPin className="w-12 h-12 mx-auto mb-4 text-[rgb(148,163,184)]" />
              <h3 className="text-lg font-medium text-[rgb(15,23,42)] mb-2">
                No locations found
              </h3>
              <p className="text-[rgb(100,116,139)] mb-4">
                {searchQuery 
                  ? 'Try adjusting your search or filters'
                  : 'Start exploring by searching for locations'
                }
              </p>
              {searchQuery && (
                <Button
                  variant="outline"
                  onClick={() => {
                    setSearchQuery('');
                    setFilters({});
                  }}
                  className="border-[rgb(226,232,240)] text-[rgb(15,23,42)]"
                >
                  Clear search
                </Button>
              )}
            </Card>
          ) : (
            filteredLocations.map((location) => (
              <Card 
                key={location.id} 
                className="p-4 border-[rgb(226,232,240)] hover:shadow-md transition-shadow cursor-pointer"
                onClick={() => handleLocationSelect(location)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleLocationSelect(location);
                  }
                }}
                aria-label={`Select ${location.name}`}
              >
                <div className="space-y-3">
                  {/* Header */}
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <h3 className="font-semibold text-[rgb(15,23,42)] text-lg">
                        {location.name}
                      </h3>
                      <p className="text-[rgb(100,116,139)] text-sm flex items-center gap-1">
                        <MapPin className="w-3 h-3" />
                        {location.address}
                        {location.distance && (
                          <span className="ml-2">• {location.distance.toFixed(1)} mi</span>
                        )}
                      </p>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleFavorite(location.id);
                      }}
                      className="p-2 min-h-[44px] min-w-[44px]"
                      aria-label={location.isFavorite ? 'Remove from favorites' : 'Add to favorites'}
                    >
                      <Heart 
                        className={`w-5 h-5 ${
                          location.isFavorite 
                            ? 'fill-[rgb(239,68,68)] text-[rgb(239,68,68)]' 
                            : 'text-[rgb(148,163,184)]'
                        }`} 
                      />
                    </Button>
                  </div>

                  {/* Description */}
                  <p className="text-[rgb(71,85,105)] text-sm">
                    {location.description}
                  </p>

                  {/* Badges */}
                  <div className="flex flex-wrap gap-2">
                    <Badge className={`${TERRAIN_COLORS[location.terrain]} border-0`}>
                      {location.terrain}
                    </Badge>
                    <Badge variant="outline" className="border-[rgb(226,232,240)]">
                      <span className={`font-medium ${getDifficultyColor(location.difficulty)}`}>
                        Difficulty {location.difficulty}/10
                      </span>
                    </Badge>
                    {location.weatherInfo && (
                      <Badge variant="outline" className="border-[rgb(226,232,240)]">
                        {location.weatherInfo.temperature}°F • {location.weatherInfo.condition}
                      </Badge>
                    )}
                  </div>

                  {/* Rating and Reviews */}
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-1">
                      <Star className="w-4 h-4 fill-[rgb(245,158,11)] text-[rgb(245,158,11)]" />
                      <span className="font-medium text-[rgb(15,23,42)]">
                        {location.rating}
                      </span>
                      <span className="text-[rgb(100,116,139)] text-sm">
                        ({location.reviews} reviews)
                      </span>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        // Open navigation app
                        const url = `https://maps.google.com/?q=${location.coordinates.lat},${location.coordinates.lng}`;
                        window.open(url, '_blank');
                      }}
                      className="border-[rgb(226,232,240)] text-[rgb(15,23,42)] min-h-[44px]"
                      aria-label={`Get directions to ${location.name}`}
                    >
                      <Navigation className="w-4 h-4 mr-1" />
                      Directions
                    </Button>
                  </div>

                  {/* Amenities */}
                  {location.amenities.length > 0 && (
                    <div className="flex flex-wrap gap-1">
                      {location.amenities.map((amenity) => (
                        <span
                          key={amenity}
                          className="text-xs px-2 py-1 bg-[rgb(241,245,249)] text-[rgb(71,85,105)] rounded"
                        >
                          {amenity}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </Card>
            ))
          )}
        </div>
      )}
    </div>
  );
}

