'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface CalendarEvent {
  id: string;
  title: string;
  start: Date;
  end: Date;
  description?: string;
  location?: string;
  attendees?: string[];
  source: 'google' | 'outlook' | 'apple' | 'local';
  externalId?: string;
}

interface CalendarIntegration {
  id: string;
  provider: 'google' | 'outlook' | 'apple';
  email: string;
  accessToken: string;
  refreshToken?: string;
  isActive: boolean;
  lastSync: Date;
}

interface CalendarAvailability {
  userId: string;
  email: string;
  name: string;
  isAvailable: boolean;
  conflictingEvents: CalendarEvent[];
}

interface CalendarAPIProps {
  onEventsLoaded?: (events: CalendarEvent[]) => void;
  onAvailabilityChecked?: (availability: CalendarAvailability[]) => void;
  onError?: (error: string) => void;
}

interface CalendarAPIReturn {
  events: CalendarEvent[];
  integrations: CalendarIntegration[];
  isLoading: boolean;
  error: string | null;
  connectCalendar: (provider: 'google' | 'outlook' | 'apple') => Promise<void>;
  disconnectCalendar: (integrationId: string) => Promise<void>;
  syncCalendars: () => Promise<void>;
  checkAvailability: (startDate: Date, endDate: Date, userEmails: string[]) => Promise<CalendarAvailability[]>;
  createEvent: (event: Omit<CalendarEvent, 'id' | 'source'>) => Promise<CalendarEvent>;
  sendInvites: (eventId: string, attendeeEmails: string[]) => Promise<void>;
  refreshIntegration: (integrationId: string) => Promise<void>;
}

// Google Calendar API helpers
const GOOGLE_CALENDAR_SCOPE = 'https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/calendar.events';
const GOOGLE_CLIENT_ID = process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID;

// Microsoft Graph API helpers
const MICROSOFT_SCOPE = 'https://graph.microsoft.com/calendars.read https://graph.microsoft.com/calendars.readwrite';
const MICROSOFT_CLIENT_ID = process.env.NEXT_PUBLIC_MICROSOFT_CLIENT_ID;

export function useCalendarAPI({
  onEventsLoaded,
  onAvailabilityChecked,
  onError
}: CalendarAPIProps = {}): CalendarAPIReturn {
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [integrations, setIntegrations] = useState<CalendarIntegration[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const supabase = createClientComponentClient();

  // Load integrations on mount
  useEffect(() => {
    loadIntegrations();
  }, []);

  // Load events when integrations change
  useEffect(() => {
    if (integrations.length > 0) {
      syncCalendars();
    }
  }, [integrations]);

  const handleError = useCallback((errorMessage: string) => {
    setError(errorMessage);
    onError?.(errorMessage);
  }, [onError]);

  const loadIntegrations = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from('calendar_integrations')
        .select('*')
        .eq('user_id', user.id)
        .eq('is_active', true);

      if (error) throw error;

      setIntegrations(data || []);
    } catch (err) {
      handleError('Failed to load calendar integrations');
    }
  };

  const connectCalendar = async (provider: 'google' | 'outlook' | 'apple') => {
    setIsLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('User not authenticated');

      if (provider === 'google') {
        await connectGoogleCalendar(user.id);
      } else if (provider === 'outlook') {
        await connectOutlookCalendar(user.id);
      } else if (provider === 'apple') {
        await connectAppleCalendar(user.id);
      }

      await loadIntegrations();
    } catch (err) {
      handleError(`Failed to connect ${provider} calendar: ${err instanceof Error ? err.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const connectGoogleCalendar = async (userId: string) => {
    if (!GOOGLE_CLIENT_ID) {
      throw new Error('Google Client ID not configured');
    }

    return new Promise<void>((resolve, reject) => {
      // Load Google API
      const script = document.createElement('script');
      script.src = 'https://apis.google.com/js/api.js';
      script.onload = () => {
        window.gapi.load('auth2', async () => {
          try {
            const authInstance = window.gapi.auth2.init({
              client_id: GOOGLE_CLIENT_ID,
              scope: GOOGLE_CALENDAR_SCOPE
            });

            const authResult = await authInstance.signIn();
            const authResponse = authResult.getAuthResponse();

            // Get user profile
            await window.gapi.load('client');
            await window.gapi.client.init({
              apiKey: process.env.NEXT_PUBLIC_GOOGLE_API_KEY,
              clientId: GOOGLE_CLIENT_ID,
              scope: GOOGLE_CALENDAR_SCOPE
            });

            const profile = authResult.getBasicProfile();

            // Save integration to database
            const { error } = await supabase
              .from('calendar_integrations')
              .insert({
                user_id: userId,
                provider: 'google',
                email: profile.getEmail(),
                access_token: authResponse.access_token,
                refresh_token: authResponse.refresh_token,
                is_active: true,
                last_sync: new Date().toISOString()
              });

            if (error) throw error;
            resolve();
          } catch (err) {
            reject(err);
          }
        });
      };
      script.onerror = () => reject(new Error('Failed to load Google API'));
      document.head.appendChild(script);
    });
  };

  const connectOutlookCalendar = async (userId: string) => {
    if (!MICROSOFT_CLIENT_ID) {
      throw new Error('Microsoft Client ID not configured');
    }

    // Use Microsoft Authentication Library (MSAL)
    const redirectUri = `${window.location.origin}/auth/microsoft/callback`;
    const authUrl = `https://login.microsoftonline.com/common/oauth2/v2.0/authorize?` +
      `client_id=${MICROSOFT_CLIENT_ID}&` +
      `response_type=code&` +
      `redirect_uri=${encodeURIComponent(redirectUri)}&` +
      `scope=${encodeURIComponent(MICROSOFT_SCOPE)}&` +
      `response_mode=query`;

    // Open popup for authentication
    const popup = window.open(authUrl, 'microsoft-auth', 'width=500,height=600');

    return new Promise<void>((resolve, reject) => {
      const checkClosed = setInterval(() => {
        if (popup?.closed) {
          clearInterval(checkClosed);
          reject(new Error('Authentication cancelled'));
        }
      }, 1000);

      // Listen for message from popup
      const messageHandler = async (event: MessageEvent) => {
        if (event.origin !== window.location.origin) return;

        if (event.data.type === 'MICROSOFT_AUTH_SUCCESS') {
          clearInterval(checkClosed);
          popup?.close();
          window.removeEventListener('message', messageHandler);

          try {
            // Save integration to database
            const { error } = await supabase
              .from('calendar_integrations')
              .insert({
                user_id: userId,
                provider: 'outlook',
                email: event.data.email,
                access_token: event.data.accessToken,
                refresh_token: event.data.refreshToken,
                is_active: true,
                last_sync: new Date().toISOString()
              });

            if (error) throw error;
            resolve();
          } catch (err) {
            reject(err);
          }
        } else if (event.data.type === 'MICROSOFT_AUTH_ERROR') {
          clearInterval(checkClosed);
          popup?.close();
          window.removeEventListener('message', messageHandler);
          reject(new Error(event.data.error));
        }
      };

      window.addEventListener('message', messageHandler);
    });
  };

  const connectAppleCalendar = async (userId: string) => {
    // Apple Calendar integration would require EventKit framework
    // For web, we'd need to use CalDAV or similar protocol
    throw new Error('Apple Calendar integration not yet implemented for web');
  };

  const disconnectCalendar = async (integrationId: string) => {
    setIsLoading(true);
    setError(null);

    try {
      const { error } = await supabase
        .from('calendar_integrations')
        .update({ is_active: false })
        .eq('id', integrationId);

      if (error) throw error;

      await loadIntegrations();
    } catch (err) {
      handleError('Failed to disconnect calendar');
    } finally {
      setIsLoading(false);
    }
  };

  const syncCalendars = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const allEvents: CalendarEvent[] = [];

      for (const integration of integrations) {
        if (!integration.isActive) continue;

        let events: CalendarEvent[] = [];

        if (integration.provider === 'google') {
          events = await syncGoogleCalendar(integration);
        } else if (integration.provider === 'outlook') {
          events = await syncOutlookCalendar(integration);
        }

        allEvents.push(...events);
      }

      setEvents(allEvents);
      onEventsLoaded?.(allEvents);
    } catch (err) {
      handleError('Failed to sync calendars');
    } finally {
      setIsLoading(false);
    }
  };

  const syncGoogleCalendar = async (integration: CalendarIntegration): Promise<CalendarEvent[]> => {
    try {
      const response = await fetch(`https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${new Date().toISOString()}`, {
        headers: {
          'Authorization': `Bearer ${integration.accessToken}`
        }
      });

      if (!response.ok) {
        if (response.status === 401) {
          await refreshIntegration(integration.id);
          return [];
        }
        throw new Error('Failed to fetch Google Calendar events');
      }

      const data = await response.json();

      return data.items?.map((item: any) => ({
        id: item.id,
        title: item.summary || 'Untitled Event',
        start: new Date(item.start.dateTime || item.start.date),
        end: new Date(item.end.dateTime || item.end.date),
        description: item.description,
        location: item.location,
        attendees: item.attendees?.map((a: any) => a.email) || [],
        source: 'google' as const,
        externalId: item.id
      })) || [];
    } catch (err) {
      console.error('Google Calendar sync error:', err);
      return [];
    }
  };

  const syncOutlookCalendar = async (integration: CalendarIntegration): Promise<CalendarEvent[]> => {
    try {
      const response = await fetch('https://graph.microsoft.com/v1.0/me/events', {
        headers: {
          'Authorization': `Bearer ${integration.accessToken}`
        }
      });

      if (!response.ok) {
        if (response.status === 401) {
          await refreshIntegration(integration.id);
          return [];
        }
        throw new Error('Failed to fetch Outlook Calendar events');
      }

      const data = await response.json();

      return data.value?.map((item: any) => ({
        id: item.id,
        title: item.subject || 'Untitled Event',
        start: new Date(item.start.dateTime),
        end: new Date(item.end.dateTime),
        description: item.body?.content,
        location: item.location?.displayName,
        attendees: item.attendees?.map((a: any) => a.emailAddress.address) || [],
        source: 'outlook' as const,
        externalId: item.id
      })) || [];
    } catch (err) {
      console.error('Outlook Calendar sync error:', err);
      return [];
    }
  };

  const refreshIntegration = async (integrationId: string) => {
    try {
      const integration = integrations.find(i => i.id === integrationId);
      if (!integration?.refreshToken) return;

      let newAccessToken = '';

      if (integration.provider === 'google') {
        const response = await fetch('https://oauth2.googleapis.com/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            client_id: GOOGLE_CLIENT_ID!,
            client_secret: process.env.NEXT_PUBLIC_GOOGLE_CLIENT_SECRET!,
            refresh_token: integration.refreshToken,
            grant_type: 'refresh_token'
          })
        });

        const data = await response.json();
        newAccessToken = data.access_token;
      } else if (integration.provider === 'outlook') {
        const response = await fetch('https://login.microsoftonline.com/common/oauth2/v2.0/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            client_id: MICROSOFT_CLIENT_ID!,
            client_secret: process.env.NEXT_PUBLIC_MICROSOFT_CLIENT_SECRET!,
            refresh_token: integration.refreshToken,
            grant_type: 'refresh_token',
            scope: MICROSOFT_SCOPE
          })
        });

        const data = await response.json();
        newAccessToken = data.access_token;
      }

      if (newAccessToken) {
        const { error } = await supabase
          .from('calendar_integrations')
          .update({ 
            access_token: newAccessToken,
            last_sync: new Date().toISOString()
          })
          .eq('id', integrationId);

        if (error) throw error;
        await loadIntegrations();
      }
    } catch (err) {
      console.error('Failed to refresh integration:', err);
    }
  };

  const checkAvailability = async (
    startDate: Date, 
    endDate: Date, 
    userEmails: string[]
  ): Promise<CalendarAvailability[]> => {
    setIsLoading(true);
    setError(null);

    try {
      const availability: CalendarAvailability[] = [];

      for (const email of userEmails) {
        const userEvents = events.filter(event => 
          event.attendees?.includes(email) &&
          event.start < endDate &&
          event.end > startDate
        );

        const isAvailable = userEvents.length === 0;

        availability.push({
          userId: email, // Using email as userId for simplicity
          email,
          name: email.split('@')[0], // Extract name from email
          isAvailable,
          conflictingEvents: userEvents
        });
      }

      onAvailabilityChecked?.(availability);
      return availability;
    } catch (err) {
      handleError('Failed to check availability');
      return [];
    } finally {
      setIsLoading(false);
    }
  };

  const createEvent = async (eventData: Omit<CalendarEvent, 'id' | 'source'>): Promise<CalendarEvent> => {
    setIsLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('User not authenticated');

      // Create event in local database first
      const { data, error } = await supabase
        .from('trip_events')
        .insert({
          user_id: user.id,
          title: eventData.title,
          start_date: eventData.start.toISOString(),
          end_date: eventData.end.toISOString(),
          description: eventData.description,
          location: eventData.location,
          attendees: eventData.attendees || []
        })
        .select()
        .single();

      if (error) throw error;

      const newEvent: CalendarEvent = {
        id: data.id,
        title: data.title,
        start: new Date(data.start_date),
        end: new Date(data.end_date),
        description: data.description,
        location: data.location,
        attendees: data.attendees,
        source: 'local'
      };

      // Try to create in external calendars
      for (const integration of integrations) {
        try {
          if (integration.provider === 'google') {
            await createGoogleCalendarEvent(integration, newEvent);
          } else if (integration.provider === 'outlook') {
            await createOutlookCalendarEvent(integration, newEvent);
          }
        } catch (err) {
          console.error(`Failed to create event in ${integration.provider}:`, err);
        }
      }

      setEvents(prev => [...prev, newEvent]);
      return newEvent;
    } catch (err) {
      handleError('Failed to create event');
      throw err;
    } finally {
      setIsLoading(false);
    }
  };

  const createGoogleCalendarEvent = async (integration: CalendarIntegration, event: CalendarEvent) => {
    const response = await fetch('https://www.googleapis.com/calendar/v3/calendars/primary/events', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${integration.accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        summary: event.title,
        description: event.description,
        location: event.location,
        start: {
          dateTime: event.start.toISOString(),
          timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        end: {
          dateTime: event.end.toISOString(),
          timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        attendees: event.attendees?.map(email => ({ email }))
      })
    });

    if (!response.ok) {
      throw new Error('Failed to create Google Calendar event');
    }
  };

  const createOutlookCalendarEvent = async (integration: CalendarIntegration, event: CalendarEvent) => {
    const response = await fetch('https://graph.microsoft.com/v1.0/me/events', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${integration.accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        subject: event.title,
        body: {
          contentType: 'text',
          content: event.description || ''
        },
        location: {
          displayName: event.location || ''
        },
        start: {
          dateTime: event.start.toISOString(),
          timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        end: {
          dateTime: event.end.toISOString(),
          timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        attendees: event.attendees?.map(email => ({
          emailAddress: { address: email, name: email.split('@')[0] }
        }))
      })
    });

    if (!response.ok) {
      throw new Error('Failed to create Outlook Calendar event');
    }
  };

  const sendInvites = async (eventId: string, attendeeEmails: string[]) => {
    setIsLoading(true);
    setError(null);

    try {
      // Send invites through external calendar providers
      for (const integration of integrations) {
        try {
          if (integration.provider === 'google') {
            await sendGoogleCalendarInvites(integration, eventId, attendeeEmails);
          } else if (integration.provider === 'outlook') {
            await sendOutlookCalendarInvites(integration, eventId, attendeeEmails);
          }
        } catch (err) {
          console.error(`Failed to send invites via ${integration.provider}:`, err);
        }
      }

      // Also send custom email invites
      await sendCustomInvites(eventId, attendeeEmails);
    } catch (err) {
      handleError('Failed to send invites');
    } finally {
      setIsLoading(false);
    }
  };

  const sendGoogleCalendarInvites = async (
    integration: CalendarIntegration, 
    eventId: string, 
    attendeeEmails: string[]
  ) => {
    // Google Calendar automatically sends invites when attendees are added
    // This is handled in the createGoogleCalendarEvent function
  };

  const sendOutlookCalendarInvites = async (
    integration: CalendarIntegration, 
    eventId: string, 
    attendeeEmails: string[]
  ) => {
    // Outlook Calendar automatically sends invites when attendees are added
    // This is handled in the createOutlookCalendarEvent function
  };

  const sendCustomInvites = async (eventId: string, attendeeEmails: string[]) => {
    // Send custom email invites using your email service
    const event = events.find(e => e.id === eventId);
    if (!event) return;

    // This would integrate with your email service (SendGrid, etc.)
    const inviteData = {
      eventId,
      eventTitle: event.title,
      eventStart: event.start,
      eventEnd: event.end,
      eventLocation: event.location,
      eventDescription: event.description,
      attendeeEmails
    };

    // Call your email service API
    await fetch('/api/send-calendar-invites', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(inviteData)
    });
  };

  return {
    events,
    integrations,
    isLoading,
    error,
    connectCalendar,
    disconnectCalendar,
    syncCalendars,
    checkAvailability,
    createEvent,
    sendInvites,
    refreshIntegration
  };
}

