'use client';

import { useState, useEffect } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface WeatherData {
  id: string;
  location: string;
  latitude: number;
  longitude: number;
  current: CurrentWeather;
  forecast: ForecastDay[];
  alerts: WeatherAlert[];
  lastUpdated: string;
}

interface CurrentWeather {
  temperature: number;
  feelsLike: number;
  humidity: number;
  windSpeed: number;
  windDirection: string;
  visibility: number;
  uvIndex: number;
  condition: string;
  icon: string;
  pressure: number;
}

interface ForecastDay {
  date: string;
  high: number;
  low: number;
  condition: string;
  icon: string;
  precipitationChance: number;
  windSpeed: number;
  humidity: number;
}

interface WeatherAlert {
  id: string;
  title: string;
  description: string;
  severity: 'minor' | 'moderate' | 'severe' | 'extreme';
  startTime: string;
  endTime: string;
  areas: string[];
}

interface WeatherAPIProps {
  tripId?: string;
  latitude: number;
  longitude: number;
  location: string;
  onWeatherUpdate?: (weather: WeatherData) => void;
}

interface WeatherAPIError {
  code: string;
  message: string;
  retryable: boolean;
}

// Weather API Service
class WeatherService {
  private static readonly API_KEY = process.env.NEXT_PUBLIC_WEATHER_API_KEY;
  private static readonly BASE_URL = 'https://api.openweathermap.org/data/2.5';
  private static readonly CACHE_DURATION = 10 * 60 * 1000; // 10 minutes

  static async getCurrentWeather(lat: number, lon: number): Promise<CurrentWeather> {
    const response = await fetch(
      `${this.BASE_URL}/weather?lat=${lat}&lon=${lon}&appid=${this.API_KEY}&units=metric`,
      {
        next: { revalidate: 600 } // 10 minutes
      }
    );

    if (!response.ok) {
      throw new Error(`Weather API error: ${response.status}`);
    }

    const data = await response.json();

    return {
      temperature: Math.round(data.main.temp),
      feelsLike: Math.round(data.main.feels_like),
      humidity: data.main.humidity,
      windSpeed: Math.round(data.wind.speed * 3.6), // Convert m/s to km/h
      windDirection: this.getWindDirection(data.wind.deg),
      visibility: Math.round(data.visibility / 1000), // Convert to km
      uvIndex: 0, // Not available in current weather endpoint
      condition: data.weather[0].description,
      icon: data.weather[0].icon,
      pressure: data.main.pressure
    };
  }

  static async getForecast(lat: number, lon: number): Promise<ForecastDay[]> {
    const response = await fetch(
      `${this.BASE_URL}/forecast?lat=${lat}&lon=${lon}&appid=${this.API_KEY}&units=metric`,
      {
        next: { revalidate: 3600 } // 1 hour
      }
    );

    if (!response.ok) {
      throw new Error(`Forecast API error: ${response.status}`);
    }

    const data = await response.json();

    // Group by day and get daily highs/lows
    const dailyData = new Map<string, any[]>();

    data.list.forEach((item: any) => {
      const date = new Date(item.dt * 1000).toISOString().split('T')[0];
      if (!dailyData.has(date)) {
        dailyData.set(date, []);
      }
      dailyData.get(date)!.push(item);
    });

    const forecast: ForecastDay[] = [];

    for (const [date, items] of dailyData) {
      if (forecast.length >= 7) break;

      const temps = items.map(item => item.main.temp);
      const high = Math.round(Math.max(...temps));
      const low = Math.round(Math.min(...temps));

      // Use midday data for conditions
      const middayItem = items.find(item => {
        const hour = new Date(item.dt * 1000).getHours();
        return hour >= 12 && hour <= 15;
      }) || items[0];

      forecast.push({
        date,
        high,
        low,
        condition: middayItem.weather[0].description,
        icon: middayItem.weather[0].icon,
        precipitationChance: Math.round((middayItem.pop || 0) * 100),
        windSpeed: Math.round(middayItem.wind.speed * 3.6),
        humidity: middayItem.main.humidity
      });
    }

    return forecast;
  }

  static async getWeatherAlerts(lat: number, lon: number): Promise<WeatherAlert[]> {
    // Note: OpenWeatherMap's alerts require a paid plan
    // This is a placeholder implementation
    try {
      const response = await fetch(
        `${this.BASE_URL}/onecall?lat=${lat}&lon=${lon}&appid=${this.API_KEY}&exclude=minutely,hourly`,
        {
          next: { revalidate: 1800 } // 30 minutes
        }
      );

      if (!response.ok) {
        return []; // Return empty array if alerts endpoint fails
      }

      const data = await response.json();

      if (!data.alerts) {
        return [];
      }

      return data.alerts.map((alert: any, index: number) => ({
        id: `alert-${index}`,
        title: alert.event,
        description: alert.description,
        severity: this.mapSeverity(alert.tags),
        startTime: new Date(alert.start * 1000).toISOString(),
        endTime: new Date(alert.end * 1000).toISOString(),
        areas: alert.areas || []
      }));
    } catch (error) {
      console.warn('Weather alerts not available:', error);
      return [];
    }
  }

  private static getWindDirection(degrees: number): string {
    const directions = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
    const index = Math.round(degrees / 22.5) % 16;
    return directions[index];
  }

  private static mapSeverity(tags: string[]): 'minor' | 'moderate' | 'severe' | 'extreme' {
    if (tags.includes('extreme')) return 'extreme';
    if (tags.includes('severe')) return 'severe';
    if (tags.includes('moderate')) return 'moderate';
    return 'minor';
  }
}

// Main Component
export default function WeatherAPI({ 
  tripId, 
  latitude, 
  longitude, 
  location, 
  onWeatherUpdate 
}: WeatherAPIProps) {
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<WeatherAPIError | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const supabase = createClientComponentClient();

  const fetchWeatherData = async (retryAttempt = 0) => {
    try {
      setLoading(true);
      setError(null);

      // Check cache first
      const cached = await getCachedWeather(latitude, longitude);
      if (cached && isCacheValid(cached.lastUpdated)) {
        setWeatherData(cached);
        setLoading(false);
        onWeatherUpdate?.(cached);
        return;
      }

      // Fetch fresh data
      const [current, forecast, alerts] = await Promise.all([
        WeatherService.getCurrentWeather(latitude, longitude),
        WeatherService.getForecast(latitude, longitude),
        WeatherService.getWeatherAlerts(latitude, longitude)
      ]);

      const newWeatherData: WeatherData = {
        id: `weather-${latitude}-${longitude}`,
        location,
        latitude,
        longitude,
        current,
        forecast,
        alerts,
        lastUpdated: new Date().toISOString()
      };

      // Cache the data
      await cacheWeatherData(newWeatherData);

      // Save to Supabase if tripId provided
      if (tripId) {
        await saveWeatherToTrip(tripId, newWeatherData);
      }

      setWeatherData(newWeatherData);
      onWeatherUpdate?.(newWeatherData);
      setRetryCount(0);
    } catch (err) {
      const weatherError: WeatherAPIError = {
        code: 'FETCH_ERROR',
        message: err instanceof Error ? err.message : 'Failed to fetch weather data',
        retryable: retryAttempt < 3
      };

      setError(weatherError);

      // Auto-retry with exponential backoff
      if (weatherError.retryable && retryAttempt < 3) {
        const delay = Math.pow(2, retryAttempt) * 1000;
        setTimeout(() => {
          setRetryCount(retryAttempt + 1);
          fetchWeatherData(retryAttempt + 1);
        }, delay);
      }
    } finally {
      setLoading(false);
    }
  };

  const getCachedWeather = async (lat: number, lon: number): Promise<WeatherData | null> => {
    try {
      const cacheKey = `weather-${lat}-${lon}`;
      const cached = localStorage.getItem(cacheKey);
      return cached ? JSON.parse(cached) : null;
    } catch {
      return null;
    }
  };

  const isCacheValid = (lastUpdated: string): boolean => {
    const cacheAge = Date.now() - new Date(lastUpdated).getTime();
    return cacheAge < 10 * 60 * 1000; // 10 minutes
  };

  const cacheWeatherData = async (data: WeatherData): Promise<void> => {
    try {
      const cacheKey = `weather-${data.latitude}-${data.longitude}`;
      localStorage.setItem(cacheKey, JSON.stringify(data));
    } catch (error) {
      console.warn('Failed to cache weather data:', error);
    }
  };

  const saveWeatherToTrip = async (tripId: string, weather: WeatherData): Promise<void> => {
    try {
      const { error } = await supabase
        .from('trip_weather')
        .upsert({
          trip_id: tripId,
          location: weather.location,
          latitude: weather.latitude,
          longitude: weather.longitude,
          weather_data: weather,
          updated_at: new Date().toISOString()
        });

      if (error) {
        console.warn('Failed to save weather to trip:', error);
      }
    } catch (error) {
      console.warn('Failed to save weather to trip:', error);
    }
  };

  const handleRetry = () => {
    setRetryCount(0);
    fetchWeatherData();
  };

  useEffect(() => {
    if (latitude && longitude) {
      fetchWeatherData();
    }
  }, [latitude, longitude, location]);

  // Auto-refresh every 10 minutes
  useEffect(() => {
    const interval = setInterval(() => {
      if (weatherData && !loading) {
        fetchWeatherData();
      }
    }, 10 * 60 * 1000);

    return () => clearInterval(interval);
  }, [weatherData, loading]);

  if (loading && !weatherData) {
    return <WeatherSkeleton />;
  }

  if (error && !weatherData) {
    return <WeatherError error={error} onRetry={handleRetry} />;
  }

  if (!weatherData) {
    return <WeatherEmpty onRefresh={() => fetchWeatherData()} />;
  }

  return (
    <div className="w-full space-y-4">
      <CurrentWeatherCard 
        weather={weatherData.current} 
        location={weatherData.location}
        lastUpdated={weatherData.lastUpdated}
        onRefresh={() => fetchWeatherData()}
        loading={loading}
      />

      {weatherData.alerts.length > 0 && (
        <WeatherAlerts alerts={weatherData.alerts} />
      )}

      <ForecastCard forecast={weatherData.forecast} />
    </div>
  );
}

