      <div className="space-y-3">
        {forecast.map((day, index) => (
          <div 
            key={day.date}
            className="flex items-center justify-between py-2 border-b border-[rgb(226,232,240)] last:border-b-0"
          >
            <div className="flex items-center gap-3 flex-1">
              <div className="w-16 text-sm font-medium text-[rgb(15,23,42)]">
                {formatDate(day.date)}
              </div>
              <div className="text-2xl">
                {getWeatherIcon(day.icon)}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm text-[rgb(15,23,42)] capitalize">
                  {day.condition}
                </div>
                <div className="text-xs text-[rgb(15,23,42)]/60">
                  {day.precipitationChance}% rain
                </div>
              </div>
            </div>

            <div className="flex items-center gap-4 text-sm">
              <div className="text-[rgb(15,23,42)]/60">
                {day.windSpeed} km/h
              </div>
              <div className="text-right">
