                      id="inviteeName"
                      placeholder="John Doe"
                      value={newInvitee.name}
                      onChange={(e) => setNewInvitee({...newInvitee, name: e.target.value})}
                      className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="inviteeEmail">Email *</Label>
                    <Input
                      id="inviteeEmail"
                      type="email"
                      placeholder="john@example.com"
                      value={newInvitee.email}
                      onChange={(e) => setNewInvitee({...newInvitee, email: e.target.value})}
                      className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="inviteePhone">Phone (Optional)</Label>
                    <Input
                      id="inviteePhone"
                      placeholder="+1 (555) 123-4567"
                      value={newInvitee.phone}
                      onChange={(e) => setNewInvitee({...newInvitee, phone: e.target.value})}
                      className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                    />
                  </div>
                </div>
                <Button 
                  onClick={addInvitee}
                  className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white h-11"
                >
                  Add Invitee
                </Button>

                {invitees.length > 0 && (
                  <div className="space-y-2">
                    <Label>Current Invitees ({invitees.length})</Label>
                    <div className="space-y-2 max-h-48 overflow-y-auto">
                      {invitees.map((invitee) => (
                        <div key={invitee.id} className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]">
                          <div>
                            <p className="font-medium text-[rgb(15,23,42)]">{invitee.name}</p>
                            <p className="text-sm text-[rgb(100,116,139)]">{invitee.email}</p>
                            {invitee.phone && (
                              <p className="text-sm text-[rgb(100,116,139)]">{invitee.phone}</p>
                            )}
                          </div>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => removeInvitee(invitee.id)}
                            className="text-[rgb(239,68,68)] border-[rgb(239,68,68)] hover:bg-[rgb(239,68,68)] hover:text-white"
                          >
                            Remove
                          </Button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>

            <Card className="shadow-md border-[rgb(226,232,240)]">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-[rgb(15,23,42)]">
                  <Send className="w-5 h-5 text-[rgb(34,139,34)]" />
                  Invitation Template
                </CardTitle>
                <CardDescription>Choose and customize your invitation message</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label>Template</Label>
                  <Select value={selectedTemplate.id} onValueChange={(value) => {
                    const template = defaultTemplates.find(t => t.id === value);
                    if (template) setSelectedTemplate(template);
                  }}>
                    <SelectTrigger className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {defaultTemplates.map((template) => (
                        <SelectItem key={template.id} value={template.id}>
                          {template.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label>Preview</Label>
                  <div className="p-4 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)] max-h-64 overflow-y-auto">
                    <h4 className="font-semibold text-[rgb(15,23,42)] mb-2">{selectedTemplate.subject}</h4>
                    <div className="whitespace-pre-wrap text-sm text-[rgb(100,116,139)]">
                      {generateInvitationText()}
                    </div>
                  </div>
                </div>

                <Button 
                  onClick={sendInvitations}
                  disabled={isLoading || invitees.length === 0}
                  className="w-full bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white h-12 text-lg"
                >
                  {isLoading ? (
                    <div className="flex items-center gap-2">
                      <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      Sending Invitations...
                    </div>
                  ) : (
                    <div className="flex items-center gap-2">
                      <Send className="w-5 h-5" />
                      Send Invitations ({invitees.length})
                    </div>
                  )}
                </Button>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="sent" className="space-y-6">
            {sentInvitations.length === 0 ? (
              <Card className="shadow-md border-[rgb(226,232,240)]">
                <CardContent className="text-center py-12">
                  <Send className="w-12 h-12 text-[rgb(156,163,175)] mx-auto mb-4" />
                  <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No invitations sent yet</h3>
                  <p className="text-[rgb(100,116,139)] mb-4">Create your first trip invitation to get started</p>
                  <Button 
                    onClick={() => setActiveTab('create')}
                    className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white"
                  >
                    Create Invitation
                  </Button>
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-4">
                {sentInvitations.map((invitation) => (
                  <Card key={invitation.id} className="shadow-md border-[rgb(226,232,240)]">
                    <CardHeader>
                      <div className="flex items-start justify-between">
                        <div>
                          <CardTitle className="text-[rgb(15,23,42)]">{invitation.tripName}</CardTitle>
                          <CardDescription className="flex items-center gap-4 mt-1">
                            <span className="flex items-center gap-1">
                              <MapPin className="w-4 h-4" />
                              {invitation.location}
                            </span>
                            <span className="flex items-center gap-1">
                              <Calendar className="w-4 h-4" />
                              {new Date(invitation.startDate).toLocaleDateString()} - {new Date(invitation.endDate).toLocaleDateString()}
                            </span>
                          </CardDescription>
                        </div>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => copyInvitationLink(invitation.tripId)}
                          className="border-[rgb(34,139,34)] text-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)] hover:text-white"
                        >
                          <Copy className="w-4 h-4 mr-2" />
                          Copy Link
                        </Button>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-4">
                        <div>
                          <h4 className="font-medium text-[rgb(15,23,42)] mb-2">Invitees ({invitation.invitees.length})</h4>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {invitation.invitees.map((invitee) => (
                              <div key={invitee.id} className="flex items-center justify-between p-2 bg-[rgb(248,250,252)] rounded border border-[rgb(226,232,240)]">
                                <div>
                                  <p className="font-medium text-sm text-[rgb(15,23,42)]">{invitee.name}</p>
                                  <p className="text-xs text-[rgb(100,116,139)]">{invitee.email}</p>
                                </div>
                                <Badge className={`${getStatusColor(invitee.status)} text-xs flex items-center gap-1`}>
                                  {getStatusIcon(invitee.status)}
                                  {invitee.status}
                                </Badge>
                              </div>
                            ))}
                          </div>
                        </div>

                        <div className="flex items-center justify-between pt-2 border-t border-[rgb(226,232,240)]">
                          <div className="text-sm text-[rgb(100,116,139)]">
                            Sent {new Date(invitation.createdAt).toLocaleDateString()}
                          </div>
                          <div className="flex gap-2">
                            <Badge variant="outline" className="text-[rgb(34,139,34)] border-[rgb(34,139,34)]">
                              {invitation.invitees.filter(i => i.status === 'accepted').length} Accepted
                            </Badge>
                            <Badge variant="outline" className="text-[rgb(100,116,139)] border-[rgb(226,232,240)]">
                              {invitation.invitees.filter(i => i.status === 'pending').length} Pending
                            </Badge>
                          </div>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </TabsContent>

          <TabsContent value="templates" className="space-y-6">
            <Card className="shadow-md border-[rgb(226,232,240)]">
              <CardHeader>
                <CardTitle className="text-[rgb(15,23,42)]">Invitation Templates</CardTitle>
                <CardDescription>Manage your invitation message templates</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {defaultTemplates.map((template) => (
                    <div key={template.id} className="p-4 border border-[rgb(226,232,240)] rounded-lg">
                      <div className="flex items-start justify-between mb-2">
                        <div>
                          <h4 className="font-semibold text-[rgb(15,23,42)]">{template.name}</h4>
                          {template.isDefault && (
                            <Badge className="bg-[rgb(34,139,34)] text-white text-xs mt-1">Default</Badge>
                          )}
                        </div>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setSelectedTemplate(template)}
                          className="border-[rgb(34,139,34)] text-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)] hover:text-white"
                        >
                          Use Template
                        </Button>
                      </div>
                      <p className="text-sm text-[rgb(100,116,139)] mb-2 font-medium">{template.subject}</p>
                      <div className="text-sm text-[rgb(100,116,139)] bg-[rgb(248,250,252)] p-3 rounded border max-h-32 overflow-y-auto">
                        {template.body.substring(0, 200)}...
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            <Card className="shadow-md border-[rgb(226,232,240)]">
              <CardHeader>
                <CardTitle className="text-[rgb(15,23,42)]">Calendar Integration</CardTitle>
                <CardDescription>Connect your calendar providers for automatic event creation</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {calendarProviders.map((provider) => (
                    <div key={provider.id} className="flex items-center justify-between p-3 border border-[rgb(226,232,240)] rounded-lg">
                      <div className="flex items-center gap-3">
                        <span className="text-2xl">{provider.icon}</span>
                        <div>
                          <p className="font-medium text-[rgb(15,23,42)]">{provider.name}</p>
                          <p className="text-sm text-[rgb(100,116,139)]">
                            {provider.connected ? 'Connected' : 'Not connected'}
                          </p>
                        </div>
                      </div>
                      <Button
                        variant={provider.connected ? "outline" : "default"}
                        size="sm"
                        className={provider.connected 
                          ? "border-[rgb(239,68,68)] text-[rgb(239,68,68)] hover:bg-[rgb(239,68,68)] hover:text-white" 
                          : "bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white"
                        }
                      >
                        {provider.connected ? 'Disconnect' : 'Connect'}
                      </Button>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface Trip {
  id: string;
  name: string;
  description?: string;
  start_date: string;
  end_date: string;
  location: string;
  latitude?: number;
  longitude?: number;
  created_by: string;
  created_at: string;
  updated_at: string;
  status: 'planning' | 'confirmed' | 'completed' | 'cancelled';
}

interface TripMember {
  id: string;
  trip_id: string;
  user_id: string;
  role: 'organizer' | 'member';
  status: 'invited' | 'accepted' | 'declined';
  joined_at: string;
}

interface Task {
  id: string;
  trip_id: string;
  title: string;
  description?: string;
  assigned_to?: string;
  due_date?: string;
  status: 'pending' | 'in_progress' | 'completed';
  category: 'food' | 'equipment' | 'logistics' | 'other';
  created_at: string;
}

interface Meal {
  id: string;
  trip_id: string;
  name: string;
  meal_type: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  scheduled_date: string;
  description?: string;
  assigned_to?: string;
  ingredients?: string[];
  created_at: string;
}

interface ChatMessage {
  id: string;
  trip_id: string;
  user_id: string;
  message: string;
  created_at: string;
  message_type: 'text' | 'system' | 'image';
}

interface WeatherData {
  date: string;
  temperature_high: number;
  temperature_low: number;
  condition: string;
  precipitation_chance: number;
  wind_speed: number;
}

interface APIResponse<T> {
  data: T | null;
  error: string | null;
  loading: boolean;
}

interface CreateTripData {
  name: string;
  description?: string;
  start_date: string;
  end_date: string;
  location: string;
  latitude?: number;
  longitude?: number;
}

interface UpdateTripData extends Partial<CreateTripData> {
  status?: Trip['status'];
}

interface CreateTaskData {
  title: string;
  description?: string;
  assigned_to?: string;
  due_date?: string;
  category: Task['category'];
}

interface CreateMealData {
  name: string;
  meal_type: Meal['meal_type'];
  scheduled_date: string;
  description?: string;
  assigned_to?: string;
  ingredients?: string[];
}

interface SendMessageData {
  message: string;
  message_type?: ChatMessage['message_type'];
}

interface InviteMemberData {
  user_id: string;
  role?: TripMember['role'];
}

// Custom hook for Trip API
export const useTripAPI = () => {
  const supabase = createClientComponentClient();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleError = useCallback((error: any, defaultMessage: string) => {
    console.error('Trip API Error:', error);
    const errorMessage = error?.message || defaultMessage;
    setError(errorMessage);
    return errorMessage;
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  // Trip CRUD operations
  const createTrip = useCallback(async (tripData: CreateTripData): Promise<APIResponse<Trip>> => {
    setLoading(true);
    clearError();

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('trips')
        .insert({
          ...tripData,
          created_by: user.id,
          status: 'planning'
        })
        .select()
        .single();

      if (error) throw error;

      // Add creator as organizer
      await supabase
        .from('trip_members')
        .insert({
          trip_id: data.id,
          user_id: user.id,
          role: 'organizer',
          status: 'accepted'
        });

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to create trip');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const getTrip = useCallback(async (tripId: string): Promise<APIResponse<Trip>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('trips')
        .select('*')
        .eq('id', tripId)
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch trip');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const updateTrip = useCallback(async (tripId: string, updates: UpdateTripData): Promise<APIResponse<Trip>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('trips')
        .update({
          ...updates,
          updated_at: new Date().toISOString()
        })
        .eq('id', tripId)
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to update trip');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const deleteTrip = useCallback(async (tripId: string): Promise<APIResponse<boolean>> => {
    setLoading(true);
    clearError();

    try {
      const { error } = await supabase
        .from('trips')
        .delete()
        .eq('id', tripId);

      if (error) throw error;

      setLoading(false);
      return { data: true, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to delete trip');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const getUserTrips = useCallback(async (): Promise<APIResponse<Trip[]>> => {
    setLoading(true);
    clearError();

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('trips')
        .select(`
          *,
          trip_members!inner(user_id)
        `)
        .eq('trip_members.user_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;

      setLoading(false);
      return { data: data || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch user trips');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  // Member management
  const inviteMember = useCallback(async (tripId: string, memberData: InviteMemberData): Promise<APIResponse<TripMember>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('trip_members')
        .insert({
          trip_id: tripId,
          user_id: memberData.user_id,
          role: memberData.role || 'member',
          status: 'invited'
        })
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to invite member');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const respondToInvite = useCallback(async (tripId: string, status: 'accepted' | 'declined'): Promise<APIResponse<TripMember>> => {
    setLoading(true);
    clearError();

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('trip_members')
        .update({ status })
        .eq('trip_id', tripId)
        .eq('user_id', user.id)
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to respond to invite');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const getTripMembers = useCallback(async (tripId: string): Promise<APIResponse<TripMember[]>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('trip_members')
        .select(`
          *,
          profiles(id, email, full_name, avatar_url)
        `)
        .eq('trip_id', tripId);

      if (error) throw error;

      setLoading(false);
      return { data: data || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch trip members');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  // Task management
  const createTask = useCallback(async (tripId: string, taskData: CreateTaskData): Promise<APIResponse<Task>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('tasks')
        .insert({
          trip_id: tripId,
          ...taskData,
          status: 'pending'
        })
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to create task');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const updateTask = useCallback(async (taskId: string, updates: Partial<Task>): Promise<APIResponse<Task>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('tasks')
        .update(updates)
        .eq('id', taskId)
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to update task');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const getTripTasks = useCallback(async (tripId: string): Promise<APIResponse<Task[]>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('tasks')
        .select(`
          *,
          assigned_user:profiles(id, full_name)
        `)
        .eq('trip_id', tripId)
        .order('created_at', { ascending: false });

      if (error) throw error;

      setLoading(false);
      return { data: data || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch trip tasks');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  // Meal management
  const createMeal = useCallback(async (tripId: string, mealData: CreateMealData): Promise<APIResponse<Meal>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('meals')
        .insert({
          trip_id: tripId,
          ...mealData
        })
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to create meal');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const getTripMeals = useCallback(async (tripId: string): Promise<APIResponse<Meal[]>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('meals')
        .select(`
          *,
          assigned_user:profiles(id, full_name)
        `)
        .eq('trip_id', tripId)
        .order('scheduled_date', { ascending: true });

      if (error) throw error;

      setLoading(false);
      return { data: data || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch trip meals');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  // Chat functionality
  const sendMessage = useCallback(async (tripId: string, messageData: SendMessageData): Promise<APIResponse<ChatMessage>> => {
    setLoading(true);
    clearError();

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('chat_messages')
        .insert({
          trip_id: tripId,
          user_id: user.id,
          message: messageData.message,
          message_type: messageData.message_type || 'text'
        })
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to send message');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  const getTripMessages = useCallback(async (tripId: string, limit: number = 50): Promise<APIResponse<ChatMessage[]>> => {
    setLoading(true);
    clearError();

    try {
      const { data, error } = await supabase
        .from('chat_messages')
        .select(`
          *,
          user:profiles(id, full_name, avatar_url)
        `)
        .eq('trip_id', tripId)
        .order('created_at', { ascending: false })
        .limit(limit);

      if (error) throw error;

      setLoading(false);
      return { data: data?.reverse() || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch messages');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [supabase, handleError, clearError]);

  // Weather integration
  const getWeatherForecast = useCallback(async (latitude: number, longitude: number, startDate: string, endDate: string): Promise<APIResponse<WeatherData[]>> => {
    setLoading(true);
    clearError();

    try {
      // This would integrate with a weather API like OpenWeatherMap
      const response = await fetch(`/api/weather?lat=${latitude}&lon=${longitude}&start=${startDate}&end=${endDate}`);

      if (!response.ok) {
        throw new Error('Failed to fetch weather data');
      }

      const weatherData = await response.json();

      setLoading(false);
      return { data: weatherData, error: null, loading: false };
    } catch (err) {
      const errorMessage = handleError(err, 'Failed to fetch weather forecast');
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  }, [handleError, clearError]);

  return {
    // State
    loading,
    error,
    clearError,

    // Trip operations
    createTrip,
    getTrip,
    updateTrip,
    deleteTrip,
    getUserTrips,

    // Member operations
    inviteMember,
    respondToInvite,
    getTripMembers,

    // Task operations
    createTask,
    updateTask,
    getTripTasks,

    // Meal operations
    createMeal,
    getTripMeals,

    // Chat operations
    sendMessage,
    getTripMessages,

    // Weather operations
    getWeatherForecast
  };
};

// Main API component
const TripAPI = () => {
  const api = useTripAPI();

  return (
    <div className="hidden">
      {/* This component provides the API hook and doesn't render UI */}
    </div>
  );
};

export default TripAPI;
export type {
  Trip,
  TripMember,
  Task,
  Meal,
  ChatMessage,
  WeatherData,
  APIResponse,
  CreateTripData,
  UpdateTripData,
  CreateTaskData,
  CreateMealData,
  SendMessageData,
  InviteMemberData
};

