'use client'

import React, { useState, useCallback, useRef, useEffect } from 'react'
import { GoogleMap, LoadScript, Marker, InfoWindow, Autocomplete } from '@react-google-maps/api'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { MapPin, Search, Star, Trash2, Navigation } from 'lucide-react'
import { toast } from 'sonner'

interface SavedLocation {
  id: string
  name: string
  lat: number
  lng: number
  address: string
  rating?: number
  notes?: string
  savedAt: Date
  category: 'campground' | 'trail' | 'scenic' | 'fuel' | 'food' | 'other'
}

interface MapLocation {
  lat: number
  lng: number
}

interface GoogleMapsAPIProps {
  apiKey: string
  onLocationSave?: (location: SavedLocation) => void
  savedLocations?: SavedLocation[]
  defaultCenter?: MapLocation
  className?: string
}

const libraries: ('places')[] = ['places']

const mapContainerStyle = {
  width: '100%',
  height: '100%',
  minHeight: '400px'
}

const defaultMapCenter: MapLocation = {
  lat: 39.8283,
  lng: -98.5795
}

const mapOptions = {
  disableDefaultUI: false,
  zoomControl: true,
  streetViewControl: false,
  mapTypeControl: true,
  fullscreenControl: true,
  gestureHandling: 'greedy' as const,
  styles: [
    {
      featureType: 'poi',
      elementType: 'labels',
      stylers: [{ visibility: 'on' }]
    },
    {
      featureType: 'landscape.natural',
      elementType: 'geometry',
      stylers: [{ color: '#f5f5f5' }]
    }
  ]
}

const categoryColors = {
  campground: 'rgb(34, 139, 34)',
  trail: 'rgb(245, 158, 11)',
  scenic: 'rgb(59, 130, 246)',
  fuel: 'rgb(239, 68, 68)',
  food: 'rgb(168, 85, 247)',
  other: 'rgb(107, 114, 128)'
}

export default function GoogleMapsAPI({
  apiKey,
  onLocationSave,
  savedLocations = [],
  defaultCenter = defaultMapCenter,
  className = ''
}: GoogleMapsAPIProps) {
  const [map, setMap] = useState<google.maps.Map | null>(null)
  const [center, setCenter] = useState<MapLocation>(defaultCenter)
  const [selectedLocation, setSelectedLocation] = useState<MapLocation | null>(null)
  const [selectedSavedLocation, setSelectedSavedLocation] = useState<SavedLocation | null>(null)
  const [searchValue, setSearchValue] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [userLocation, setUserLocation] = useState<MapLocation | null>(null)

  const autocompleteRef = useRef<google.maps.places.Autocomplete | null>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)

  const onLoad = useCallback((map: google.maps.Map) => {
    setMap(map)
  }, [])

  const onUnmount = useCallback(() => {
    setMap(null)
  }, [])

  const onMapClick = useCallback((event: google.maps.MapMouseEvent) => {
    if (event.latLng) {
      const lat = event.latLng.lat()
      const lng = event.latLng.lng()
      setSelectedLocation({ lat, lng })
      setSelectedSavedLocation(null)
    }
  }, [])

  const onAutocompleteLoad = useCallback((autocomplete: google.maps.places.Autocomplete) => {
    autocompleteRef.current = autocomplete
  }, [])

  const onPlaceChanged = useCallback(() => {
    if (autocompleteRef.current) {
      const place = autocompleteRef.current.getPlace()
      if (place.geometry?.location) {
        const lat = place.geometry.location.lat()
        const lng = place.geometry.location.lng()
        const newCenter = { lat, lng }
        setCenter(newCenter)
        setSelectedLocation(newCenter)
        setSelectedSavedLocation(null)

        if (map) {
          map.panTo(newCenter)
          map.setZoom(15)
        }
      }
    }
  }, [map])

  const getCurrentLocation = useCallback(() => {
    setIsLoading(true)

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const lat = position.coords.latitude
          const lng = position.coords.longitude
          const location = { lat, lng }

          setUserLocation(location)
          setCenter(location)
          setSelectedLocation(location)

          if (map) {
            map.panTo(location)
            map.setZoom(15)
          }

          setIsLoading(false)
          toast.success('Current location found')
        },
        (error) => {
          console.error('Geolocation error:', error)
          toast.error('Unable to get current location')
          setIsLoading(false)
        },
        {
          enableHighAccuracy: true,
          timeout: 10000,
          maximumAge: 300000
        }
      )
    } else {
      toast.error('Geolocation is not supported')
      setIsLoading(false)
    }
  }, [map])

  const saveLocation = useCallback(async (location: MapLocation, name: string, category: SavedLocation['category']) => {
    if (!location) return

    setIsLoading(true)

    try {
      // Reverse geocoding to get address
      const geocoder = new google.maps.Geocoder()
      const response = await geocoder.geocode({ location })

      const address = response.results[0]?.formatted_address || 'Unknown address'

      const savedLocation: SavedLocation = {
        id: `loc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        name,
        lat: location.lat,
        lng: location.lng,
        address,
        savedAt: new Date(),
        category
      }

      onLocationSave?.(savedLocation)
      setSelectedLocation(null)
      toast.success(`Location "${name}" saved successfully`)
    } catch (error) {
      console.error('Error saving location:', error)
      toast.error('Failed to save location')
    } finally {
      setIsLoading(false)
    }
  }, [onLocationSave])

  const deleteLocation = useCallback((locationId: string) => {
    // This would typically call a delete function passed as prop
    toast.success('Location deleted')
  }, [])

  useEffect(() => {
    if (map && savedLocations.length > 0) {
      const bounds = new google.maps.LatLngBounds()
      savedLocations.forEach(location => {
        bounds.extend({ lat: location.lat, lng: location.lng })
      })
      map.fitBounds(bounds)
    }
  }, [map, savedLocations])

  if (!apiKey) {
    return (
      <Card className={`w-full ${className}`}>
        <CardContent className="p-6">
          <div className="text-center text-[rgb(107,114,128)]">
            Google Maps API key is required
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className={`w-full h-full flex flex-col ${className}`}>
      <LoadScript
        googleMapsApiKey={apiKey}
        libraries={libraries}
        loadingElement={
          <div className="w-full h-96 bg-[rgb(241,245,249)] animate-pulse rounded-lg flex items-center justify-center">
            <div className="text-[rgb(107,114,128)]">Loading map...</div>
          </div>
        }
      >
        {/* Search Controls */}
        <Card className="mb-4 shadow-md">
          <CardContent className="p-4">
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="flex-1 relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[rgb(107,114,128)] w-4 h-4" />
                <Autocomplete
                  onLoad={onAutocompleteLoad}
                  onPlaceChanged={onPlaceChanged}
                >
                  <Input
                    ref={searchInputRef}
                    placeholder="Search for places..."
                    value={searchValue}
                    onChange={(e) => setSearchValue(e.target.value)}
                    className="pl-10 font-medium"
                    aria-label="Search for places"
                  />
                </Autocomplete>
              </div>
              <Button
                onClick={getCurrentLocation}
                disabled={isLoading}
                variant="outline"
                size="default"
                className="min-h-[44px] font-medium"
                aria-label="Get current location"
              >
                <Navigation className="w-4 h-4 mr-2" />
                My Location
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Map Container */}
        <Card className="flex-1 shadow-lg">
          <CardContent className="p-0 h-full">
            <GoogleMap
              mapContainerStyle={mapContainerStyle}
              center={center}
              zoom={10}
              onLoad={onLoad}
              onUnmount={onUnmount}
              onClick={onMapClick}
              options={mapOptions}
            >
              {/* User Location Marker */}
              {userLocation && (
                <Marker
                  position={userLocation}
                  icon={{
                    url: 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(`
                      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <circle cx="12" cy="12" r="8" fill="rgb(59, 130, 246)" stroke="white" stroke-width="2"/>
                        <circle cx="12" cy="12" r="3" fill="white"/>
                      </svg>
                    `),
                    scaledSize: new google.maps.Size(24, 24)
                  }}
                  title="Your Location"
                />
              )}

              {/* Selected Location Marker */}
              {selectedLocation && (
                <Marker
                  position={selectedLocation}
                  icon={{
                    url: 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(`
                      <svg width="32" height="32" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z" fill="rgb(245, 158, 11)" stroke="white" stroke-width="1"/>
                        <circle cx="12" cy="9" r="2.5" fill="white"/>
                      </svg>
                    `),
                    scaledSize: new google.maps.Size(32, 32)
                  }}
                >
                  <InfoWindow
                    position={selectedLocation}
                    onCloseClick={() => setSelectedLocation(null)}
                  >
                    <div className="p-2 max-w-xs">
                      <h3 className="font-semibold text-[rgb(15,23,42)] mb-2">Save Location</h3>
                      <SaveLocationForm
                        location={selectedLocation}
                        onSave={saveLocation}
                        isLoading={isLoading}
                      />
                    </div>
                  </InfoWindow>
                </Marker>
              )}

              {/* Saved Locations Markers */}
              {savedLocations.map((location) => (
                <Marker
                  key={location.id}
                  position={{ lat: location.lat, lng: location.lng }}
                  icon={{
                    url: 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(`
                      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z" fill="${categoryColors[location.category]}" stroke="white" stroke-width="1"/>
                        <circle cx="12" cy="9" r="2.5" fill="white"/>
                      </svg>
                    `),
                    scaledSize: new google.maps.Size(28, 28)
                  }}
                  onClick={() => setSelectedSavedLocation(location)}
                />
              ))}

              {/* Saved Location Info Window */}
              {selectedSavedLocation && (
                <InfoWindow
                  position={{ lat: selectedSavedLocation.lat, lng: selectedSavedLocation.lng }}
                  onCloseClick={() => setSelectedSavedLocation(null)}
                >
                  <div className="p-3 max-w-sm">
                    <div className="flex items-start justify-between mb-2">
                      <h3 className="font-semibold text-[rgb(15,23,42)] text-lg">{selectedSavedLocation.name}</h3>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => deleteLocation(selectedSavedLocation.id)}
                        className="text-[rgb(239,68,68)] hover:text-[rgb(239,68,68)] p-1"
                        aria-label="Delete location"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>

                    <Badge 
                      className="mb-2 text-white font-medium"
                      style={{ backgroundColor: categoryColors[selectedSavedLocation.category] }}
                    >
                      {selectedSavedLocation.category}
                    </Badge>

                    <p className="text-sm text-[rgb(107,114,128)] mb-2">
                      {selectedSavedLocation.address}
                    </p>

                    {selectedSavedLocation.rating && (
                      <div className="flex items-center mb-2">
                        <Star className="w-4 h-4 text-[rgb(245,158,11)] fill-current mr-1" />
                        <span className="text-sm font-medium">{selectedSavedLocation.rating}</span>
                      </div>
                    )}

                    {selectedSavedLocation.notes && (
                      <p className="text-sm text-[rgb(15,23,42)] mb-2">
                        {selectedSavedLocation.notes}
                      </p>
                    )}

                    <p className="text-xs text-[rgb(107,114,128)]">
                      Saved {selectedSavedLocation.savedAt.toLocaleDateString()}
                    </p>
                  </div>
                </InfoWindow>
              )}
            </GoogleMap>
          </CardContent>
        </Card>
      </LoadScript>
    </div>
  )
}

interface SaveLocationFormProps {
  location: MapLocation
  onSave: (location: MapLocation, name: string, category: SavedLocation['category']) => void
  isLoading: boolean
}

function SaveLocationForm({ location, onSave, isLoading }: SaveLocationFormProps) {
  const [name, setName] = useState('')
  const [category, setCategory] = useState<SavedLocation['category']>('other')

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (name.trim()) {
      onSave(location, name.trim(), category)
      setName('')
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      <Input
        placeholder="Location name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        required
        className="font-medium"
        aria-label="Location name"
      />

      <select
        value={category}
        onChange={(e) => setCategory(e.target.value as SavedLocation['category'])}
        className="w-full p-2 border border-[rgb(226,232,240)] rounded-md font-medium bg-white"
        aria-label="Location category"
      >
        <option value="campground">Campground</option>
        <option value="trail">Trail</option>
        <option value="scenic">Scenic Spot</option>
        <option value="fuel">Fuel Station</option>
        <option value="food">Food & Dining</option>
        <option value="other">Other</option>
      </select>

      <Button
        type="submit"
        disabled={!name.trim() || isLoading}
        className="w-full bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white font-medium min-h-[44px]"
      >
        <MapPin className="w-4 h-4 mr-2" />
        {isLoading ? 'Saving...' : 'Save Location'}
      </Button>
    </form>
  )
}

