'use client';

import { useState, useCallback, useEffect } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface Location {
  id: string;
  name: string;
  latitude: number;
  longitude: number;
  description?: string;
  terrain: 'easy' | 'moderate' | 'difficult' | 'extreme';
  difficulty: number; // 1-10 scale
  amenities: string[];
  imageUrl?: string;
  rating: number;
  reviewCount: number;
  createdAt: string;
  updatedAt: string;
}

interface LocationSearchParams {
  query?: string;
  latitude?: number;
  longitude?: number;
  radius?: number; // in miles
  terrain?: Location['terrain'];
  minRating?: number;
  limit?: number;
  offset?: number;
}

interface LocationAPIResponse {
  locations: Location[];
  total: number;
  hasMore: boolean;
}

interface SavedLocation {
  id: string;
  userId: string;
  locationId: string;
  location: Location;
  notes?: string;
  tags: string[];
  savedAt: string;
}

interface LocationAPIError {
  message: string;
  code: string;
  details?: any;
}

// Custom hook for location API operations
export const useLocationAPI = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<LocationAPIError | null>(null);
  const supabase = createClientComponentClient();

  const searchLocations = useCallback(async (params: LocationSearchParams): Promise<LocationAPIResponse> => {
    setLoading(true);
    setError(null);

    try {
      let query = supabase
        .from('locations')
        .select('*', { count: 'exact' });

      // Apply filters
      if (params.query) {
        query = query.or(`name.ilike.%${params.query}%,description.ilike.%${params.query}%`);
      }

      if (params.terrain) {
        query = query.eq('terrain', params.terrain);
      }

      if (params.minRating) {
        query = query.gte('rating', params.minRating);
      }

      // Geographic search
      if (params.latitude && params.longitude && params.radius) {
        const radiusInDegrees = params.radius / 69; // Rough conversion
        query = query
          .gte('latitude', params.latitude - radiusInDegrees)
          .lte('latitude', params.latitude + radiusInDegrees)
          .gte('longitude', params.longitude - radiusInDegrees)
          .lte('longitude', params.longitude + radiusInDegrees);
      }

      // Pagination
      const limit = params.limit || 20;
      const offset = params.offset || 0;
      query = query.range(offset, offset + limit - 1);

      // Order by rating and review count
      query = query.order('rating', { ascending: false });

      const { data, error: queryError, count } = await query;

      if (queryError) {
        throw new Error(queryError.message);
      }

      const total = count || 0;
      const hasMore = offset + limit < total;

      return {
        locations: data || [],
        total,
        hasMore
      };
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to search locations',
        code: 'SEARCH_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const getLocationById = useCallback(async (id: string): Promise<Location | null> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error: queryError } = await supabase
        .from('locations')
        .select('*')
        .eq('id', id)
        .single();

      if (queryError) {
        if (queryError.code === 'PGRST116') {
          return null; // Not found
        }
        throw new Error(queryError.message);
      }

      return data;
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to get location',
        code: 'GET_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const saveLocation = useCallback(async (locationId: string, notes?: string, tags: string[] = []): Promise<SavedLocation> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      // Check if already saved
      const { data: existing } = await supabase
        .from('saved_locations')
        .select('id')
        .eq('user_id', user.id)
        .eq('location_id', locationId)
        .single();

      if (existing) {
        throw new Error('Location already saved');
      }

      const { data, error: insertError } = await supabase
        .from('saved_locations')
        .insert({
          user_id: user.id,
          location_id: locationId,
          notes,
          tags,
          saved_at: new Date().toISOString()
        })
        .select(`
          *,
          location:locations(*)
        `)
        .single();

      if (insertError) {
        throw new Error(insertError.message);
      }

      return {
        id: data.id,
        userId: data.user_id,
        locationId: data.location_id,
        location: data.location,
        notes: data.notes,
        tags: data.tags,
        savedAt: data.saved_at
      };
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to save location',
        code: 'SAVE_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const unsaveLocation = useCallback(async (locationId: string): Promise<void> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { error: deleteError } = await supabase
        .from('saved_locations')
        .delete()
        .eq('user_id', user.id)
        .eq('location_id', locationId);

      if (deleteError) {
        throw new Error(deleteError.message);
      }
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to unsave location',
        code: 'UNSAVE_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const getSavedLocations = useCallback(async (): Promise<SavedLocation[]> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error: queryError } = await supabase
        .from('saved_locations')
        .select(`
          *,
          location:locations(*)
        `)
        .eq('user_id', user.id)
        .order('saved_at', { ascending: false });

      if (queryError) {
        throw new Error(queryError.message);
      }

      return (data || []).map(item => ({
        id: item.id,
        userId: item.user_id,
        locationId: item.location_id,
        location: item.location,
        notes: item.notes,
        tags: item.tags,
        savedAt: item.saved_at
      }));
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to get saved locations',
        code: 'GET_SAVED_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const updateSavedLocation = useCallback(async (
    savedLocationId: string, 
    updates: { notes?: string; tags?: string[] }
  ): Promise<SavedLocation> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error: updateError } = await supabase
        .from('saved_locations')
        .update({
          ...updates,
          updated_at: new Date().toISOString()
        })
        .eq('id', savedLocationId)
        .select(`
          *,
          location:locations(*)
        `)
        .single();

      if (updateError) {
        throw new Error(updateError.message);
      }

      return {
        id: data.id,
        userId: data.user_id,
        locationId: data.location_id,
        location: data.location,
        notes: data.notes,
        tags: data.tags,
        savedAt: data.saved_at
      };
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to update saved location',
        code: 'UPDATE_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const getNearbyLocations = useCallback(async (
    latitude: number, 
    longitude: number, 
    radiusMiles: number = 50
  ): Promise<Location[]> => {
    setLoading(true);
    setError(null);

    try {
      // Use PostGIS for accurate distance calculation if available
      const { data, error: queryError } = await supabase
        .rpc('get_nearby_locations', {
          lat: latitude,
          lng: longitude,
          radius_miles: radiusMiles
        });

      if (queryError) {
        // Fallback to simple bounding box search
        return searchLocations({
          latitude,
          longitude,
          radius: radiusMiles,
          limit: 50
        }).then(response => response.locations);
      }

      return data || [];
    } catch (err) {
      const error: LocationAPIError = {
        message: err instanceof Error ? err.message : 'Failed to get nearby locations',
        code: 'NEARBY_ERROR',
        details: err
      };
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [supabase, searchLocations]);

  return {
    loading,
    error,
    searchLocations,
    getLocationById,
    saveLocation,
    unsaveLocation,
    getSavedLocations,
    updateSavedLocation,
    getNearbyLocations,
    clearError: () => setError(null)
  };
};

// Location API service class
export class LocationAPIService {
  private supabase = createClientComponentClient();

  async searchLocations(params: LocationSearchParams): Promise<LocationAPIResponse> {
    const hook = useLocationAPI();
    return hook.searchLocations(params);
  }

  async getLocationById(id: string): Promise<Location | null> {
    const hook = useLocationAPI();
    return hook.getLocationById(id);
  }

  async saveLocation(locationId: string, notes?: string, tags: string[] = []): Promise<SavedLocation> {
    const hook = useLocationAPI();
    return hook.saveLocation(locationId, notes, tags);
  }

  async unsaveLocation(locationId: string): Promise<void> {
    const hook = useLocationAPI();
    return hook.unsaveLocation(locationId);
  }

  async getSavedLocations(): Promise<SavedLocation[]> {
    const hook = useLocationAPI();
    return hook.getSavedLocations();
  }

  async updateSavedLocation(savedLocationId: string, updates: { notes?: string; tags?: string[] }): Promise<SavedLocation> {
    const hook = useLocationAPI();
    return hook.updateSavedLocation(savedLocationId, updates);
  }

  async getNearbyLocations(latitude: number, longitude: number, radiusMiles: number = 50): Promise<Location[]> {
    const hook = useLocationAPI();
    return hook.getNearbyLocations(latitude, longitude, radiusMiles);
  }
}

// Utility functions
export const calculateDistance = (
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number => {
  const R = 3959; // Earth's radius in miles
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

export const formatDistance = (miles: number): string => {
  if (miles < 1) {
    return `${(miles * 5280).toFixed(0)} ft`;
  }
  return `${miles.toFixed(1)} mi`;
};

export const getTerrainColor = (terrain: Location['terrain']): string => {
  switch (terrain) {
    case 'easy':
      return 'rgb(34, 139, 34)'; // Primary green
    case 'moderate':
      return 'rgb(245, 158, 11)'; // Accent orange
    case 'difficult':
      return 'rgb(239, 68, 68)'; // Destructive red
    case 'extreme':
      return 'rgb(15, 23, 42)'; // Foreground dark
    default:
      return 'rgb(156, 163, 175)'; // Gray
  }
};

export const getTerrainLabel = (terrain: Location['terrain']): string => {
  switch (terrain) {
    case 'easy':
      return 'Easy';
    case 'moderate':
      return 'Moderate';
    case 'difficult':
      return 'Difficult';
    case 'extreme':
      return 'Extreme';
    default:
      return 'Unknown';
  }
};

// Main component export
const LocationAPI = () => {
  const {
    loading,
    error,
    searchLocations,
    getLocationById,
    saveLocation,
    unsaveLocation,
    getSavedLocations,
    updateSavedLocation,
    getNearbyLocations,
    clearError
  } = useLocationAPI();

  return {
    loading,
    error,
    searchLocations,
    getLocationById,
    saveLocation,
    unsaveLocation,
    getSavedLocations,
    updateSavedLocation,
    getNearbyLocations,
    clearError
  };
};

export default LocationAPI;

// Export types for use in other components
export type {
  Location,
  LocationSearchParams,
  LocationAPIResponse,
  SavedLocation,
  LocationAPIError
};

