                  <button
                    onClick={() => handleNavigate(item.href)}
                    className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg text-left transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 ${
                      active
                        ? 'bg-[rgb(34,139,34)] text-white'
                        : 'text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                    }`}
                    aria-current={active ? 'page' : undefined}
                  >
                    <Icon className="w-5 h-5 flex-shrink-0" />
                    <span className="font-medium font-[Inter,system-ui,sans-serif]">
                      {item.label}
                    </span>
                    {item.badge && (
                      <span 
                        className={`ml-auto px-2 py-1 text-xs font-semibold rounded-full ${
                          active 
                            ? 'bg-white text-[rgb(34,139,34)]' 
                            : 'bg-[rgb(245,158,11)] text-white'
                        }`}
