          </ul>
        </nav>
      </div>

      {/* Bottom Navigation Bar */}
      <nav 
        className="fixed bottom-0 left-0 right-0 z-40 bg-white border-t border-[rgb(226,232,240)] safe-area-inset-bottom"
        role="navigation"
        aria-label="Bottom navigation"
      >
        <div className="flex items-center justify-around px-2 py-2">
          {navigationItems.map((item) => {
            const Icon = isActive(item.href) ? item.activeIcon : item.icon;
            const active = isActive(item.href);

            return (
              <button
                key={item.id}
                onClick={() => handleNavigate(item.href)}
                className={`relative flex flex-col items-center gap-1 px-3 py-2 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px] min-w-[44px] ${
                  active
                    ? 'text-[rgb(34,139,34)]'
                    : 'text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]'
                }`}
                aria-current={active ? 'page' : undefined}
                aria-label={`Navigate to ${item.label}`}
              >
                <Icon className="w-6 h-6" />
                <span className="text-xs font-medium font-[Inter,system-ui,sans-serif]">
                  {item.label}
                </span>
                {item.badge && (
                  <span 
                    className="absolute -top-1 -right-1 bg-[rgb(245,158,11)] text-white text-xs font-semibold rounded-full w-5 h-5 flex items-center justify-center"
                    aria-label={`${item.badge} unread messages`}
                  >
                    {item.badge}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </nav>

      {/* Spacer for fixed navigation */}
      <div className="h-16" aria-hidden="true" />
      <div className="h-20" aria-hidden="true" />
    </>
  );
}

'use client'

import React, { useState, useEffect } from 'react'
import { Plus, Check, X, User, Calendar, Clock, AlertCircle } from 'lucide-react'

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  isOnline: boolean
}

interface Task {
  id: string
  title: string
  description?: string
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'other'
  assignedTo?: string
  assignedToName?: string
  dueDate?: string
  priority: 'low' | 'medium' | 'high'
  status: 'pending' | 'in-progress' | 'completed'
  createdAt: string
  updatedAt: string
}

interface TaskAssignmentProps {
  tripId: string
  groupMembers: GroupMember[]
  onTaskCreate?: (task: Omit<Task, 'id' | 'createdAt' | 'updatedAt'>) => void
  onTaskUpdate?: (taskId: string, updates: Partial<Task>) => void
  onTaskDelete?: (taskId: string) => void
}

const TASK_CATEGORIES = [
  { value: 'food', label: 'Food & Meals', color: 'bg-[rgb(245,158,11)]' },
  { value: 'equipment', label: 'Equipment', color: 'bg-[rgb(34,139,34)]' },
  { value: 'logistics', label: 'Logistics', color: 'bg-[rgb(59,130,246)]' },
  { value: 'safety', label: 'Safety', color: 'bg-[rgb(239,68,68)]' },
  { value: 'other', label: 'Other', color: 'bg-[rgb(107,114,128)]' }
] as const

const PRIORITY_LEVELS = [
  { value: 'low', label: 'Low', color: 'text-[rgb(107,114,128)]' },
  { value: 'medium', label: 'Medium', color: 'text-[rgb(245,158,11)]' },
  { value: 'high', label: 'High', color: 'text-[rgb(239,68,68)]' }
] as const

export default function TaskAssignment({ 
  tripId, 
  groupMembers, 
  onTaskCreate, 
  onTaskUpdate, 
  onTaskDelete 
}: TaskAssignmentProps) {
  const [tasks, setTasks] = useState<Task[]>([])
  const [isCreating, setIsCreating] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    category: 'other' as Task['category'],
    assignedTo: '',
    dueDate: '',
    priority: 'medium' as Task['priority']
  })

  useEffect(() => {
    loadTasks()
  }, [tripId])

  const loadTasks = async () => {
    try {
      setLoading(true)
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))

      const mockTasks: Task[] = [
        {
          id: '1',
          title: 'Bring firewood',
          description: 'Collect dry firewood for campfire',
          category: 'equipment',
          assignedTo: groupMembers[0]?.id,
          assignedToName: groupMembers[0]?.name,
          dueDate: '2024-01-15',
          priority: 'high',
          status: 'pending',
          createdAt: '2024-01-10T10:00:00Z',
          updatedAt: '2024-01-10T10:00:00Z'
        },
        {
          id: '2',
          title: 'Prepare Saturday lunch',
          description: 'Sandwiches and snacks for the group',
          category: 'food',
          assignedTo: groupMembers[1]?.id,
          assignedToName: groupMembers[1]?.name,
          dueDate: '2024-01-14',
          priority: 'medium',
          status: 'in-progress',
          createdAt: '2024-01-10T11:00:00Z',
          updatedAt: '2024-01-12T09:00:00Z'
        }
      ]

      setTasks(mockTasks)
    } catch (err) {
      setError('Failed to load tasks. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  const handleCreateTask = async () => {
    if (!newTask.title.trim()) return

    try {
      const assignedMember = groupMembers.find(m => m.id === newTask.assignedTo)
      const task: Task = {
        id: Date.now().toString(),
        title: newTask.title,
        description: newTask.description,
        category: newTask.category,
        assignedTo: newTask.assignedTo || undefined,
        assignedToName: assignedMember?.name,
        dueDate: newTask.dueDate || undefined,
        priority: newTask.priority,
        status: 'pending',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      }

      setTasks(prev => [...prev, task])
      onTaskCreate?.(task)

      setNewTask({
        title: '',
        description: '',
        category: 'other',
        assignedTo: '',
        dueDate: '',
        priority: 'medium'
      })
      setIsCreating(false)
    } catch (err) {
      setError('Failed to create task. Please try again.')
    }
  }

  const handleUpdateTaskStatus = async (taskId: string, status: Task['status']) => {
    try {
      setTasks(prev => prev.map(task => 
        task.id === taskId 
          ? { ...task, status, updatedAt: new Date().toISOString() }
          : task
      ))
      onTaskUpdate?.(taskId, { status })
    } catch (err) {
      setError('Failed to update task. Please try again.')
    }
  }

  const handleDeleteTask = async (taskId: string) => {
    try {
      setTasks(prev => prev.filter(task => task.id !== taskId))
      onTaskDelete?.(taskId)
    } catch (err) {
      setError('Failed to delete task. Please try again.')
    }
  }

  const getCategoryColor = (category: Task['category']) => {
    return TASK_CATEGORIES.find(c => c.value === category)?.color || 'bg-[rgb(107,114,128)]'
  }

  const getPriorityColor = (priority: Task['priority']) => {
    return PRIORITY_LEVELS.find(p => p.value === priority)?.color || 'text-[rgb(107,114,128)]'
  }

  const getStatusIcon = (status: Task['status']) => {
    switch (status) {
      case 'completed':
        return <Check className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'in-progress':
        return <Clock className="w-4 h-4 text-[rgb(245,158,11)]" />
      default:
        return <AlertCircle className="w-4 h-4 text-[rgb(107,114,128)]" />
    }
  }

  if (loading) {
    return (
      <div className="p-4 space-y-4">
        <div className="flex items-center justify-between">
          <div className="h-8 bg-[rgb(241,245,249)] rounded-md w-32 animate-pulse"></div>
          <div className="h-10 bg-[rgb(241,245,249)] rounded-md w-24 animate-pulse"></div>
        </div>
        {[1, 2, 3].map(i => (
          <div key={i} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-sm">
            <div className="space-y-3">
              <div className="h-5 bg-[rgb(241,245,249)] rounded w-3/4 animate-pulse"></div>
              <div className="h-4 bg-[rgb(241,245,249)] rounded w-1/2 animate-pulse"></div>
              <div className="flex gap-2">
                <div className="h-6 bg-[rgb(241,245,249)] rounded w-16 animate-pulse"></div>
                <div className="h-6 bg-[rgb(241,245,249)] rounded w-20 animate-pulse"></div>
              </div>
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className="p-4 max-w-4xl mx-auto font-medium" style={{ fontFamily: 'Inter, system-ui, sans-serif' }}>
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Task Assignment</h2>
        <button
          onClick={() => setIsCreating(true)}
          className="flex items-center gap-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg shadow-md hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
          aria-label="Add new task"
        >
          <Plus className="w-4 h-4" />
          <span className="hidden sm:inline">Add Task</span>
        </button>
      </div>

      {error && (
        <div className="mb-4 p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
          <p className="text-[rgb(239,68,68)] text-sm">{error}</p>
        </div>
      )}

      {isCreating && (
        <div className="mb-6 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
          <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Create New Task</h3>

          <div className="space-y-4">
            <div>
              <label htmlFor="task-title" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                Task Title *
              </label>
              <input
                id="task-title"
                type="text"
                value={newTask.title}
                onChange={(e) => setNewTask(prev => ({ ...prev, title: e.target.value }))}
                placeholder="Enter task title"
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                aria-required="true"
              />
            </div>

            <div>
              <label htmlFor="task-description" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                Description
              </label>
              <textarea
                id="task-description"
                value={newTask.description}
                onChange={(e) => setNewTask(prev => ({ ...prev, description: e.target.value }))}
                placeholder="Enter task description"
                rows={3}
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="task-category" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Category
                </label>
                <select
                  id="task-category"
                  value={newTask.category}
                  onChange={(e) => setNewTask(prev => ({ ...prev, category: e.target.value as Task['category'] }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                >
                  {TASK_CATEGORIES.map(category => (
                    <option key={category.value} value={category.value}>
                      {category.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="task-priority" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Priority
                </label>
                <select
                  id="task-priority"
                  value={newTask.priority}
                  onChange={(e) => setNewTask(prev => ({ ...prev, priority: e.target.value as Task['priority'] }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                >
                  {PRIORITY_LEVELS.map(priority => (
                    <option key={priority.value} value={priority.value}>
                      {priority.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="task-assignee" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Assign To
                </label>
                <select
                  id="task-assignee"
                  value={newTask.assignedTo}
                  onChange={(e) => setNewTask(prev => ({ ...prev, assignedTo: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                >
                  <option value="">Unassigned</option>
                  {groupMembers.map(member => (
                    <option key={member.id} value={member.id}>
                      {member.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="task-due-date" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Due Date
                </label>
                <input
                  id="task-due-date"
                  type="date"
                  value={newTask.dueDate}
                  onChange={(e) => setNewTask(prev => ({ ...prev, dueDate: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                />
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <button
                onClick={handleCreateTask}
                disabled={!newTask.title.trim()}
                className="flex-1 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg shadow-md hover:bg-[rgb(34,139,34)]/90 disabled:bg-[rgb(107,114,128)] disabled:cursor-not-allowed transition-colors min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              >
                Create Task
              </button>
              <button
                onClick={() => setIsCreating(false)}
                className="px-4 py-2 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[rgb(226,232,240)] focus:ring-offset-2"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {tasks.length === 0 ? (
          <div className="text-center py-12">
            <AlertCircle className="w-12 h-12 text-[rgb(107,114,128)] mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No tasks yet</h3>
            <p className="text-[rgb(107,114,128)] mb-4">Get started by creating your first task for the trip.</p>
            <button
              onClick={() => setIsCreating(true)}
              className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-6 py-2 rounded-lg shadow-md hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            >
              Create First Task
            </button>
          </div>
        ) : (
          tasks.map(task => (
            <div
              key={task.id}
              className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    {getStatusIcon(task.status)}
                    <h3 className="font-semibold text-[rgb(15,23,42)]">{task.title}</h3>
                  </div>
                  {task.description && (
                    <p className="text-[rgb(107,114,128)] text-sm mb-2">{task.description}</p>
                  )}
                </div>
                <button
                  onClick={() => handleDeleteTask(task.id)}
                  className="p-1 text-[rgb(107,114,128)] hover:text-[rgb(239,68,68)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(239,68,68)] focus:ring-offset-2 rounded"
                  aria-label="Delete task"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="flex flex-wrap gap-2 mb-3">
                <span className={`px-2 py-1 rounded-full text-xs font-medium text-[rgb(255,255,255)] ${getCategoryColor(task.category)}`}>
                  {TASK_CATEGORIES.find(c => c.value === task.category)?.label}
                </span>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${getPriorityColor(task.priority)} bg-[rgb(248,250,252)]`}>
                  {PRIORITY_LEVELS.find(p => p.value === task.priority)?.label} Priority
                </span>
                {task.dueDate && (
                  <span className="px-2 py-1 rounded-full text-xs font-medium text-[rgb(107,114,128)] bg-[rgb(248,250,252)] flex items-center gap-1">
                    <Calendar className="w-3 h-3" />
                    {new Date(task.dueDate).toLocaleDateString()}
                  </span>
                )}
              </div>

              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {task.assignedTo ? (
                    <>
                      <User className="w-4 h-4 text-[rgb(107,114,128)]" />
                      <span className="text-sm text-[rgb(15,23,42)]">{task.assignedToName}</span>
                    </>
                  ) : (
                    <span className="text-sm text-[rgb(107,114,128)]">Unassigned</span>
                  )}
                </div>

                <div className="flex gap-2">
                  {task.status !== 'completed' && (
                    <button
                      onClick={() => handleUpdateTaskStatus(task.id, task.status === 'pending' ? 'in-progress' : 'completed')}
                      className="px-3 py-1 text-xs font-medium bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-md hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[32px] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                    >
                      {task.status === 'pending' ? 'Start' : 'Complete'}
                    </button>
                  )}
                  {task.status === 'completed' && (
                    <button
                      onClick={() => handleUpdateTaskStatus(task.id, 'pending')}
                      className="px-3 py-1 text-xs font-medium bg-[rgb(107,114,128)] text-[rgb(255,255,255)] rounded-md hover:bg-[rgb(107,114,128)]/90 transition-colors min-h-[32px] focus:outline-none focus:ring-2 focus:ring-[rgb(107,114,128)] focus:ring-offset-2"
                    >
                      Reopen
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  )
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, Smile, MoreVertical, Users } from 'lucide-react';

interface Message {
  id: string;
  userId: string;
  userName: string;
  userAvatar?: string;
  content: string;
  timestamp: Date;
  type: 'text' | 'image' | 'file';
  isSystem?: boolean;
}

interface ChatUser {
  id: string;
  name: string;
  avatar?: string;
  isOnline: boolean;
}

interface ChatInterfaceProps {
  tripId: string;
  currentUserId: string;
  currentUserName: string;
  messages?: Message[];
  users?: ChatUser[];
  onSendMessage?: (content: string, type: 'text' | 'image' | 'file') => void;
  onTyping?: (isTyping: boolean) => void;
}

export default function ChatInterface({
  tripId,
  currentUserId,
  currentUserName,
  messages = [],
  users = [],
  onSendMessage,
  onTyping
}: ChatInterfaceProps) {
  const [messageInput, setMessageInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showUserList, setShowUserList] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = () => {
    if (messageInput.trim() && onSendMessage) {
      onSendMessage(messageInput.trim(), 'text');
      setMessageInput('');
      setIsTyping(false);
      onTyping?.(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setMessageInput(e.target.value);

    if (!isTyping && e.target.value.length > 0) {
      setIsTyping(true);
      onTyping?.(true);
    } else if (isTyping && e.target.value.length === 0) {
      setIsTyping(false);
      onTyping?.(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && onSendMessage) {
      // In a real implementation, you'd upload the file and get a URL
      onSendMessage(`Shared file: ${file.name}`, 'file');
    }
  };

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date);
  };

  const formatDate = (date: Date) => {
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    if (date.toDateString() === today.toDateString()) {
      return 'Today';
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday';
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date);
    }
  };

  const groupMessagesByDate = (messages: Message[]) => {
    const groups: { [key: string]: Message[] } = {};

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString();
      if (!groups[dateKey]) {
        groups[dateKey] = [];
      }
      groups[dateKey].push(message);
    });

    return Object.entries(groups).map(([date, msgs]) => ({
      date: new Date(date),
      messages: msgs
    }));
  };

  const messageGroups = groupMessagesByDate(messages);
  const onlineUsers = users.filter(user => user.isOnline);

  return (
    <div className="flex flex-col h-full bg-[rgb(255,255,255)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-[rgb(255,255,255)]">
        <div className="flex items-center gap-3">
          <h2 className="text-lg font-semibold text-[rgb(15,23,42)] font-medium">
            Trip Chat
          </h2>
          <div className="flex items-center gap-1 text-sm text-[rgb(100,116,139)]">
            <Users size={16} />
            <span>{onlineUsers.length} online</span>
          </div>
        </div>

        <button
          onClick={() => setShowUserList(!showUserList)}
          className="p-2 rounded-lg hover:bg-[rgb(241,245,249)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
          aria-label="Show user list"
        >
          <MoreVertical size={20} className="text-[rgb(100,116,139)]" />
        </button>
      </div>

      {/* User List Overlay */}
      {showUserList && (
        <div className="absolute top-16 right-4 z-10 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg shadow-lg p-4 min-w-48">
          <h3 className="font-medium text-[rgb(15,23,42)] mb-3">Group Members</h3>
          <div className="space-y-2">
            {users.map(user => (
              <div key={user.id} className="flex items-center gap-3">
                <div className="relative">
                  <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-medium">
                    {user.name.charAt(0).toUpperCase()}
                  </div>
                  {user.isOnline && (
                    <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-[rgb(34,139,34)] border-2 border-white rounded-full"></div>
                  )}
                </div>
                <span className="text-sm text-[rgb(15,23,42)]">{user.name}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messageGroups.map(({ date, messages: dayMessages }) => (
          <div key={date.toDateString()}>
            {/* Date Separator */}
            <div className="flex items-center justify-center my-4">
              <div className="bg-[rgb(241,245,249)] px-3 py-1 rounded-full">
                <span className="text-xs text-[rgb(100,116,139)] font-medium">
                  {formatDate(date)}
                </span>
              </div>
            </div>

            {/* Messages for this date */}
            {dayMessages.map((message, index) => {
              const isCurrentUser = message.userId === currentUserId;
              const showAvatar = !isCurrentUser && (
                index === 0 || 
                dayMessages[index - 1]?.userId !== message.userId
              );

              return (
                <div
                  key={message.id}
                  className={`flex gap-3 ${isCurrentUser ? 'justify-end' : 'justify-start'}`}
                >
                  {!isCurrentUser && (
                    <div className="w-8 h-8 flex-shrink-0">
                      {showAvatar && (
                        <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-medium">
                          {message.userName.charAt(0).toUpperCase()}
                        </div>
                      )}
                    </div>
                  )}

                  <div className={`max-w-xs lg:max-w-md ${isCurrentUser ? 'order-1' : ''}`}>
                    {showAvatar && !isCurrentUser && (
                      <div className="text-xs text-[rgb(100,116,139)] mb-1 font-medium">
                        {message.userName}
                      </div>
                    )}

                    <div
                      className={`px-4 py-2 rounded-lg ${
                        isCurrentUser
                          ? 'bg-[rgb(34,139,34)] text-white'
                          : message.isSystem
                          ? 'bg-[rgb(241,245,249)] text-[rgb(100,116,139)] text-center italic'
                          : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
                      }`}
                    >
                      <p className="text-sm leading-relaxed">{message.content}</p>
                      <div className={`text-xs mt-1 ${
                        isCurrentUser ? 'text-green-100' : 'text-[rgb(100,116,139)]'
                      }`}>
                        {formatTime(message.timestamp)}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(255,255,255)]">
        <div className="flex items-end gap-3">
          <input
            ref={fileInputRef}
            type="file"
            className="hidden"
            onChange={handleFileUpload}
            accept="image/*,.pdf,.doc,.docx"
          />

          <button
            onClick={() => fileInputRef.current?.click()}
            className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(241,245,249)] rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            aria-label="Attach file"
          >
            <Paperclip size={20} />
          </button>

          <div className="flex-1 relative">
            <textarea
              ref={inputRef}
              value={messageInput}
              onChange={handleInputChange}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 pr-12 border border-[rgb(226,232,240)] rounded-lg resize-none focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)]"
              rows={1}
              style={{ minHeight: '44px', maxHeight: '120px' }}
            />

            <button
              className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 rounded"
              aria-label="Add emoji"
            >
              <Smile size={20} />
            </button>
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!messageInput.trim()}
            className="p-3 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(22,101,22)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            style={{ minHeight: '44px', minWidth: '44px' }}
            aria-label="Send message"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { X, Bell, CheckCircle, AlertTriangle, Info, Calendar, Users, MapPin, MessageSquare } from 'lucide-react';

interface Notification {
  id: string;
  type: 'info' | 'success' | 'warning' | 'error' | 'trip' | 'task' | 'weather' | 'chat';
  title: string;
  message: string;
  timestamp: Date;
  read: boolean;
  actionUrl?: string;
  priority: 'low' | 'medium' | 'high';
  metadata?: {
    tripId?: string;
    taskId?: string;
    userId?: string;
    groupId?: string;
  };
}

interface NotificationSystemProps {
  notifications: Notification[];
  onMarkAsRead: (id: string) => void;
  onMarkAllAsRead: () => void;
  onDismiss: (id: string) => void;
  onNotificationClick: (notification: Notification) => void;
  className?: string;
}

const NotificationSystem: React.FC<NotificationSystemProps> = ({
  notifications,
  onMarkAsRead,
  onMarkAllAsRead,
  onDismiss,
  onNotificationClick,
  className = ''
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [filter, setFilter] = useState<'all' | 'unread' | 'trip' | 'task'>('all');

  const unreadCount = notifications.filter(n => !n.read).length;

  const getNotificationIcon = (type: Notification['type']) => {
    const iconClass = "w-5 h-5";
    switch (type) {
      case 'success':
        return <CheckCircle className={`${iconClass} text-[rgb(34,139,34)]`} />;
      case 'warning':
        return <AlertTriangle className={`${iconClass} text-[rgb(245,158,11)]`} />;
      case 'error':
        return <AlertTriangle className={`${iconClass} text-[rgb(239,68,68)]`} />;
      case 'trip':
        return <MapPin className={`${iconClass} text-[rgb(34,139,34)]`} />;
      case 'task':
        return <Users className={`${iconClass} text-[rgb(245,158,11)]`} />;
      case 'weather':
        return <Calendar className={`${iconClass} text-[rgb(34,139,34)]`} />;
      case 'chat':
        return <MessageSquare className={`${iconClass} text-[rgb(34,139,34)]`} />;
      default:
        return <Info className={`${iconClass} text-[rgb(34,139,34)]`} />;
    }
  };

  const getPriorityColor = (priority: Notification['priority']) => {
    switch (priority) {
      case 'high':
        return 'border-l-[rgb(239,68,68)]';
      case 'medium':
        return 'border-l-[rgb(245,158,11)]';
      default:
        return 'border-l-[rgb(34,139,34)]';
    }
  };

  const filteredNotifications = notifications.filter(notification => {
    switch (filter) {
      case 'unread':
        return !notification.read;
      case 'trip':
        return notification.type === 'trip' || notification.type === 'weather';
      case 'task':
        return notification.type === 'task';
      default:
        return true;
    }
  });

  const formatTimestamp = (timestamp: Date) => {
    const now = new Date();
    const diff = now.getTime() - timestamp.getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes}m ago`;
    if (hours < 24) return `${hours}h ago`;
    return `${days}d ago`;
  };

  const handleNotificationClick = useCallback((notification: Notification) => {
    if (!notification.read) {
      onMarkAsRead(notification.id);
    }
    onNotificationClick(notification);
    setIsOpen(false);
  }, [onMarkAsRead, onNotificationClick]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      setIsOpen(false);
    }
  }, []);

  useEffect(() => {
    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown as any);
      return () => document.removeEventListener('keydown', handleKeyDown as any);
    }
  }, [isOpen, handleKeyDown]);

  return (
    <div className={`relative ${className}`}>
      {/* Notification Bell Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 rounded-lg bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors"
        aria-label={`Notifications ${unreadCount > 0 ? `(${unreadCount} unread)` : ''}`}
        style={{ minHeight: '44px', minWidth: '44px' }}
      >
        <Bell className="w-5 h-5 text-[rgb(15,23,42)]" />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 bg-[rgb(239,68,68)] text-[rgb(255,255,255)] text-xs font-medium rounded-full min-w-[20px] h-5 flex items-center justify-center px-1">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {/* Notification Panel */}
      {isOpen && (
        <>
          {/* Backdrop */}
          <div
            className="fixed inset-0 bg-black bg-opacity-25 z-40 md:hidden"
            onClick={() => setIsOpen(false)}
          />

          {/* Panel */}
          <div className="absolute right-0 top-full mt-2 w-screen max-w-sm bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg shadow-lg z-50 md:w-96">
            {/* Header */}
            <div className="p-4 border-b border-[rgb(226,232,240)]">
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-lg font-semibold text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
                  Notifications
                </h3>
                <button
                  onClick={() => setIsOpen(false)}
                  className="p-1 rounded-md hover:bg-[rgb(241,245,249)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                  aria-label="Close notifications"
                >
                  <X className="w-4 h-4 text-[rgb(15,23,42)]" />
                </button>
              </div>

              {/* Filter Tabs */}
              <div className="flex gap-1 bg-[rgb(241,245,249)] p-1 rounded-md">
                {[
                  { key: 'all', label: 'All' },
                  { key: 'unread', label: 'Unread' },
                  { key: 'trip', label: 'Trips' },
                  { key: 'task', label: 'Tasks' }
                ].map(({ key, label }) => (
                  <button
                    key={key}
                    onClick={() => setFilter(key as any)}
                    className={`flex-1 px-3 py-1.5 text-sm font-medium rounded transition-colors ${
                      filter === key
                        ? 'bg-[rgb(255,255,255)] text-[rgb(15,23,42)] shadow-sm'
                        : 'text-[rgb(15,23,42)] hover:bg-[rgb(255,255,255)]'
                    }`}
                  >
                    {label}
                  </button>
                ))}
              </div>

              {/* Mark All Read */}
              {unreadCount > 0 && (
                <button
                  onClick={onMarkAllAsRead}
                  className="mt-3 text-sm text-[rgb(34,139,34)] hover:text-[rgb(34,139,34)] font-medium"
                >
                  Mark all as read
                </button>
              )}
            </div>

            {/* Notifications List */}
            <div className="max-h-96 overflow-y-auto">
              {filteredNotifications.length === 0 ? (
                <div className="p-6 text-center">
                  <Bell className="w-12 h-12 text-[rgb(226,232,240)] mx-auto mb-3" />
                  <p className="text-[rgb(15,23,42)] font-medium mb-1">No notifications</p>
                  <p className="text-sm text-[rgb(15,23,42)]">
                    {filter === 'unread' ? "You're all caught up!" : "We'll notify you when something happens."}
                  </p>
                </div>
              ) : (
                <div className="divide-y divide-[rgb(226,232,240)]">
                  {filteredNotifications.map((notification) => (
                    <div
                      key={notification.id}
                      className={`p-4 hover:bg-[rgb(248,250,252)] cursor-pointer transition-colors border-l-4 ${getPriorityColor(notification.priority)} ${
                        !notification.read ? 'bg-[rgb(248,250,252)]' : ''
                      }`}
                      onClick={() => handleNotificationClick(notification)}
                      role="button"
                      tabIndex={0}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          handleNotificationClick(notification);
                        }
                      }}
                    >
                      <div className="flex gap-3">
                        <div className="flex-shrink-0 mt-0.5">
                          {getNotificationIcon(notification.type)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex-1">
                              <p className={`text-sm font-medium text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif] ${
                                !notification.read ? 'font-semibold' : ''
                              }`}>
                                {notification.title}
                              </p>
                              <p className="text-sm text-[rgb(15,23,42)] mt-1 line-clamp-2">
                                {notification.message}
                              </p>
                              <p className="text-xs text-[rgb(15,23,42)] mt-2">
                                {formatTimestamp(notification.timestamp)}
                              </p>
                            </div>
                            <div className="flex items-center gap-1">
                              {!notification.read && (
                                <div className="w-2 h-2 bg-[rgb(34,139,34)] rounded-full" />
                              )}
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  onDismiss(notification.id);
                                }}
                                className="p-1 rounded-md hover:bg-[rgb(241,245,249)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                                aria-label="Dismiss notification"
                              >
                                <X className="w-3 h-3 text-[rgb(15,23,42)]" />
                              </button>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default NotificationSystem;

