  const acceptedCount = trip.participants.filter(p => p.rsvpStatus === 'accepted').length;
  const pendingCount = trip.participants.filter(p => p.rsvpStatus === 'pending').length;

  return (
    <div className="space-y-6">
      {/* RSVP Status */}
      <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
        <h2 className="text-lg font-semibold mb-3 text-[rgb(15,23,42)]">RSVP Status</h2>
        <div className="grid grid-cols-2 gap-4">
          <div className="text-center">
            <div className="text-2xl font-bold text-[rgb(34,139,34)]">{acceptedCount}</div>
            <div className="text-sm text-[rgb(15,23,42)]">Confirmed</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-[rgb(245,158,11)]">{pendingCount}</div>
            <div className="text-sm text-[rgb(15,23,42)]">Pending</div>
          </div>
        </div>
      </div>

      {/* Participants */}
      <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
        <h2 className="text-lg font-semibold mb-3 text-[rgb(15,23,42)]">Participants</h2>
        <div className="space-y-2">
          {trip.participants.map((participant) => (
            <div key={participant.id} className="flex items-center justify-between p-2 bg-[rgb(255,255,255)] rounded border border-[rgb(226,232,240)]">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-semibold">
                  {participant.name.charAt(0)}
                </div>
                <span className="text-[rgb(15,23,42)]">{participant.name}</span>
              </div>
              <span className={`px-2 py-1 rounded text-xs font-medium ${
                participant.rsvpStatus === 'accepted' 
                  ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                  : participant.rsvpStatus === 'pending'
                  ? 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
                  : 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]'
              }`}>
                {participant.rsvpStatus}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)] text-center">
          <div className="text-xl font-bold text-[rgb(34,139,34)]">{trip.tasks.length}</div>
          <div className="text-sm text-[rgb(15,23,42)]">Total Tasks</div>
        </div>
        <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)] text-center">
          <div className="text-xl font-bold text-[rgb(34,139,34)]">{trip.meals.length}</div>
          <div className="text-sm text-[rgb(15,23,42)]">Planned Meals</div>
        </div>
      </div>
    </div>
  );
};

// Tasks Tab Component
const TasksTab: React.FC<{ 
  tasks: Task[]; 
  onToggleComplete: (taskId: string) => void; 
  participants: Participant[] 
}> = ({ tasks, onToggleComplete, participants }) => {
  const getParticipantName = (id?: string) => {
    if (!id) return 'Unassigned';
    return participants.find(p => p.id === id)?.name || 'Unknown';
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'food': return 'bg-[rgb(245,158,11)]';
      case 'equipment': return 'bg-[rgb(34,139,34)]';
      case 'logistics': return 'bg-[rgb(239,68,68)]';
      default: return 'bg-[rgb(226,232,240)]';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Trip Tasks</h2>
        <button className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg text-sm font-medium min-h-[44px]">
          Add Task
        </button>
      </div>

      {tasks.map((task) => (
        <div key={task.id} className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
          <div className="flex items-start gap-3">
            <button
              onClick={() => onToggleComplete(task.id)}
              className={`w-5 h-5 rounded border-2 flex items-center justify-center mt-1 min-w-[20px] ${
                task.completed 
                  ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)]' 
                  : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)]'
              }`}
              aria-label={`Mark task ${task.title} as ${task.completed ? 'incomplete' : 'complete'}`}
            >
              {task.completed && (
                <svg className="w-3 h-3 text-[rgb(255,255,255)]" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
              )}
            </button>

            <div className="flex-1">
              <div className="flex items-center gap-2 mb-2">
                <h3 className={`font-medium ${task.completed ? 'line-through text-[rgb(226,232,240)]' : 'text-[rgb(15,23,42)]'}`}>
                  {task.title}
                </h3>
                <span className={`px-2 py-1 rounded text-xs text-[rgb(255,255,255)] ${getCategoryColor(task.category)}`}>
                  {task.category}
                </span>
              </div>

              <div className="flex items-center justify-between text-sm text-[rgb(15,23,42)]">
                <span>Assigned to: {getParticipantName(task.assignedTo)}</span>
                <span>Due: {new Date(task.dueDate).toLocaleDateString()}</span>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

