// Chat Tab Component
const ChatTab: React.FC<{ 
  messages: Message[]; 
  newMessage: string; 
  setNewMessage: (message: string) => void; 
  onSendMessage: () => void; 
}> = ({ messages, newMessage, setNewMessage, onSendMessage }) => {
  return (
    <div className="space-y-4">
      <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Group Chat</h2>

      {/* Messages */}
      <div className="space-y-3 max-h-96 overflow-y-auto">
        {messages.map((message) => (
          <div key={message.id} className="bg-[rgb(248,250,252)] rounded-lg p-3 border border-[rgb(226,232,240)]">
            <div className="flex justify-between items-start mb-1">
              <span className="font-medium text-[rgb(15,23,42)]">{message.sender}</span>
              <span className="text-xs text-[rgb(15,23,42)]">
                {new Date(message.timestamp).toLocaleTimeString()}
              </span>
            </div>
            <p className="text-[rgb(15,23,42)]">{message.content}</p>
          </div>
        ))}
      </div>

      {/* Message Input */}
      <div className="flex gap-2">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && onSendMessage()}
          placeholder="Type a message..."
          className="flex-1 p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
          aria-label="Type a message"
        />
        <button
          onClick={onSendMessage}
          className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg font-medium min-h-[44px] min-w-[44px]"
          aria-label="Send message"
        >
          Send
        </button>
      </div>
    </div>
  );
};

