export default TripPlannerApp;

'use client'

import React, { useState, useEffect } from 'react'
import { ChevronDownIcon, ChevronUpIcon, CheckIcon, XMarkIcon } from '@heroicons/react/24/outline'

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost'
  size?: 'default' | 'sm' | 'lg'
  children: React.ReactNode
}

interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string
  error?: string
}

interface SelectProps {
  value: string
  onValueChange: (value: string) => void
  children: React.ReactNode
  placeholder?: string
  disabled?: boolean
}

interface SelectItemProps {
  value: string
  children: React.ReactNode
}

interface CardProps {
  children: React.ReactNode
  className?: string
}

interface ToastProps {
  message: string
  type: 'success' | 'error' | 'info'
  onClose: () => void
}

interface SkeletonProps {
  className?: string
}

// Button Component
export const Button: React.FC<ButtonProps> = ({ 
  variant = 'default', 
  size = 'default', 
  className = '', 
  children, 
  disabled,
  ...props 
}) => {
  const baseClasses = 'inline-flex items-center justify-center rounded-md font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50'

  const variants = {
    default: 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)] hover:bg-[rgb(34,139,34)]/90 focus-visible:ring-[rgb(34,139,34)]',
    destructive: 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)] hover:bg-[rgb(239,68,68)]/90 focus-visible:ring-[rgb(239,68,68)]',
    outline: 'border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)] focus-visible:ring-[rgb(34,139,34)]',
    secondary: 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)] focus-visible:ring-[rgb(34,139,34)]',
    ghost: 'text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)] focus-visible:ring-[rgb(34,139,34)]'
  }

  const sizes = {
    default: 'h-11 px-4 py-2 min-h-[44px]',
    sm: 'h-9 px-3 text-sm min-h-[44px]',
    lg: 'h-12 px-8 min-h-[44px]'
  }

  return (
    <button
      className={`${baseClasses} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled}
      {...props}
    >
      {children}
    </button>
  )
}

// Input Component
export const Input: React.FC<InputProps> = ({ 
  label, 
  error, 
  className = '', 
  id,
  ...props 
}) => {
  const inputId = id || `input-${Math.random().toString(36).substr(2, 9)}`

  return (
    <div className="space-y-2">
      {label && (
        <label 
          htmlFor={inputId}
          className="text-sm font-medium text-[rgb(15,23,42)]"
        >
          {label}
        </label>
      )}
      <input
        id={inputId}
        className={`flex h-11 w-full rounded-md border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] px-3 py-2 text-sm font-medium placeholder:text-[rgb(148,163,184)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[rgb(34,139,34)] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 min-h-[44px] ${error ? 'border-[rgb(239,68,68)]' : ''} ${className}`}
        {...props}
      />
      {error && (
        <p className="text-sm text-[rgb(239,68,68)]" role="alert">
          {error}
        </p>
      )}
    </div>
  )
}

// Select Component
export const Select: React.FC<SelectProps> = ({ 
  value, 
  onValueChange, 
  children, 
  placeholder = 'Select an option',
  disabled = false 
}) => {
  const [isOpen, setIsOpen] = useState(false)
  const [selectedLabel, setSelectedLabel] = useState('')

  useEffect(() => {
    const findSelectedLabel = (children: React.ReactNode): string => {
      let label = ''
      React.Children.forEach(children, (child) => {
        if (React.isValidElement(child) && child.props.value === value) {
          label = child.props.children
        }
      })
      return label
    }

    setSelectedLabel(findSelectedLabel(children))
  }, [value, children])

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      setIsOpen(!isOpen)
    } else if (event.key === 'Escape') {
      setIsOpen(false)
    }
  }

  return (
    <div className="relative">
      <button
        type="button"
        className={`flex h-11 w-full items-center justify-between rounded-md border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] px-3 py-2 text-sm font-medium placeholder:text-[rgb(148,163,184)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[rgb(34,139,34)] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 min-h-[44px] ${isOpen ? 'ring-2 ring-[rgb(34,139,34)]' : ''}`}
        onClick={() => !disabled && setIsOpen(!isOpen)}
        onKeyDown={handleKeyDown}
        disabled={disabled}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        role="combobox"
      >
        <span className={selectedLabel ? 'text-[rgb(15,23,42)]' : 'text-[rgb(148,163,184)]'}>
          {selectedLabel || placeholder}
        </span>
        {isOpen ? (
          <ChevronUpIcon className="h-4 w-4 text-[rgb(148,163,184)]" />
        ) : (
          <ChevronDownIcon className="h-4 w-4 text-[rgb(148,163,184)]" />
        )}
      </button>

      {isOpen && (
        <div className="absolute top-full z-50 mt-1 w-full rounded-md border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] shadow-lg">
          <div className="max-h-60 overflow-auto p-1" role="listbox">
            {React.Children.map(children, (child) => {
              if (React.isValidElement(child)) {
                return React.cloneElement(child, {
                  onClick: () => {
                    onValueChange(child.props.value)
                    setIsOpen(false)
                  },
                  isSelected: child.props.value === value
                })
              }
              return child
            })}
          </div>
        </div>
      )}
    </div>
  )
}

// SelectItem Component
export const SelectItem: React.FC<SelectItemProps & { onClick?: () => void; isSelected?: boolean }> = ({ 
  value, 
  children, 
  onClick,
  isSelected = false 
}) => {
  return (
    <div
      className={`relative flex cursor-pointer select-none items-center rounded-sm px-2 py-2 text-sm font-medium outline-none hover:bg-[rgb(241,245,249)] focus:bg-[rgb(241,245,249)] min-h-[44px] ${isSelected ? 'bg-[rgb(241,245,249)]' : ''}`}
      onClick={onClick}
      role="option"
      aria-selected={isSelected}
    >
      {children}
      {isSelected && (
        <CheckIcon className="ml-auto h-4 w-4 text-[rgb(34,139,34)]" />
      )}
    </div>
  )
}

// Card Component
export const Card: React.FC<CardProps> = ({ children, className = '' }) => {
  return (
    <div className={`rounded-lg border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] shadow-md ${className}`}>
      {children}
    </div>
  )
}

export const CardHeader: React.FC<{ children: React.ReactNode; className?: string }> = ({ 
  children, 
  className = '' 
}) => {
  return (
    <div className={`flex flex-col space-y-1.5 p-6 ${className}`}>
      {children}
    </div>
  )
}

export const CardTitle: React.FC<{ children: React.ReactNode; className?: string }> = ({ 
  children, 
  className = '' 
}) => {
  return (
    <h3 className={`text-lg font-semibold leading-none tracking-tight text-[rgb(15,23,42)] ${className}`}>
      {children}
    </h3>
  )
}

export const CardContent: React.FC<{ children: React.ReactNode; className?: string }> = ({ 
  children, 
  className = '' 
}) => {
  return (
    <div className={`p-6 pt-0 ${className}`}>
      {children}
    </div>
  )
}

// Toast Component
export const Toast: React.FC<ToastProps> = ({ message, type, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose()
    }, 5000)

    return () => clearTimeout(timer)
  }, [onClose])

  const typeStyles = {
    success: 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]',
    error: 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]',
    info: 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
  }

  return (
    <div className={`fixed bottom-4 right-4 z-50 flex items-center gap-2 rounded-md px-4 py-3 shadow-lg ${typeStyles[type]}`}>
      <span className="text-sm font-medium">{message}</span>
      <button
        onClick={onClose}
        className="ml-2 rounded-sm opacity-70 hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-offset-2"
        aria-label="Close notification"
      >
        <XMarkIcon className="h-4 w-4" />
      </button>
    </div>
  )
}

// Skeleton Component
export const Skeleton: React.FC<SkeletonProps> = ({ className = '' }) => {
  return (
    <div className={`animate-pulse rounded-md bg-[rgb(241,245,249)] ${className}`} />
  )
}

// Badge Component
export const Badge: React.FC<{ 
  children: React.ReactNode
  variant?: 'default' | 'secondary' | 'destructive' | 'outline'
  className?: string 
}> = ({ 
  children, 
  variant = 'default', 
  className = '' 
}) => {
  const variants = {
    default: 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)] hover:bg-[rgb(34,139,34)]/80',
    secondary: 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]',
    destructive: 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)] hover:bg-[rgb(239,68,68)]/80',
    outline: 'border border-[rgb(226,232,240)] text-[rgb(15,23,42)]'
  }

  return (
    <div className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium transition-colors ${variants[variant]} ${className}`}>
      {children}
    </div>
  )
}

// Dialog Component
export const Dialog: React.FC<{ 
  open: boolean
  onOpenChange: (open: boolean) => void
  children: React.ReactNode 
}> = ({ open, onOpenChange, children }) => {
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onOpenChange(false)
      }
    }

    if (open) {
      document.addEventListener('keydown', handleEscape)
      document.body.style.overflow = 'hidden'
    }

    return () => {
      document.removeEventListener('keydown', handleEscape)
      document.body.style.overflow = 'unset'
    }
  }, [open, onOpenChange])

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div 
        className="fixed inset-0 bg-black/50" 
        onClick={() => onOpenChange(false)}
        aria-hidden="true"
      />
      <div className="relative z-50 w-full max-w-lg mx-4">
        {children}
      </div>
    </div>
  )
}

export const DialogContent: React.FC<{ 
  children: React.ReactNode
  className?: string 
}> = ({ children, className = '' }) => {
  return (
    <div className={`rounded-lg border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] shadow-lg p-6 ${className}`}>
      {children}
    </div>
  )
}

export const DialogHeader: React.FC<{ 
  children: React.ReactNode
  className?: string 
}> = ({ children, className = '' }) => {
  return (
    <div className={`flex flex-col space-y-1.5 text-center sm:text-left mb-4 ${className}`}>
      {children}
    </div>
  )
}

export const DialogTitle: React.FC<{ 
  children: React.ReactNode
  className?: string 
}> = ({ children, className = '' }) => {
  return (
    <h2 className={`text-lg font-semibold leading-none tracking-tight text-[rgb(15,23,42)] ${className}`}>
      {children}
    </h2>
  )
}

// Textarea Component
export const Textarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement> & {
  label?: string
  error?: string
}> = ({ 
  label, 
  error, 
  className = '', 
  id,
  ...props 
}) => {
  const textareaId = id || `textarea-${Math.random().toString(36).substr(2, 9)}`

  return (
    <div className="space-y-2">
      {label && (
        <label 
          htmlFor={textareaId}
          className="text-sm font-medium text-[rgb(15,23,42)]"
        >
          {label}
        </label>
      )}
      <textarea
        id={textareaId}
        className={`flex min-h-[80px] w-full rounded-md border border-[rgb(226,232,240)] bg-[rgb(255,255,255)] px-3 py-2 text-sm font-medium placeholder:text-[rgb(148,163,184)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[rgb(34,139,34)] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 resize-none ${error ? 'border-[rgb(239,68,68)]' : ''} ${className}`}
        {...props}
      />
      {error && (
        <p className="text-sm text-[rgb(239,68,68)]" role="alert">
          {error}
        </p>
      )}
    </div>
  )
}

export default {
  Button,
  Input,
  Select,
  SelectItem,
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Toast,
  Skeleton,
  Badge,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  Textarea
}

