'use client';

import React from 'react';
import { cn } from '@/lib/utils';

// Type definitions for shadcn/ui setup
interface ShadcnConfig {
  style: string;
  rsc: boolean;
  tsx: boolean;
  tailwind: {
    config: string;
    css: string;
    baseColor: string;
    cssVariables: boolean;
  };
  aliases: {
    components: string;
    utils: string;
  };
}

interface ComponentInfo {
  name: string;
  description: string;
  installed: boolean;
  dependencies: string[];
}

interface ShadcnSetupProps {
  className?: string;
  onConfigUpdate?: (config: ShadcnConfig) => void;
  onComponentInstall?: (componentName: string) => void;
}

const ShadcnSetup: React.FC<ShadcnSetupProps> = ({
  className,
  onConfigUpdate,
  onComponentInstall
}) => {
  const [config, setConfig] = React.useState<ShadcnConfig>({
    style: 'default',
    rsc: true,
    tsx: true,
    tailwind: {
      config: 'tailwind.config.js',
      css: 'app/globals.css',
      baseColor: 'slate',
      cssVariables: true
    },
    aliases: {
      components: '@/components',
      utils: '@/lib/utils'
    }
  });

  const [installedComponents, setInstalledComponents] = React.useState<Set<string>>(new Set());

  const availableComponents: ComponentInfo[] = [
    {
      name: 'button',
      description: 'Displays a button or a component that looks like a button.',
      installed: false,
      dependencies: ['@radix-ui/react-slot']
    },
    {
      name: 'card',
      description: 'Displays a card with header, content, and footer.',
      installed: false,
      dependencies: []
    },
    {
      name: 'input',
      description: 'Displays a form input field or a component that looks like an input field.',
      installed: false,
      dependencies: []
    },
    {
      name: 'label',
      description: 'Renders an accessible label associated with controls.',
      installed: false,
      dependencies: ['@radix-ui/react-label']
    },
    {
      name: 'toast',
      description: 'A succinct message that is displayed temporarily.',
      installed: false,
      dependencies: ['@radix-ui/react-toast']
    },
    {
      name: 'dialog',
