              checked={config.rsc}
              onChange={(e) => handleConfigChange('rsc', e.target.checked)}
              className="w-4 h-4 text-[rgb(34,139,34)] border-[rgb(226,232,240)] rounded
                         focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              aria-label="Enable React Server Components"
            />
            <label htmlFor="rsc-toggle" className="text-sm text-[rgb(15,23,42)]">
              Use React Server Components
