      {/* Components Section */}
      <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-md">
        <h2 className="text-lg font-semibold mb-4 text-[rgb(15,23,42)]">
