                  {isInstalled && (
                    <span className="text-xs bg-[rgb(34,139,34)] text-[rgb(255,255,255)] 
                                   px-2 py-1 rounded-full">
                      Installed
                    </span>
                  )}
                </div>

                <p className="text-xs text-[rgb(100,116,139)] leading-relaxed">
                  {component.description}
                </p>

                {component.dependencies.length > 0 && (
                  <div className="text-xs text-[rgb(100,116,139)]">
                    <span className="font-medium">Dependencies:</span>
                    <div className="mt-1 space-y-1">
                      {component.dependencies.map((dep) => (
                        <div key={dep} className="font-mono text-xs bg-[rgb(241,245,249)] 
                                                 px-2 py-1 rounded">
                          {dep}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <button
                  onClick={() => handleComponentInstall(component.name)}
                  disabled={isInstalled}
                  className={cn(
                    'w-full px-3 py-2 text-sm font-medium rounded-md transition-colors',
                    'min-h-[44px] focus:outline-none focus:ring-2 focus:ring-offset-2',
                    isInstalled
                      ? 'bg-[rgb(241,245,249)] text-[rgb(100,116,139)] cursor-not-allowed'
                      : 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)] hover:bg-[rgb(22,101,22)] focus:ring-[rgb(34,139,34)]'
                  )}
                  aria-label={`Install ${component.name} component`}
                >
                  {isInstalled ? 'Installed' : 'Install'}
