export default function GroupManagement({ 
  groupId, 
  onMemberAdded, 
  onMemberRemoved, 
  onGroupUpdated 
}: GroupManagementProps) {
  const [members, setMembers] = useState<GroupMember[]>(mockMembers);
  const [group, setGroup] = useState<Group>(mockGroup);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedMember, setSelectedMember] = useState<GroupMember | null>(null);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [showMemberDetails, setShowMemberDetails] = useState(false);
  const [showGroupSettings, setShowGroupSettings] = useState(false);
  const [loading, setLoading] = useState(false);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<'member' | 'admin'>('member');

  // Filter members based on search query
  const filteredMembers = members.filter(member =>
    member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    member.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
    member.skills?.some(skill => skill.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  // Handle member invitation
  const handleInviteMember = async () => {
    if (!inviteEmail.trim()) return;

    setLoading(true);
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));

      const newMember: GroupMember = {
        id: Date.now().toString(),
        name: inviteEmail.split('@')[0],
        email: inviteEmail,
        role: inviteRole,
        status: 'pending',
        joinedAt: new Date()
      };

      setMembers(prev => [...prev, newMember]);
      setInviteEmail('');
      setShowInviteModal(false);
      onMemberAdded?.(newMember);
    } catch (error) {
      console.error('Failed to invite member:', error);
    } finally {
      setLoading(false);
    }
  };

  // Handle member removal
  const handleRemoveMember = async (memberId: string) => {
    setLoading(true);
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500));

      setMembers(prev => prev.filter(m => m.id !== memberId));
      onMemberRemoved?.(memberId);
      setShowMemberDetails(false);
    } catch (error) {
      console.error('Failed to remove member:', error);
    } finally {
      setLoading(false);
    }
  };

  // Get role icon
  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'owner':
        return <Crown className="w-4 h-4 text-[rgb(245,158,11)]" />;
      case 'admin':
        return <Shield className="w-4 h-4 text-[rgb(34,139,34)]" />;
      default:
        return <User className="w-4 h-4 text-[rgb(100,116,139)]" />;
    }
  };

  // Get status color
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-[rgb(34,139,34)]';
      case 'pending':
        return 'bg-[rgb(245,158,11)]';
      default:
        return 'bg-[rgb(100,116,139)]';
    }
  };

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-3">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Group Management</h1>
            <p className="text-sm text-[rgb(100,116,139)]">{group.name} • {members.length} members</p>
          </div>
          <button
            onClick={() => setShowGroupSettings(true)}
            className="p-2 rounded-lg bg-[rgb(248,250,252)] hover:bg-[rgb(241,245,249)] transition-colors"
            aria-label="Group settings"
          >
            <Settings className="w-5 h-5 text-[rgb(100,116,139)]" />
          </button>
        </div>
      </div>

      {/* Search and Actions */}
      <div className="p-4 space-y-4">
        <div className="flex gap-3">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(100,116,139)]" />
            <input
              type="text"
              placeholder="Search members..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
            />
          </div>
          <button
            onClick={() => setShowInviteModal(true)}
            className="px-4 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(22,101,52)] transition-colors flex items-center gap-2 min-w-[44px] min-h-[44px]"
            aria-label="Invite member"
          >
            <UserPlus className="w-4 h-4" />
            <span className="hidden sm:inline">Invite</span>
          </button>
        </div>

        {/* Member List */}
        <div className="space-y-2">
          {filteredMembers.map((member) => (
            <div
              key={member.id}
              className="bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg p-4 hover:shadow-md transition-shadow cursor-pointer"
              onClick={() => {
                setSelectedMember(member);
                setShowMemberDetails(true);
              }}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="relative">
                    <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] font-semibold">
                      {member.name.charAt(0).toUpperCase()}
                    </div>
                    <div className={`absolute -bottom-1 -right-1 w-3 h-3 ${getStatusColor(member.status)} rounded-full border-2 border-[rgb(255,255,255)]`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className="font-semibold text-[rgb(15,23,42)] truncate">{member.name}</h3>
                      {getRoleIcon(member.role)}
                    </div>
                    <p className="text-sm text-[rgb(100,116,139)] truncate">{member.email}</p>
                    {member.skills && member.skills.length > 0 && (
                      <div className="flex gap-1 mt-1">
                        {member.skills.slice(0, 2).map((skill) => (
                          <span
                            key={skill}
                            className="px-2 py-1 bg-[rgb(241,245,249)] text-xs text-[rgb(100,116,139)] rounded"
                          >
                            {skill}
                          </span>
                        ))}
                        {member.skills.length > 2 && (
                          <span className="px-2 py-1 bg-[rgb(241,245,249)] text-xs text-[rgb(100,116,139)] rounded">
                            +{member.skills.length - 2}
                          </span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`px-2 py-1 text-xs rounded-full ${
                    member.status === 'active' 
                      ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                      : member.status === 'pending'
                      ? 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
                      : 'bg-[rgb(100,116,139)] text-[rgb(255,255,255)]'
                  }`}>
                    {member.status}
                  </span>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedMember(member);
                      setShowMemberDetails(true);
                    }}
                    className="p-1 hover:bg-[rgb(241,245,249)] rounded"
                    aria-label="Member options"
                  >
                    <MoreVertical className="w-4 h-4 text-[rgb(100,116,139)]" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredMembers.length === 0 && (
          <div className="text-center py-8">
            <User className="w-12 h-12 text-[rgb(100,116,139)] mx-auto mb-3" />
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-1">No members found</h3>
            <p className="text-[rgb(100,116,139)]">Try adjusting your search or invite new members</p>
          </div>
        )}
      </div>

      {/* Invite Modal */}
      {showInviteModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-[rgb(255,255,255)] rounded-lg p-6 w-full max-w-md">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Invite Member</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Email Address
                </label>
                <input
                  type="email"
                  value={inviteEmail}
                  onChange={(e) => setInviteEmail(e.target.value)}
                  placeholder="Enter email address"
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Role
                </label>
                <select
                  value={inviteRole}
                  onChange={(e) => setInviteRole(e.target.value as 'member' | 'admin')}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]"
                >
                  <option value="member">Member</option>
                  <option value="admin">Admin</option>
                </select>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setShowInviteModal(false)}
                className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] text-[rgb(100,116,139)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleInviteMember}
                disabled={!inviteEmail.trim() || loading}
                className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(22,101,52)] disabled:opacity-50 transition-colors"
              >
                {loading ? 'Sending...' : 'Send Invite'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Member Details Modal */}
      {showMemberDetails && selectedMember && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-[rgb(255,255,255)] rounded-lg p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Member Details</h2>
              <button
                onClick={() => setShowMemberDetails(false)}
                className="p-1 hover:bg-[rgb(248,250,252)] rounded"
              >
                <Plus className="w-5 h-5 text-[rgb(100,116,139)] rotate-45" />
              </button>
            </div>

            <div className="space-y-4">
              {/* Profile */}
              <div className="text-center">
                <div className="w-16 h-16 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] font-bold text-xl mx-auto mb-2">
                  {selectedMember.name.charAt(0).toUpperCase()}
                </div>
                <h3 className="font-semibold text-[rgb(15,23,42)]">{selectedMember.name}</h3>
                <div className="flex items-center justify-center gap-2 mt-1">
                  {getRoleIcon(selectedMember.role)}
                  <span className="text-sm text-[rgb(100,116,139)] capitalize">{selectedMember.role}</span>
                </div>
              </div>

              {/* Contact Info */}
              <div className="space-y-3">
                <div className="flex items-center gap-3">
                  <Mail className="w-4 h-4 text-[rgb(100,116,139)]" />
                  <span className="text-sm text-[rgb(15,23,42)]">{selectedMember.email}</span>
                </div>
                {selectedMember.phone && (
                  <div className="flex items-center gap-3">
                    <Phone className="w-4 h-4 text-[rgb(100,116,139)]" />
                    <span className="text-sm text-[rgb(15,23,42)]">{selectedMember.phone}</span>
                  </div>
                )}
                <div className="flex items-center gap-3">
                  <Calendar className="w-4 h-4 text-[rgb(100,116,139)]" />
                  <span className="text-sm text-[rgb(15,23,42)]">
                    Joined {selectedMember.joinedAt.toLocaleDateString()}
                  </span>
                </div>
              </div>

              {/* Skills */}
              {selectedMember.skills && selectedMember.skills.length > 0 && (
                <div>
                  <h4 className="font-medium text-[rgb(15,23,42)] mb-2">Skills</h4>
                  <div className="flex flex-wrap gap-2">
                    {selectedMember.skills.map((skill) => (
                      <span
                        key={skill}
                        className="px-2 py-1 bg-[rgb(248,250,252)] text-sm text-[rgb(100,116,139)] rounded"
                      >
                        {skill}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {/* Emergency Contact */}
              {selectedMember.emergencyContact && (
                <div>
                  <h4 className="font-medium text-[rgb(15,23,42)] mb-2">Emergency Contact</h4>
                  <div className="bg-[rgb(248,250,252)] p-3 rounded-lg space-y-1">
                    <p className="text-sm text-[rgb(15,23,42)]">{selectedMember.emergencyContact.name}</p>
                    <p className="text-sm text-[rgb(100,116,139)]">{selectedMember.emergencyContact.phone}</p>
                    <p className="text-xs text-[rgb(100,116,139)]">{selectedMember.emergencyContact.relationship}</p>
                  </div>
                </div>
              )}

              {/* Actions */}
              <div className="flex gap-2 pt-4">
                <button className="flex-1 px-3 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(22,101,52)] transition-colors flex items-center justify-center gap-2">
                  <MessageCircle className="w-4 h-4" />
                  Message
                </button>
                {selectedMember.role !== 'owner' && (
                  <button
                    onClick={() => handleRemoveMember(selectedMember.id)}
                    disabled={loading}
                    className="px-3 py-2 bg-[rgb(239,68,68)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(220,38,38)] disabled:opacity-50 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Calendar, Clock, Users, MapPin, Send, Check, X, Plus, Edit2, Trash2 } from 'lucide-react';

interface GroupMember {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  availability: { [date: string]: 'available' | 'unavailable' | 'maybe' };
}

interface TripEvent {
  id: string;
  title: string;
  description?: string;
  startDate: Date;
  endDate: Date;
  location: string;
  organizer: string;
  attendees: string[];
  rsvpStatus: { [memberId: string]: 'yes' | 'no' | 'maybe' | 'pending' };
  tasks: Task[];
  meals: Meal[];
  weather?: WeatherData;
}

interface Task {
  id: string;
  title: string;
  description?: string;
  assignedTo?: string;
  dueDate?: Date;
  completed: boolean;
}

interface Meal {
  id: string;
  name: string;
  date: Date;
  time: string;
  assignedTo?: string;
  ingredients?: string[];
}

interface WeatherData {
  temperature: number;
  condition: string;
  precipitation: number;
  windSpeed: number;
}

interface CalendarIntegration {
  provider: 'google' | 'outlook' | 'apple';
  connected: boolean;
  lastSync?: Date;
}

const SchedulingComponent: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'calendar' | 'tasks' | 'meals' | 'rsvp'>('overview');
  const [selectedEvent, setSelectedEvent] = useState<TripEvent | null>(null);
  const [isCreatingEvent, setIsCreatingEvent] = useState(false);
  const [groupMembers, setGroupMembers] = useState<GroupMember[]>([]);
  const [events, setEvents] = useState<TripEvent[]>([]);
  const [calendarIntegrations, setCalendarIntegrations] = useState<CalendarIntegration[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [eventForm, setEventForm] = useState({
    title: '',
    description: '',
    startDate: '',
    endDate: '',
    location: '',
    attendees: [] as string[]
  });

  const [taskForm, setTaskForm] = useState({
    title: '',
    description: '',
    assignedTo: '',
    dueDate: ''
  });

  const [mealForm, setMealForm] = useState({
    name: '',
    date: '',
    time: '',
    assignedTo: ''
  });

  useEffect(() => {
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    setLoading(true);
    try {
      // Simulate API calls
      await Promise.all([
        loadGroupMembers(),
        loadEvents(),
        loadCalendarIntegrations()
      ]);
    } catch (err) {
      setError('Failed to load data. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const loadGroupMembers = async () => {
    // Mock data - replace with actual API call
    setGroupMembers([
      {
        id: '1',
        name: 'John Doe',
        email: 'john@example.com',
        availability: {
          '2024-01-15': 'available',
          '2024-01-16': 'available'
        }
      },
      {
        id: '2',
        name: 'Jane Smith',
        email: 'jane@example.com',
        availability: {
          '2024-01-15': 'maybe',
          '2024-01-16': 'available'
        }
      }
    ]);
  };

  const loadEvents = async () => {
    // Mock data - replace with actual API call
    setEvents([]);
  };

  const loadCalendarIntegrations = async () => {
    setCalendarIntegrations([
      { provider: 'google', connected: false },
      { provider: 'outlook', connected: false },
      { provider: 'apple', connected: false }
    ]);
  };

  const createEvent = async () => {
    if (!eventForm.title || !eventForm.startDate || !eventForm.endDate) {
      setError('Please fill in all required fields');
      return;
    }

    setLoading(true);
    try {
      const newEvent: TripEvent = {
        id: Date.now().toString(),
        title: eventForm.title,
        description: eventForm.description,
        startDate: new Date(eventForm.startDate),
        endDate: new Date(eventForm.endDate),
        location: eventForm.location,
        organizer: 'current-user',
        attendees: eventForm.attendees,
        rsvpStatus: {},
        tasks: [],
        meals: []
      };

      setEvents(prev => [...prev, newEvent]);
      setSelectedEvent(newEvent);
      setIsCreatingEvent(false);
      setEventForm({
        title: '',
        description: '',
        startDate: '',
        endDate: '',
        location: '',
        attendees: []
      });

      // Send calendar invites
      await sendCalendarInvites(newEvent);
    } catch (err) {
      setError('Failed to create event');
    } finally {
      setLoading(false);
    }
  };

  const sendCalendarInvites = async (event: TripEvent) => {
    // Implement calendar invite logic
    console.log('Sending calendar invites for:', event.title);
  };

  const addTask = async () => {
    if (!selectedEvent || !taskForm.title) return;

    const newTask: Task = {
      id: Date.now().toString(),
      title: taskForm.title,
      description: taskForm.description,
      assignedTo: taskForm.assignedTo,
      dueDate: taskForm.dueDate ? new Date(taskForm.dueDate) : undefined,
      completed: false
    };

    const updatedEvent = {
      ...selectedEvent,
      tasks: [...selectedEvent.tasks, newTask]
    };

    setSelectedEvent(updatedEvent);
    setEvents(prev => prev.map(e => e.id === selectedEvent.id ? updatedEvent : e));
    setTaskForm({ title: '', description: '', assignedTo: '', dueDate: '' });
  };

  const addMeal = async () => {
    if (!selectedEvent || !mealForm.name || !mealForm.date) return;

    const newMeal: Meal = {
      id: Date.now().toString(),
      name: mealForm.name,
      date: new Date(mealForm.date),
      time: mealForm.time,
      assignedTo: mealForm.assignedTo
    };

    const updatedEvent = {
      ...selectedEvent,
      meals: [...selectedEvent.meals, newMeal]
    };

    setSelectedEvent(updatedEvent);
    setEvents(prev => prev.map(e => e.id === selectedEvent.id ? updatedEvent : e));
    setMealForm({ name: '', date: '', time: '', assignedTo: '' });
  };

  const updateRSVP = async (eventId: string, memberId: string, status: 'yes' | 'no' | 'maybe') => {
    setEvents(prev => prev.map(event => 
      event.id === eventId 
        ? { ...event, rsvpStatus: { ...event.rsvpStatus, [memberId]: status } }
        : event
    ));

    if (selectedEvent?.id === eventId) {
      setSelectedEvent(prev => prev ? {
        ...prev,
        rsvpStatus: { ...prev.rsvpStatus, [memberId]: status }
      } : null);
    }
  };

  const connectCalendar = async (provider: 'google' | 'outlook' | 'apple') => {
    setLoading(true);
    try {
      // Implement OAuth flow for calendar integration
      setCalendarIntegrations(prev => 
        prev.map(integration => 
          integration.provider === provider 
            ? { ...integration, connected: true, lastSync: new Date() }
            : integration
        )
      );
    } catch (err) {
      setError(`Failed to connect ${provider} calendar`);
    } finally {
      setLoading(false);
    }
  };

  if (loading && events.length === 0) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] p-4">
        <div className="max-w-4xl mx-auto space-y-4">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-32 bg-[rgb(241,245,249)] rounded-lg animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Trip Scheduling</h1>
            <p className="text-[rgb(100,116,139)] text-sm">Plan and coordinate your off-road adventures</p>
          </div>
          <button
            onClick={() => setIsCreatingEvent(true)}
            className="flex items-center gap-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
            aria-label="Create new trip"
          >
            <Plus size={20} />
            <span>New Trip</span>
          </button>
        </div>

        {error && (
          <div className="bg-[rgb(239,68,68)]/10 border border-[rgb(239,68,68)]/20 text-[rgb(239,68,68)] p-4 rounded-lg">
            {error}
            <button 
              onClick={() => setError(null)}
              className="ml-2 underline hover:no-underline"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* Calendar Integrations */}
        <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
          <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Calendar Integrations</h3>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {calendarIntegrations.map((integration) => (
              <button
                key={integration.provider}
                onClick={() => !integration.connected && connectCalendar(integration.provider)}
                className={`p-3 rounded-lg border transition-colors min-h-[44px] ${
                  integration.connected
                    ? 'bg-[rgb(34,139,34)]/10 border-[rgb(34,139,34)]/20 text-[rgb(34,139,34)]'
                    : 'bg-[rgb(255,255,255)] border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:border-[rgb(34,139,34)]'
                }`}
                disabled={integration.connected}
                aria-label={`${integration.connected ? 'Connected to' : 'Connect'} ${integration.provider} calendar`}
              >
                <div className="flex items-center justify-between">
                  <span className="capitalize">{integration.provider}</span>
                  {integration.connected ? <Check size={16} /> : <Plus size={16} />}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Events List */}
        <div className="space-y-4">
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Upcoming Trips</h2>

          {events.length === 0 ? (
            <div className="text-center py-12 bg-[rgb(248,250,252)] rounded-lg">
              <Calendar size={48} className="mx-auto text-[rgb(148,163,184)] mb-4" />
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No trips planned</h3>
              <p className="text-[rgb(100,116,139)] mb-4">Create your first off-road adventure</p>
              <button
                onClick={() => setIsCreatingEvent(true)}
                className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-6 py-2 rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
              >
                Plan a Trip
              </button>
            </div>
          ) : (
            <div className="grid gap-4">
              {events.map((event) => (
                <div
                  key={event.id}
                  className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow cursor-pointer"
                  onClick={() => setSelectedEvent(event)}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => e.key === 'Enter' && setSelectedEvent(event)}
                  aria-label={`View details for ${event.title}`}
                >
                  <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                    <div className="flex-1">
                      <h3 className="font-semibold text-[rgb(15,23,42)]">{event.title}</h3>
                      <div className="flex flex-wrap items-center gap-4 mt-2 text-sm text-[rgb(100,116,139)]">
                        <div className="flex items-center gap-1">
                          <Calendar size={16} />
                          <span>{event.startDate.toLocaleDateString()}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <MapPin size={16} />
                          <span>{event.location}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Users size={16} />
                          <span>{event.attendees.length} attendees</span>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm text-[rgb(100,116,139)]">
                        {Object.values(event.rsvpStatus).filter(status => status === 'yes').length} confirmed
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Event Creation Modal */}
        {isCreatingEvent && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-[rgb(255,255,255)] rounded-lg p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Create New Trip</h2>
                <button
                  onClick={() => setIsCreatingEvent(false)}
                  className="p-2 hover:bg-[rgb(241,245,249)] rounded-lg transition-colors"
                  aria-label="Close modal"
                >
                  <X size={20} />
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Trip Title *
                  </label>
                  <input
                    type="text"
                    value={eventForm.title}
                    onChange={(e) => setEventForm(prev => ({ ...prev, title: e.target.value }))}
                    className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                    placeholder="Weekend Desert Adventure"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Description
                  </label>
                  <textarea
                    value={eventForm.description}
                    onChange={(e) => setEventForm(prev => ({ ...prev, description: e.target.value }))}
                    className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                    rows={3}
                    placeholder="Describe your adventure..."
                  />
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                      Start Date *
                    </label>
                    <input
                      type="date"
                      value={eventForm.startDate}
                      onChange={(e) => setEventForm(prev => ({ ...prev, startDate: e.target.value }))}
                      className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                      End Date *
                    </label>
                    <input
                      type="date"
                      value={eventForm.endDate}
                      onChange={(e) => setEventForm(prev => ({ ...prev, endDate: e.target.value }))}
                      className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Location
                  </label>
                  <input
                    type="text"
                    value={eventForm.location}
                    onChange={(e) => setEventForm(prev => ({ ...prev, location: e.target.value }))}
                    className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                    placeholder="Moab, Utah"
                  />
                </div>

                <div className="flex gap-3 pt-4">
                  <button
                    onClick={() => setIsCreatingEvent(false)}
                    className="flex-1 p-3 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(241,245,249)] transition-colors min-h-[44px]"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={createEvent}
                    disabled={loading}
                    className="flex-1 p-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors disabled:opacity-50 min-h-[44px]"
                  >
                    {loading ? 'Creating...' : 'Create Trip'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Event Details Modal */}
        {selectedEvent && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-[rgb(255,255,255)] rounded-lg w-full max-w-4xl max-h-[90vh] overflow-hidden">
              <div className="flex items-center justify-between p-6 border-b border-[rgb(226,232,240)]">
                <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">{selectedEvent.title}</h2>
                <button
                  onClick={() => setSelectedEvent(null)}
                  className="p-2 hover:bg-[rgb(241,245,249)] rounded-lg transition-colors"
                  aria-label="Close event details"
                >
                  <X size={20} />
                </button>
              </div>

              <div className="flex border-b border-[rgb(226,232,240)]">
                {(['overview', 'tasks', 'meals', 'rsvp'] as const).map((tab) => (
                  <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-6 py-3 text-sm font-medium transition-colors min-h-[44px] ${
                      activeTab === tab
                        ? 'text-[rgb(34,139,34)] border-b-2 border-[rgb(34,139,34)]'
                        : 'text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]'
                    }`}
                  >
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                  </button>
                ))}
              </div>

              <div className="p-6 overflow-y-auto max-h-[60vh]">
                {activeTab === 'overview' && (
                  <div className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div>
                        <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Trip Details</h3>
                        <div className="space-y-3">
                          <div className="flex items-center gap-2 text-sm">
                            <Calendar size={16} className="text-[rgb(100,116,139)]" />
                            <span>{selectedEvent.startDate.toLocaleDateString()} - {selectedEvent.endDate.toLocaleDateString()}</span>
                          </div>
                          <div className="flex items-center gap-2 text-sm">
                            <MapPin size={16} className="text-[rgb(100,116,139)]" />
                            <span>{selectedEvent.location}</span>
                          </div>
                          <div className="flex items-center gap-2 text-sm">
                            <Users size={16} className="text-[rgb(100,116,139)]" />
                            <span>{selectedEvent.attendees.length} attendees</span>
                          </div>
                        </div>
                      </div>

                      {selectedEvent.weather && (
                        <div>
                          <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Weather Forecast</h3>
                          <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
                            <div className="text-2xl font-bold text-[rgb(15,23,42)]">
                              {selectedEvent.weather.temperature}°F
                            </div>
                            <div className="text-sm text-[rgb(100,116,139)]">
                              {selectedEvent.weather.condition}
                            </div>
                          </div>
                        </div>
                      )}
                    </div>

                    {selectedEvent.description && (
                      <div>
                        <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Description</h3>
                        <p className="text-[rgb(100,116,139)]">{selectedEvent.description}</p>
                      </div>
                    )}
                  </div>
                )}

                {activeTab === 'tasks' && (
                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="font-semibold text-[rgb(15,23,42)]">Tasks</h3>
                    </div>

                    <div className="bg-[rgb(248,250,252)] p-4 rounded-lg space-y-3">
                      <h4 className="font-medium text-[rgb(15,23,42)]">Add New Task</h4>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        <input
                          type="text"
                          value={taskForm.title}
                          onChange={(e) => setTaskForm(prev => ({ ...prev, title: e.target.value }))}
                          placeholder="Task title"
                          className="p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                        />
                        <select
                          value={taskForm.assignedTo}
                          onChange={(e) => setTaskForm(prev => ({ ...prev, assignedTo: e.target.value }))}
                          className="p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                        >
                          <option value="">Assign to...</option>
                          {groupMembers.map(member => (
                            <option key={member.id} value={member.id}>{member.name}</option>
                          ))}
                        </select>
                      </div>
                      <button
                        onClick={addTask}
                        disabled={!taskForm.title}
                        className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors disabled:opacity-50 min-h-[44px]"
                      >
                        Add Task
                      </button>
                    </div>

                    <div className="space-y-3">
                      {selectedEvent.tasks.map((task) => (
                        <div key={task.id} className="flex items-center gap-3 p-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg">
                          <input
                            type="checkbox"
                            checked={task.completed}
                            onChange={() => {
                              const updatedEvent = {
                                ...selectedEvent,
                                tasks: selectedEvent.tasks.map(t => 
                                  t.id === task.id ? { ...t, completed: !t.completed } : t
                                )
                              };
                              setSelectedEvent(updatedEvent);
                            }}
                            className="w-5 h-5 text-[rgb(34,139,34)] rounded focus:ring-[rgb(34,139,34)]"
                          />
                          <div className="flex-1">
                            <div className={`font-medium ${task.completed ? 'line-through text-[rgb(100,116,139)]' : 'text-[rgb(15,23,42)]'}`}>
                              {task.title}
                            </div>
                            {task.assignedTo && (
                              <div className="text-sm text-[rgb(100,116,139)]">
                                Assigned to: {groupMembers.find(m => m.id === task.assignedTo)?.name}
                              </div>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {activeTab === 'meals' && (
                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="font-semibold text-[rgb(15,23,42)]">Meal Planning</h3>
                    </div>

                    <div className="bg-[rgb(248,250,252)] p-4 rounded-lg space-y-3">
                      <h4 className="font-medium text-[rgb(15,23,42)]">Add Meal</h4>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                        <input
                          type="text"
                          value={mealForm.name}
                          onChange={(e) => setMealForm(prev => ({ ...prev, name: e.target.value }))}
                          placeholder="Meal name"
                          className="p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                        />
                        <input
                          type="date"
                          value={mealForm.date}
                          onChange={(e) => setMealForm(prev => ({ ...prev, date: e.target.value }))}
                          className="p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                        />
                        <select
                          value={mealForm.assignedTo}
                          onChange={(e) => setMealForm(prev => ({ ...prev, assignedTo: e.target.value }))}
                          className="p-3 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                        >
                          <option value="">Assign to...</option>
                          {groupMembers.map(member => (
                            <option key={member.id} value={member.id}>{member.name}</option>
                          ))}
                        </select>
                      </div>
                      <button
                        onClick={addMeal}
                        disabled={!mealForm.name || !mealForm.date}
                        className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors disabled:opacity-50 min-h-[44px]"
                      >
                        Add Meal
                      </button>
                    </div>

                    <div className="space-y-3">
                      {selectedEvent.meals.map((meal) => (
                        <div key={meal.id} className="p-4 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg">
                          <div className="flex items-center justify-between">
                            <div>
                              <div className="font-medium text-[rgb(15,23,42)]">{meal.name}</div>
                              <div className="text-sm text-[rgb(100,116,139)]">
                                {meal.date.toLocaleDateString()} {meal.time && `at ${meal.time}`}
                              </div>
                              {meal.assignedTo && (
                                <div className="text-sm text-[rgb(100,116,139)]">
                                  Prepared by: {groupMembers.find(m => m.id === meal.assignedTo)?.name}
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {activeTab === 'rsvp' && (
                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="font-semibold text-[rgb(15,23,42)]">RSVP Status</h3>
                      <button
                        onClick={() => sendCalendarInvites(selectedEvent)}
                        className="flex items-center gap-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
                      >
                        <Send size={16} />
                        Send Invites
                      </button>
                    </div>

                    <div className="space-y-3">
                      {groupMembers.map((member) => {
                        const rsvpStatus = selectedEvent.rsvpStatus[member.id] || 'pending';
                        return (
                          <div key={member.id} className="flex items-center justify-between p-4 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg">
                            <div className="flex items-center gap-3">
                              <div className="w-10 h-10 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-full flex items-center justify-center font-medium">
                                {member.name.charAt(0)}
                              </div>
                              <div>
                                <div className="font-medium text-[rgb(15,23,42)]">{member.name}</div>
                                <div className="text-sm text-[rgb(100,116,139)]">{member.email}</div>
                              </div>
                            </div>
                            <div className="flex gap-2">
                              {(['yes', 'maybe', 'no'] as const).map((status) => (
                                <button
                                  key={status}
                                  onClick={() => updateRSVP(selectedEvent.id, member.id, status)}
                                  className={`px-3 py-1 rounded-lg text-sm transition-colors min-h-[36px] ${
                                    rsvpStatus === status
                                      ? status === 'yes'
                                        ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                                        : status === 'maybe'
                                        ? 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
                                        : 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]'
                                      : 'bg-[rgb(241,245,249)] text-[rgb(100,116,139)] hover:bg-[rgb(226,232,240)]'
                                  }`}
                                >
                                  {status === 'yes' ? 'Yes' : status === 'maybe' ? 'Maybe' : 'No'}
                                </button>
                              ))}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SchedulingComponent;

code.layout:
'use client'

import { useState } from 'react'
import { 
  Menu, 
  X, 
  MapPin, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed,
  Settings,
  Home,
  Bell
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet'
import { Badge } from '@/components/ui/badge'

interface AppLayoutProps {
  children?: React.ReactNode;
  currentPage?: string;
  notifications?: number;
  onNavigate?: (page: string) => void;
}

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  badge?: number;
  href: string;
}

const DEFAULT_NAVIGATION: NavigationItem[] = [
  { id: 'dashboard', label: 'Dashboard', icon: Home, href: '/dashboard' },
  { id: 'trips', label: 'Trip Planning', icon: MapPin, href: '/trips' },
  { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
  { id: 'group', label: 'Group Tasks', icon: Users, href: '/group' },
  { id: 'chat', label: 'Group Chat', icon: MessageCircle, badge: 3, href: '/chat' },
  { id: 'meals', label: 'Meal Planning', icon: UtensilsCrossed, href: '/meals' },
  { id: 'settings', label: 'Settings', icon: Settings, href: '/settings' }
];

export function AppLayout({
  children,
  currentPage = 'dashboard',
  notifications = 0,
  onNavigate = (page: string) => console.log('Navigate to:', page)
}: AppLayoutProps = {}) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleNavigation = (page: string) => {
    onNavigate(page);
    setIsMobileMenuOpen(false);
  };

  const NavigationContent = () => (
    <nav className="flex flex-col h-full">
      <div className="p-6 border-b border-[rgb(226,232,240)]">
        <h1 className="text-xl font-bold text-[rgb(15,23,42)] font-medium">
          Off-Road Planner
        </h1>
        <p className="text-sm text-[rgb(100,116,139)] mt-1">
          Adventure awaits
        </p>
      </div>

      <div className="flex-1 p-4 space-y-2">
        {DEFAULT_NAVIGATION.map((item) => {
          const Icon = item.icon;
          const isActive = currentPage === item.id;

          return (
            <button
              key={item.id}
              onClick={() => handleNavigation(item.id)}
              className={`
                w-full flex items-center gap-3 px-3 py-3 rounded-lg text-left transition-colors
                focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2
                ${isActive 
                  ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]' 
                  : 'text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                }
              `}
              aria-label={`Navigate to ${item.label}`}
              aria-current={isActive ? 'page' : undefined}
            >
              <Icon className="w-5 h-5 flex-shrink-0" />
              <span className="font-medium text-sm">{item.label}</span>
              {item.badge && (
                <Badge 
                  variant="secondary" 
                  className="ml-auto bg-[rgb(245,158,11)] text-[rgb(255,255,255)] text-xs"
                >
                  {item.badge}
                </Badge>
              )}
            </button>
          );
        })}
      </div>
    </nav>
  );

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] flex">
      {/* Desktop Sidebar */}
      <aside className="hidden lg:flex lg:w-64 lg:flex-col lg:border-r lg:border-[rgb(226,232,240)]">
        <NavigationContent />
      </aside>

      {/* Mobile Navigation */}
      <Sheet open={isMobileMenuOpen} onOpenChange={setIsMobileMenuOpen}>
        <SheetContent side="left" className="w-64 p-0">
          <NavigationContent />
        </SheetContent>
      </Sheet>

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <header className="bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-3 lg:px-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Sheet open={isMobileMenuOpen} onOpenChange={setIsMobileMenuOpen}>
                <SheetTrigger asChild>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="lg:hidden p-2"
                    aria-label="Open navigation menu"
                  >
                    <Menu className="w-5 h-5" />
                  </Button>
                </SheetTrigger>
              </Sheet>

              <h2 className="text-lg font-semibold text-[rgb(15,23,42)] font-medium capitalize">
                {currentPage.replace(/([A-Z])/g, ' $1').trim()}
              </h2>
            </div>

            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                size="sm"
                className="relative p-2"
                aria-label={`Notifications ${notifications > 0 ? `(${notifications} unread)` : ''}`}
              >
                <Bell className="w-5 h-5" />
                {notifications > 0 && (
                  <Badge 
                    className="absolute -top-1 -right-1 w-5 h-5 p-0 flex items-center justify-center bg-[rgb(220,38,38)] text-[rgb(255,255,255)] text-xs"
                  >
                    {notifications > 99 ? '99+' : notifications}
                  </Badge>
                )}
              </Button>
            </div>
          </div>
        </header>

        {/* Main Content Area */}
        <main className="flex-1 overflow-auto">
          <div className="p-4 lg:p-6">
            {children || (
              <div className="max-w-4xl mx-auto">
                <div className="bg-[rgb(248,250,252)] rounded-lg p-8 text-center shadow-sm">
                  <MapPin className="w-12 h-12 mx-auto mb-4 text-[rgb(34,139,34)]" />
                  <h3 className="text-xl font-semibold text-[rgb(15,23,42)] mb-2 font-medium">
                    Welcome to Off-Road Planner
                  </h3>
                  <p className="text-[rgb(100,116,139)] mb-6">
                    Plan your next adventure with friends. Organize trips, assign tasks, 
