'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Plus, ArrowLeft } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'

interface TripFormData {
  name: string
  description: string
  startDate: string
  endDate: string
  location: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard'
  tags: string[]
}

interface CreateTripPageProps {
  onBack?: () => void
  onSubmit?: (data: TripFormData) => void
  initialData?: Partial<TripFormData>
}

export function CreateTripPage({
  onBack = () => console.log('Back clicked'),
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {}
}: CreateTripPageProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    description: '',
    startDate: '',
    endDate: '',
    location: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    tags: [],
    ...initialData
  })

  const [currentTag, setCurrentTag] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && formData.startDate > formData.endDate) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (formData.maxParticipants < 1) {
      newErrors.maxParticipants = 'Must allow at least 1 participant'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 1000)) // Simulate API call
      onSubmit(formData)
    } catch (error) {
      console.error('Failed to create trip:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleInputChange = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const addTag = () => {
    if (currentTag.trim() && !formData.tags.includes(currentTag.trim())) {
      handleInputChange('tags', [...formData.tags, currentTag.trim()])
      setCurrentTag('')
    }
  }

  const removeTag = (tagToRemove: string) => {
    handleInputChange('tags', formData.tags.filter(tag => tag !== tagToRemove))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      addTag()
    }
  }

  const difficultyColors = {
    easy: 'bg-[rgb(34,139,34)] text-white',
    moderate: 'bg-[rgb(245,158,11)] text-white',
    hard: 'bg-[rgb(220,38,38)] text-white'
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] shadow-sm">
        <div className="max-w-4xl mx-auto px-4 py-4">
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="sm"
              onClick={onBack}
              className="p-2 hover:bg-[rgb(241,245,249)]"
              aria-label="Go back"
            >
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Create New Trip</h1>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-4xl mx-auto px-4 py-6">
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Basic Information */}
          <Card className="border-[rgb(226,232,240)] shadow-md">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-[rgb(15,23,42)]">
                <MapPin className="h-5 w-5 text-[rgb(34,139,34)]" />
                Trip Details
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label htmlFor="name" className="text-[rgb(15,23,42)]">
                  Trip Name *
                </Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  placeholder="Enter trip name"
                  className={`mt-1 ${errors.name ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                  aria-describedby={errors.name ? 'name-error' : undefined}
                />
                {errors.name && (
                  <p id="name-error" className="text-sm text-[rgb(220,38,38)] mt-1">
                    {errors.name}
                  </p>
                )}
              </div>

              <div>
                <Label htmlFor="description" className="text-[rgb(15,23,42)]">
                  Description
                </Label>
                <Textarea
                  id="description"
                  value={formData.description}
                  onChange={(e) => handleInputChange('description', e.target.value)}
                  placeholder="Describe your off-road adventure..."
                  rows={3}
                  className="mt-1 border-[rgb(226,232,240)] resize-none"
                />
              </div>

              <div>
                <Label htmlFor="location" className="text-[rgb(15,23,42)]">
                  Location *
                </Label>
                <Input
                  id="location"
                  value={formData.location}
                  onChange={(e) => handleInputChange('location', e.target.value)}
                  placeholder="Enter destination"
                  className={`mt-1 ${errors.location ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                  aria-describedby={errors.location ? 'location-error' : undefined}
                />
                {errors.location && (
                  <p id="location-error" className="text-sm text-[rgb(220,38,38)] mt-1">
                    {errors.location}
                  </p>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Dates and Participants */}
          <Card className="border-[rgb(226,232,240)] shadow-md">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-[rgb(15,23,42)]">
                <Calendar className="h-5 w-5 text-[rgb(34,139,34)]" />
                Schedule & Capacity
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="startDate" className="text-[rgb(15,23,42)]">
                    Start Date *
                  </Label>
                  <Input
                    id="startDate"
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => handleInputChange('startDate', e.target.value)}
                    className={`mt-1 ${errors.startDate ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                    aria-describedby={errors.startDate ? 'startDate-error' : undefined}
                  />
                  {errors.startDate && (
                    <p id="startDate-error" className="text-sm text-[rgb(220,38,38)] mt-1">
                      {errors.startDate}
                    </p>
                  )}
                </div>

                <div>
                  <Label htmlFor="endDate" className="text-[rgb(15,23,42)]">
                    End Date *
                  </Label>
                  <Input
                    id="endDate"
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => handleInputChange('endDate', e.target.value)}
                    className={`mt-1 ${errors.endDate ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                    aria-describedby={errors.endDate ? 'endDate-error' : undefined}
                  />
                  {errors.endDate && (
                    <p id="endDate-error" className="text-sm text-[rgb(220,38,38)] mt-1">
                      {errors.endDate}
                    </p>
                  )}
                </div>
              </div>

              <div>
                <Label htmlFor="maxParticipants" className="text-[rgb(15,23,42)]">
                  Maximum Participants
                </Label>
                <Input
                  id="maxParticipants"
                  type="number"
                  min="1"
                  max="50"
                  value={formData.maxParticipants}
                  onChange={(e) => handleInputChange('maxParticipants', parseInt(e.target.value) || 1)}
                  className={`mt-1 ${errors.maxParticipants ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                  aria-describedby={errors.maxParticipants ? 'maxParticipants-error' : undefined}
                />
                {errors.maxParticipants && (
                  <p id="maxParticipants-error" className="text-sm text-[rgb(220,38,38)] mt-1">
                    {errors.maxParticipants}
                  </p>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Difficulty and Tags */}
          <Card className="border-[rgb(226,232,240)] shadow-md">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-[rgb(15,23,42)]">
                <Users className="h-5 w-5 text-[rgb(34,139,34)]" />
                Trip Settings
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label className="text-[rgb(15,23,42)]">Difficulty Level</Label>
                <div className="flex gap-2 mt-2">
                  {(['easy', 'moderate', 'hard'] as const).map((level) => (
                    <Button
                      key={level}
                      type="button"
                      variant={formData.difficulty === level ? 'default' : 'outline'}
                      onClick={() => handleInputChange('difficulty', level)}
                      className={`capitalize ${
                        formData.difficulty === level 
                          ? difficultyColors[level]
                          : 'border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                      }`}
                    >
                      {level}
                    </Button>
                  ))}
                </div>
              </div>

              <div>
                <Label htmlFor="tags" className="text-[rgb(15,23,42)]">
                  Tags
                </Label>
                <div className="flex gap-2 mt-1">
                  <Input
                    id="tags"
                    value={currentTag}
                    onChange={(e) => setCurrentTag(e.target.value)}
                    onKeyPress={handleKeyPress}
                    placeholder="Add tags (e.g., camping, hiking)"
                    className="border-[rgb(226,232,240)]"
                  />
                  <Button
                    type="button"
                    onClick={addTag}
                    size="sm"
                    className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white px-3"
                    aria-label="Add tag"
                  >
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>

                {formData.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-2">
                    {formData.tags.map((tag) => (
                      <Badge
                        key={tag}
                        variant="secondary"
                        className="bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border border-[rgb(226,232,240)]"
                      >
                        {tag}
                        <button
                          type="button"
                          onClick={() => removeTag(tag)}
                          className="ml-1 hover:text-[rgb(220,38,38)]"
                          aria-label={`Remove ${tag} tag`}
                        >
                          ×
                        </button>
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Submit Button */}
          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={onBack}
              className="border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white min-w-[120px]"
            >
              {isSubmitting ? (
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Creating...
                </div>
              ) : (
                'Create Trip'
              )}
            </Button>
          </div>
        </form>
      </div>
    </div>
  )
}

// Demo component for page.tsx
export default function CreateTripPageDemo() {
  return <CreateTripPage />
}

