'use client'

import { useState } from 'react'
import { Send, User, Clock, CheckCheck } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'

interface ChatMessage {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  content: string
  timestamp: Date
  status: 'sent' | 'delivered' | 'read'
  type: 'text' | 'system'
}

interface ChatUser {
  id: string
  name: string
  avatar?: string
  isOnline: boolean
  lastSeen?: Date
}

interface ChatModelProps {
  tripId?: string
  messages?: ChatMessage[]
  users?: ChatUser[]
  currentUserId?: string
  onSendMessage?: (content: string) => void
  onMessageRead?: (messageId: string) => void
  className?: string
}

export function ChatModel({
  tripId = 'trip-1',
  messages = DEFAULT_MESSAGES,
  users = DEFAULT_USERS,
  currentUserId = 'user-1',
  onSendMessage = (content: string) => console.log('Send message:', content),
  onMessageRead = (messageId: string) => console.log('Message read:', messageId),
  className = ''
}: ChatModelProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [localMessages, setLocalMessages] = useState<ChatMessage[]>(messages)

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: ChatMessage = {
      id: `msg-${Date.now()}`,
      userId: currentUserId,
      userName: users.find(u => u.id === currentUserId)?.name || 'You',
      content: newMessage.trim(),
      timestamp: new Date(),
      status: 'sent',
      type: 'text'
    }

    setLocalMessages(prev => [...prev, message])
    onSendMessage(newMessage.trim())
    setNewMessage('')
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const getMessageStatusIcon = (status: ChatMessage['status']) => {
    switch (status) {
      case 'sent':
        return <Clock className="w-3 h-3 text-[rgb(148,163,184)]" />
      case 'delivered':
        return <CheckCheck className="w-3 h-3 text-[rgb(148,163,184)]" />
      case 'read':
        return <CheckCheck className="w-3 h-3 text-[rgb(34,139,34)]" />
      default:
        return null
    }
  }

  const groupMessagesByDate = (messages: ChatMessage[]) => {
    const groups: { [key: string]: ChatMessage[] } = {}

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString()
      if (!groups[dateKey]) {
        groups[dateKey] = []
      }
      groups[dateKey].push(message)
    })

    return Object.entries(groups).map(([date, msgs]) => ({
      date: new Date(date),
      messages: msgs
    }))
  }

  const messageGroups = groupMessagesByDate(localMessages)
  const onlineUsers = users.filter(user => user.isOnline && user.id !== currentUserId)

  return (
    <div className={`flex flex-col h-full bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg shadow-md ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <div className="flex items-center gap-3">
          <h3 className="font-semibold text-[rgb(15,23,42)] text-lg">Trip Chat</h3>
          <Badge variant="secondary" className="text-xs">
            {users.length} members
          </Badge>
        </div>

        {onlineUsers.length > 0 && (
          <div className="flex items-center gap-2">
            <div className="flex -space-x-2">
              {onlineUsers.slice(0, 3).map(user => (
                <Avatar key={user.id} className="w-6 h-6 border-2 border-white">
                  <AvatarImage src={user.avatar} alt={user.name} />
                  <AvatarFallback className="text-xs bg-[rgb(34,139,34)] text-white">
                    {user.name.charAt(0)}
                  </AvatarFallback>
                </Avatar>
              ))}
            </div>
            {onlineUsers.length > 3 && (
              <span className="text-xs text-[rgb(100,116,139)]">
                +{onlineUsers.length - 3} online
              </span>
            )}
          </div>
        )}
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 p-4">
        <div className="space-y-4">
          {messageGroups.map(({ date, messages: dayMessages }) => (
            <div key={date.toISOString()}>
              {/* Date Separator */}
              <div className="flex items-center justify-center my-4">
                <div className="bg-[rgb(241,245,249)] px-3 py-1 rounded-full">
                  <span className="text-xs text-[rgb(100,116,139)] font-medium">
                    {formatDate(date)}
                  </span>
                </div>
              </div>

              {/* Messages for this date */}
              <div className="space-y-3">
                {dayMessages.map((message) => {
                  const isCurrentUser = message.userId === currentUserId
                  const user = users.find(u => u.id === message.userId)

                  if (message.type === 'system') {
                    return (
                      <div key={message.id} className="flex justify-center">
                        <div className="bg-[rgb(241,245,249)] px-3 py-1 rounded-full max-w-xs">
                          <p className="text-xs text-[rgb(100,116,139)] text-center">
                            {message.content}
                          </p>
                        </div>
                      </div>
                    )
                  }

                  return (
                    <div
                      key={message.id}
                      className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : 'flex-row'}`}
                    >
                      {!isCurrentUser && (
                        <Avatar className="w-8 h-8 flex-shrink-0">
                          <AvatarImage src={user?.avatar} alt={message.userName} />
                          <AvatarFallback className="bg-[rgb(34,139,34)] text-white text-sm">
                            {message.userName.charAt(0)}
                          </AvatarFallback>
                        </Avatar>
                      )}

                      <div className={`flex flex-col max-w-[70%] ${isCurrentUser ? 'items-end' : 'items-start'}`}>
                        {!isCurrentUser && (
                          <span className="text-xs text-[rgb(100,116,139)] font-medium mb-1">
                            {message.userName}
                          </span>
                        )}

                        <div
                          className={`px-3 py-2 rounded-lg ${
                            isCurrentUser
                              ? 'bg-[rgb(34,139,34)] text-white'
                              : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
                          }`}
                        >
                          <p className="text-sm leading-relaxed break-words">
                            {message.content}
                          </p>
                        </div>

                        <div className={`flex items-center gap-1 mt-1 ${isCurrentUser ? 'flex-row-reverse' : 'flex-row'}`}>
                          <span className="text-xs text-[rgb(148,163,184)]">
                            {formatTime(message.timestamp)}
                          </span>
                          {isCurrentUser && getMessageStatusIcon(message.status)}
                        </div>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      </ScrollArea>

      {/* Message Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <div className="flex gap-2">
          <Input
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Type a message..."
            className="flex-1 bg-white border-[rgb(226,232,240)] focus:border-[rgb(34,139,34)] focus:ring-[rgb(34,139,34)]"
            aria-label="Type your message"
          />
          <Button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            size="icon"
            className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white min-w-[44px] min-h-[44px]"
            aria-label="Send message"
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </div>
  )
}

