  description: 'Join us for an epic off-roading adventure through the stunning red rock landscapes of Moab. We\'ll tackle challenging trails, camp under the stars, and create unforgettable memories.',
  organizer: 'Sarah Johnson'
}

const DEFAULT_RESPONSES: RSVPResponse[] = [
  {
    id: '1',
    userId: 'user1',
    userName: 'Mike Chen',
    userAvatar: '/avatars/mike.jpg',
    status: 'attending',
    response: 'Can\'t wait! I\'ll bring my Jeep Wrangler.',
    respondedAt: new Date('2024-01-15')
