export function RSVPModel({
  trip = DEFAULT_TRIP,
  currentUserId = 'current-user',
  responses = DEFAULT_RESPONSES,
  onRSVP = (status, response) => console.log('RSVP:', status, response),
  onClose = () => console.log('Close RSVP'),
  isOpen = true
}: RSVPModelProps = {}) {
  const [selectedStatus, setSelectedStatus] = useState<'attending' | 'not-attending' | 'maybe' | null>(null)
  const [responseText, setResponseText] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const currentUserResponse = responses.find(r => r.userId === currentUserId)
  const hasResponded = currentUserResponse && currentUserResponse.status !== 'pending'

  const statusCounts = {
    attending: responses.filter(r => r.status === 'attending').length,
    maybe: responses.filter(r => r.status === 'maybe').length,
    notAttending: responses.filter(r => r.status === 'not-attending').length,
    pending: responses.filter(r => r.status === 'pending').length
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })
  }

  const handleSubmitRSVP = async () => {
    if (!selectedStatus) return

    setIsSubmitting(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 1000)) // Simulate API call
      onRSVP(selectedStatus, responseText || undefined)
      setSelectedStatus(null)
      setResponseText('')
    } finally {
      setIsSubmitting(false)
    }
  }

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
      case 'attending':
        return 'default'
      case 'maybe':
        return 'secondary'
      case 'not-attending':
        return 'destructive'
      default:
        return 'outline'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'attending':
        return <Check className="w-3 h-3" />
      case 'not-attending':
        return <X className="w-3 h-3" />
      default:
        return null
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-lg shadow-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <Card className="border-0 shadow-none">
          <CardHeader className="border-b border-[rgb(226,232,240)]">
            <div className="flex items-start justify-between">
              <div className="space-y-2">
                <CardTitle className="text-xl font-semibold text-[rgb(15,23,42)]">
                  {trip.title}
                </CardTitle>
                <div className="flex flex-wrap gap-4 text-sm text-gray-600">
                  <div className="flex items-center gap-1">
                    <MapPin className="w-4 h-4" />
                    {trip.location}
                  </div>
                  <div className="flex items-center gap-1">
                    <Calendar className="w-4 h-4" />
                    {formatDate(trip.startDate)}
                  </div>
                  <div className="flex items-center gap-1">
                    <Clock className="w-4 h-4" />
                    {Math.ceil((trip.endDate.getTime() - trip.startDate.getTime()) / (1000 * 60 * 60 * 24))} days
                  </div>
                </div>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={onClose}
                className="text-gray-500 hover:text-gray-700"
                aria-label="Close RSVP modal"
              >
                <X className="w-5 h-5" />
              </Button>
            </div>
          </CardHeader>

          <CardContent className="p-6 space-y-6">
            {/* Trip Description */}
            <div>
              <p className="text-[rgb(15,23,42)] leading-relaxed">
                {trip.description}
              </p>
            </div>

            {/* RSVP Summary */}
            <div className="bg-[rgb(248,250,252)] rounded-lg p-4">
              <div className="flex items-center gap-2 mb-3">
                <Users className="w-5 h-5 text-[rgb(34,139,34)]" />
                <h3 className="font-medium text-[rgb(15,23,42)]">RSVP Summary</h3>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                <div className="text-center">
                  <div className="text-2xl font-bold text-[rgb(34,139,34)]">
                    {statusCounts.attending}
                  </div>
                  <div className="text-xs text-gray-600">Attending</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-[rgb(245,158,11)]">
                    {statusCounts.maybe}
                  </div>
                  <div className="text-xs text-gray-600">Maybe</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-[rgb(220,38,38)]">
                    {statusCounts.notAttending}
                  </div>
                  <div className="text-xs text-gray-600">Not Going</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-gray-400">
                    {statusCounts.pending}
                  </div>
                  <div className="text-xs text-gray-600">Pending</div>
                </div>
              </div>
            </div>

            {/* Current User RSVP */}
            {!hasResponded && (
              <div className="border border-[rgb(226,232,240)] rounded-lg p-4">
                <h3 className="font-medium text-[rgb(15,23,42)] mb-4">Your Response</h3>

                <div className="space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                    <Button
                      variant={selectedStatus === 'attending' ? 'default' : 'outline'}
                      onClick={() => setSelectedStatus('attending')}
                      className={`h-12 ${selectedStatus === 'attending' ? 'bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90' : ''}`}
                      aria-label="RSVP as attending"
                    >
                      <Check className="w-4 h-4 mr-2" />
                      I'll be there
                    </Button>
                    <Button
                      variant={selectedStatus === 'maybe' ? 'default' : 'outline'}
                      onClick={() => setSelectedStatus('maybe')}
                      className={`h-12 ${selectedStatus === 'maybe' ? 'bg-[rgb(245,158,11)] hover:bg-[rgb(245,158,11)]/90' : ''}`}
                      aria-label="RSVP as maybe"
                    >
                      Maybe
                    </Button>
                    <Button
                      variant={selectedStatus === 'not-attending' ? 'destructive' : 'outline'}
                      onClick={() => setSelectedStatus('not-attending')}
                      className="h-12"
                      aria-label="RSVP as not attending"
                    >
                      <X className="w-4 h-4 mr-2" />
                      Can't make it
                    </Button>
                  </div>

                  {selectedStatus && (
                    <div className="space-y-2">
                      <Label htmlFor="response-text" className="text-sm font-medium">
                        Add a note (optional)
                      </Label>
                      <Textarea
                        id="response-text"
                        placeholder="Let everyone know your thoughts..."
                        value={responseText}
                        onChange={(e) => setResponseText(e.target.value)}
                        className="min-h-[80px]"
                        aria-describedby="response-help"
                      />
                      <p id="response-help" className="text-xs text-gray-500">
                        Share any questions, what you're bringing, or just your excitement!
                      </p>
                    </div>
                  )}

                  {selectedStatus && (
                    <Button
                      onClick={handleSubmitRSVP}
                      disabled={isSubmitting}
                      className="w-full bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 h-12"
                      aria-label="Submit RSVP response"
                    >
                      {isSubmitting ? 'Submitting...' : 'Submit RSVP'}
                    </Button>
                  )}
                </div>
              </div>
            )}

            {/* Current User's Response (if already responded) */}
            {hasResponded && currentUserResponse && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <div className="flex items-center gap-2 mb-2">
                  <Check className="w-5 h-5 text-green-600" />
                  <h3 className="font-medium text-green-800">Your Response</h3>
                </div>
                <div className="flex items-center gap-2 mb-2">
                  <Badge variant={getStatusBadgeVariant(currentUserResponse.status)}>
                    {getStatusIcon(currentUserResponse.status)}
                    <span className="ml-1 capitalize">
                      {currentUserResponse.status === 'not-attending' ? 'Not Attending' : currentUserResponse.status}
                    </span>
                  </Badge>
                  {currentUserResponse.respondedAt && (
                    <span className="text-xs text-gray-500">
                      Responded {currentUserResponse.respondedAt.toLocaleDateString()}
                    </span>
                  )}
                </div>
                {currentUserResponse.response && (
                  <p className="text-sm text-gray-700 italic">
                    "{currentUserResponse.response}"
                  </p>
                )}
              </div>
            )}

            {/* All Responses */}
            <div>
              <h3 className="font-medium text-[rgb(15,23,42)] mb-4">All Responses</h3>
              <div className="space-y-3">
                {responses.map((response) => (
                  <div
                    key={response.id}
                    className="flex items-start gap-3 p-3 bg-[rgb(248,250,252)] rounded-lg"
                  >
                    <Avatar className="w-8 h-8 flex-shrink-0">
                      <AvatarImage src={response.userAvatar} alt={response.userName} />
                      <AvatarFallback className="text-xs">
                        {response.userName.split(' ').map(n => n[0]).join('')}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-medium text-sm text-[rgb(15,23,42)]">
                          {response.userName}
                        </span>
                        <Badge 
                          variant={getStatusBadgeVariant(response.status)}
                          className="text-xs"
                        >
                          {getStatusIcon(response.status)}
                          <span className="ml-1 capitalize">
                            {response.status === 'not-attending' ? 'Not Going' : response.status}
                          </span>
                        </Badge>
                      </div>
                      {response.response && (
                        <p className="text-sm text-gray-600 mb-1">
                          {response.response}
                        </p>
                      )}
                      {response.respondedAt && (
                        <p className="text-xs text-gray-500">
                          {response.respondedAt.toLocaleDateString()}
                        </p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

export default function RSVPModelDemo() {
  const [isOpen, setIsOpen] = useState(true)

  return (
    <div className="min-h-screen bg-[rgb(241, 245, 249)] p-4">
