                  value="login" 
                  className="data-[state=active]:bg-[#ffffff] data-[state=active]:text-[#0f172a]"
                >
                  Sign In
                </TabsTrigger>
                {allowRegistration && (
                  <TabsTrigger 
                    value="register"
                    className="data-[state=active]:bg-[#ffffff] data-[state=active]:text-[#0f172a]"
                  >
                    Sign Up
                  </TabsTrigger>
                )}
              </TabsList>
            </Tabs>
          </CardHeader>

          <CardContent className="space-y-4">
            {errors.general && (
              <div className="bg-[#fef2f2] border border-[#fecaca] text-[#dc2626] px-4 py-3 rounded-lg text-sm">
