'use client'

import { useState, useEffect } from 'react'
import { Cloud, CloudRain, Sun, CloudSnow, Zap, Wind, Eye, Droplets, Thermometer, AlertTriangle } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'

interface WeatherData {
  current: {
    temp: number
    feels_like: number
    humidity: number
    visibility: number
    wind_speed: number
    weather: Array<{
      main: string
      description: string
      icon: string
    }>
  }
  daily: Array<{
    dt: number
    temp: {
      min: number
      max: number
    }
    weather: Array<{
      main: string
      description: string
      icon: string
    }>
    pop: number
  }>
  alerts?: Array<{
    event: string
    description: string
    start: number
    end: number
  }>
}

interface WeatherServiceProps {
  apiKey?: string
  location?: { lat: number; lon: number }
  onWeatherUpdate?: (data: WeatherData) => void
  showAlerts?: boolean
  showForecast?: boolean
}

export function WeatherService({
  apiKey = process.env.NEXT_PUBLIC_OPENWEATHER_API_KEY || 'demo_key',
  location = { lat: 39.7392, lon: -104.9903 }, // Denver, CO default
  onWeatherUpdate = () => {},
  showAlerts = true,
  showForecast = true
}: WeatherServiceProps = {}) {
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchWeatherData = async () => {
    try {
      setLoading(true)
      setError(null)

      if (apiKey === 'demo_key') {
        // Demo data for development
        const demoData: WeatherData = {
          current: {
            temp: 72,
            feels_like: 75,
            humidity: 45,
            visibility: 10000,
            wind_speed: 8.5,
            weather: [{
              main: 'Clear',
              description: 'clear sky',
              icon: '01d'
            }]
          },
          daily: [
            {
              dt: Date.now() / 1000,
              temp: { min: 58, max: 78 },
              weather: [{ main: 'Clear', description: 'clear sky', icon: '01d' }],
              pop: 0.1
            },
            {
              dt: Date.now() / 1000 + 86400,
              temp: { min: 62, max: 82 },
              weather: [{ main: 'Clouds', description: 'partly cloudy', icon: '02d' }],
              pop: 0.2
            },
            {
              dt: Date.now() / 1000 + 172800,
              temp: { min: 55, max: 75 },
              weather: [{ main: 'Rain', description: 'light rain', icon: '10d' }],
              pop: 0.7
            },
            {
              dt: Date.now() / 1000 + 259200,
              temp: { min: 60, max: 80 },
              weather: [{ main: 'Clear', description: 'clear sky', icon: '01d' }],
              pop: 0.1
            },
            {
              dt: Date.now() / 1000 + 345600,
              temp: { min: 65, max: 85 },
              weather: [{ main: 'Clouds', description: 'scattered clouds', icon: '03d' }],
              pop: 0.3
            },
            {
              dt: Date.now() / 1000 + 432000,
              temp: { min: 58, max: 78 },
              weather: [{ main: 'Thunderstorm', description: 'thunderstorm', icon: '11d' }],
              pop: 0.8
            },
            {
              dt: Date.now() / 1000 + 518400,
              temp: { min: 62, max: 82 },
              weather: [{ main: 'Clear', description: 'clear sky', icon: '01d' }],
              pop: 0.1
            }
          ]
        }

        setTimeout(() => {
          setWeatherData(demoData)
          onWeatherUpdate(demoData)
          setLoading(false)
        }, 1000)
        return
      }

      const response = await fetch(
        `https://api.openweathermap.org/data/3.0/onecall?lat=${location.lat}&lon=${location.lon}&appid=${apiKey}&units=imperial&exclude=minutely,hourly`
      )

      if (!response.ok) {
        throw new Error(`Weather API error: ${response.status}`)
      }

      const data = await response.json()
      setWeatherData(data)
      onWeatherUpdate(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch weather data')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchWeatherData()
  }, [location.lat, location.lon, apiKey])

  const getWeatherIcon = (iconCode: string, main: string) => {
    const iconMap: Record<string, any> = {
      'Clear': Sun,
      'Clouds': Cloud,
      'Rain': CloudRain,
      'Drizzle': CloudRain,
      'Thunderstorm': Zap,
      'Snow': CloudSnow,
      'Mist': Cloud,
      'Fog': Cloud
    }

    return iconMap[main] || Cloud
  }

  const formatDate = (timestamp: number) => {
    return new Date(timestamp * 1000).toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    })
  }

  if (loading) {
    return (
      <div className="space-y-4">
        <Card>
          <CardHeader>
            <div className="h-6 bg-[rgb(241,245,249)] rounded animate-pulse" />
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="h-20 bg-[rgb(241,245,249)] rounded animate-pulse" />
            <div className="grid grid-cols-3 gap-4">
              {[1, 2, 3].map((i) => (
                <div key={i} className="h-16 bg-[rgb(241,245,249)] rounded animate-pulse" />
              ))}
            </div>
          </CardContent>
        </Card>
        {showForecast && (
          <Card>
            <CardHeader>
              <div className="h-6 bg-[rgb(241,245,249)] rounded animate-pulse" />
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {[1, 2, 3, 4, 5].map((i) => (
                  <div key={i} className="h-12 bg-[rgb(241,245,249)] rounded animate-pulse" />
                ))}
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    )
  }

  if (error) {
    return (
      <Alert className="border-[rgb(220,38,38)] bg-red-50">
        <AlertTriangle className="h-4 w-4 text-[rgb(220,38,38)]" />
        <AlertDescription className="text-[rgb(15,23,42)]">
          {error}
          <Button 
            variant="outline" 
            size="sm" 
            onClick={fetchWeatherData}
            className="ml-2 h-8 text-xs"
          >
            Retry
          </Button>
        </AlertDescription>
      </Alert>
    )
  }

  if (!weatherData) return null

  const CurrentWeatherIcon = getWeatherIcon(
    weatherData.current.weather[0]?.icon || '',
    weatherData.current.weather[0]?.main || ''
  )

  return (
    <div className="space-y-4 font-medium">
      {/* Weather Alerts */}
      {showAlerts && weatherData.alerts && weatherData.alerts.length > 0 && (
        <div className="space-y-2">
          {weatherData.alerts.map((alert, index) => (
            <Alert key={index} className="border-[rgb(245,158,11)] bg-orange-50">
              <AlertTriangle className="h-4 w-4 text-[rgb(245,158,11)]" />
              <AlertDescription className="text-[rgb(15,23,42)]">
                <div className="font-semibold">{alert.event}</div>
                <div className="text-sm mt-1">{alert.description}</div>
                <div className="text-xs text-gray-600 mt-2">
                  {new Date(alert.start * 1000).toLocaleDateString()} - {new Date(alert.end * 1000).toLocaleDateString()}
                </div>
              </AlertDescription>
            </Alert>
          ))}
        </div>
      )}

      {/* Current Weather */}
      <Card className="shadow-md border-[rgb(226,232,240)]">
        <CardHeader className="pb-3">
          <CardTitle className="text-[rgb(15,23,42)] text-lg">Current Conditions</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <CurrentWeatherIcon className="h-12 w-12 text-[rgb(34,139,34)]" />
              <div>
                <div className="text-3xl font-bold text-[rgb(15,23,42)]">
                  {Math.round(weatherData.current.temp)}°F
                </div>
                <div className="text-sm text-gray-600 capitalize">
                  {weatherData.current.weather[0]?.description}
                </div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-sm text-gray-600">Feels like</div>
              <div className="text-xl font-semibold text-[rgb(15,23,42)]">
                {Math.round(weatherData.current.feels_like)}°F
              </div>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4 pt-4 border-t border-[rgb(226,232,240)]">
            <div className="text-center">
              <Wind className="h-5 w-5 text-[rgb(34,139,34)] mx-auto mb-1" />
              <div className="text-xs text-gray-600">Wind</div>
              <div className="text-sm font-semibold text-[rgb(15,23,42)]">
                {Math.round(weatherData.current.wind_speed)} mph
              </div>
            </div>
            <div className="text-center">
              <Droplets className="h-5 w-5 text-[rgb(34,139,34)] mx-auto mb-1" />
              <div className="text-xs text-gray-600">Humidity</div>
              <div className="text-sm font-semibold text-[rgb(15,23,42)]">
                {weatherData.current.humidity}%
              </div>
            </div>
            <div className="text-center">
              <Eye className="h-5 w-5 text-[rgb(34,139,34)] mx-auto mb-1" />
              <div className="text-xs text-gray-600">Visibility</div>
              <div className="text-sm font-semibold text-[rgb(15,23,42)]">
                {Math.round(weatherData.current.visibility / 1609)} mi
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 7-Day Forecast */}
      {showForecast && (
        <Card className="shadow-md border-[rgb(226,232,240)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-[rgb(15,23,42)] text-lg">7-Day Forecast</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {weatherData.daily.slice(0, 7).map((day, index) => {
                const DayIcon = getWeatherIcon(
                  day.weather[0]?.icon || '',
                  day.weather[0]?.main || ''
                )

                return (
                  <div key={index} className="flex items-center justify-between py-2 border-b border-[rgb(226,232,240)] last:border-b-0">
                    <div className="flex items-center gap-3 flex-1">
                      <div className="w-16 text-sm font-medium text-[rgb(15,23,42)]">
                        {index === 0 ? 'Today' : formatDate(day.dt)}
                      </div>
                      <DayIcon className="h-5 w-5 text-[rgb(34,139,34)]" />
                      <div className="text-sm text-gray-600 capitalize flex-1">
                        {day.weather[0]?.description}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      {day.pop > 0.3 && (
                        <Badge variant="secondary" className="text-xs bg-[rgb(248,250,252)] text-[rgb(15,23,42)]">
                          {Math.round(day.pop * 100)}%
                        </Badge>
                      )}
                      <div className="text-right min-w-[60px]">
                        <span className="font-semibold text-[rgb(15,23,42)]">
                          {Math.round(day.temp.max)}°
                        </span>
                        <span className="text-gray-600 ml-1">
                          {Math.round(day.temp.min)}°
                        </span>
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

// Demo component for page.tsx
export default function WeatherServiceDemo() {
