interface EmailTemplate {
  id: string
  name: string
  subject: string
  content: string
  type: 'invitation' | 'reminder' | 'update' | 'cancellation'
}

interface EmailRecipient {
  id: string
  name: string
  email: string
  status: 'pending' | 'sent' | 'delivered' | 'failed'
}

interface EmailCampaign {
  id: string
  name: string
  template: EmailTemplate
  recipients: EmailRecipient[]
  scheduledAt?: Date
  sentAt?: Date
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed'
}

interface ResendServiceProps {
  campaigns?: EmailCampaign[]
  templates?: EmailTemplate[]
  onSendEmail?: (campaignId: string, recipients: string[]) => Promise<void>
  onScheduleEmail?: (campaignId: string, scheduledAt: Date) => Promise<void>
  onCreateTemplate?: (template: Omit<EmailTemplate, 'id'>) => Promise<void>
}

const DEFAULT_TEMPLATES: EmailTemplate[] = [
  {
    id: '1',
    name: 'Trip Invitation',
    subject: '🏕️ You\'re Invited: Off-Road Adventure Trip',
    content: 'Join us for an exciting off-road adventure! We\'ll be exploring scenic trails and camping under the stars.',
    type: 'invitation'
  },
  {
    id: '2',
    name: 'Trip Reminder',
    subject: '⏰ Reminder: Off-Road Trip This Weekend',
    content: 'Don\'t forget about our upcoming off-road trip! Make sure to pack your gear and check the weather.',
    type: 'reminder'
  },
  {
    id: '3',
    name: 'Weather Update',
    subject: '🌤️ Weather Update for Your Trip',
    content: 'Here\'s the latest weather forecast for our off-road adventure. Please adjust your packing accordingly.',
    type: 'update'
  }
]

const DEFAULT_CAMPAIGNS: EmailCampaign[] = [
  {
    id: '1',
    name: 'Moab Adventure Invitation',
    template: DEFAULT_TEMPLATES[0],
    recipients: [
      { id: '1', name: 'John Smith', email: 'john@example.com', status: 'sent' },
      { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', status: 'delivered' },
      { id: '3', name: 'Mike Wilson', email: 'mike@example.com', status: 'pending' }
    ],
    status: 'sent',
    sentAt: new Date(Date.now() - 86400000)
  },
  {
    id: '2',
    name: 'Weekend Reminder',
    template: DEFAULT_TEMPLATES[1],
    recipients: [
      { id: '1', name: 'John Smith', email: 'john@example.com', status: 'pending' },
      { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', status: 'pending' }
    ],
    status: 'draft'
  }
]

export function ResendService({
  campaigns = DEFAULT_CAMPAIGNS,
  templates = DEFAULT_TEMPLATES,
  onSendEmail = async () => console.log('Email sent'),
  onScheduleEmail = async () => console.log('Email scheduled'),
  onCreateTemplate = async () => console.log('Template created')
}: ResendServiceProps = {}) {
  const [activeTab, setActiveTab] = useState<'campaigns' | 'templates'>('campaigns')
  const [selectedCampaign, setSelectedCampaign] = useState<string | null>(null)
  const [isCreatingTemplate, setIsCreatingTemplate] = useState(false)
  const [newTemplate, setNewTemplate] = useState({
    name: '',
    subject: '',
    content: '',
    type: 'invitation' as EmailTemplate['type']
  })
  const [loading, setLoading] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<string | null>(null)

  const handleSendCampaign = async (campaignId: string) => {
    try {
      setLoading(campaignId)
      setError(null)
      const campaign = campaigns.find(c => c.id === campaignId)
      if (campaign) {
        const recipientEmails = campaign.recipients.map(r => r.email)
        await onSendEmail(campaignId, recipientEmails)
        setSuccess('Campaign sent successfully!')
      }
    } catch (err) {
      setError('Failed to send campaign. Please try again.')
    } finally {
      setLoading(null)
    }
  }

  const handleCreateTemplate = async () => {
    try {
      setLoading('create-template')
      setError(null)
      await onCreateTemplate(newTemplate)
      setNewTemplate({ name: '', subject: '', content: '', type: 'invitation' })
      setIsCreatingTemplate(false)
      setSuccess('Template created successfully!')
    } catch (err) {
      setError('Failed to create template. Please try again.')
    } finally {
      setLoading(null)
    }
  }

  const getStatusColor = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'delivered':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'sent':
        return 'bg-[rgb(245,158,11)] text-white'
      case 'failed':
        return 'bg-[rgb(220,38,38)] text-white'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const getCampaignStatusColor = (status: EmailCampaign['status']) => {
    switch (status) {
      case 'sent':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'sending':
        return 'bg-[rgb(245,158,11)] text-white'
      case 'failed':
        return 'bg-[rgb(220,38,38)] text-white'
      case 'scheduled':
        return 'bg-[rgb(59,130,246)] text-white'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  return (
    <div className="w-full max-w-6xl mx-auto p-4 space-y-6 font-medium">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] flex items-center gap-2">
            <Mail className="h-6 w-6 text-[rgb(34,139,34)]" />
            Email Service
          </h1>
          <p className="text-[rgb(100,116,139)] mt-1">
            Manage email campaigns and templates for your off-road trips
          </p>
        </div>

        <div className="flex gap-2">
          <Button
            variant={activeTab === 'campaigns' ? 'default' : 'outline'}
            onClick={() => setActiveTab('campaigns')}
            className={activeTab === 'campaigns' ? 'bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90' : ''}
          >
            Campaigns
          </Button>
          <Button
            variant={activeTab === 'templates' ? 'default' : 'outline'}
            onClick={() => setActiveTab('templates')}
            className={activeTab === 'templates' ? 'bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90' : ''}
          >
            Templates
          </Button>
        </div>
      </div>

      {/* Alerts */}
      {error && (
        <Alert className="border-[rgb(220,38,38)] bg-red-50">
          <AlertCircle className="h-4 w-4 text-[rgb(220,38,38)]" />
          <AlertDescription className="text-[rgb(220,38,38)]">
            {error}
          </AlertDescription>
        </Alert>
      )}

      {success && (
        <Alert className="border-[rgb(34,139,34)] bg-green-50">
          <CheckCircle className="h-4 w-4 text-[rgb(34,139,34)]" />
          <AlertDescription className="text-[rgb(34,139,34)]">
            {success}
          </AlertDescription>
        </Alert>
      )}

      {/* Campaigns Tab */}
      {activeTab === 'campaigns' && (
        <div className="space-y-6">
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {campaigns.map((campaign) => (
              <Card key={campaign.id} className="shadow-md border-[rgb(226,232,240)]">
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between">
                    <div className="space-y-1">
                      <CardTitle className="text-lg text-[rgb(15,23,42)]">
                        {campaign.name}
                      </CardTitle>
                      <CardDescription className="text-sm">
                        {campaign.template.subject}
                      </CardDescription>
                    </div>
                    <Badge className={getCampaignStatusColor(campaign.status)}>
                      {campaign.status}
                    </Badge>
                  </div>
                </CardHeader>

                <CardContent className="space-y-4">
                  <div className="text-sm text-[rgb(100,116,139)]">
                    Recipients: {campaign.recipients.length}
                  </div>

                  <div className="space-y-2">
                    {campaign.recipients.slice(0, 3).map((recipient) => (
                      <div key={recipient.id} className="flex items-center justify-between text-sm">
                        <span className="text-[rgb(15,23,42)]">{recipient.name}</span>
                        <Badge className={getStatusColor(recipient.status)} variant="secondary">
                          {recipient.status}
                        </Badge>
                      </div>
                    ))}
                    {campaign.recipients.length > 3 && (
                      <div className="text-xs text-[rgb(100,116,139)]">
                        +{campaign.recipients.length - 3} more
                      </div>
                    )}
                  </div>

                  {campaign.status === 'draft' && (
                    <Button
                      onClick={() => handleSendCampaign(campaign.id)}
                      disabled={loading === campaign.id}
                      className="w-full bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 min-h-[44px]"
                      aria-label={`Send campaign ${campaign.name}`}
                    >
                      {loading === campaign.id ? (
                        <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      ) : (
                        <Send className="h-4 w-4 mr-2" />
                      )}
                      Send Campaign
                    </Button>
                  )}

                  {campaign.sentAt && (
                    <div className="text-xs text-[rgb(100,116,139)]">
                      Sent: {campaign.sentAt.toLocaleDateString()}
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      )}

      {/* Templates Tab */}
      {activeTab === 'templates' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Email Templates</h2>
            <Button
              onClick={() => setIsCreatingTemplate(true)}
              className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 min-h-[44px]"
              aria-label="Create new template"
            >
              Create Template
            </Button>
          </div>

          {/* Create Template Form */}
          {isCreatingTemplate && (
            <Card className="shadow-md border-[rgb(226,232,240)]">
              <CardHeader>
                <CardTitle className="text-[rgb(15,23,42)]">Create New Template</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid gap-4 sm:grid-cols-2">
                  <div>
                    <label htmlFor="template-name" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                      Template Name
                    </label>
                    <Input
                      id="template-name"
                      value={newTemplate.name}
                      onChange={(e) => setNewTemplate({ ...newTemplate, name: e.target.value })}
                      placeholder="Enter template name"
                      className="min-h-[44px]"
                      aria-required="true"
                    />
                  </div>
                  <div>
                    <label htmlFor="template-type" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                      Type
                    </label>
                    <select
                      id="template-type"
                      value={newTemplate.type}
                      onChange={(e) => setNewTemplate({ ...newTemplate, type: e.target.value as EmailTemplate['type'] })}
                      className="w-full min-h-[44px] px-3 py-2 border border-[rgb(226,232,240)] rounded-md bg-white text-[rgb(15,23,42)]"
                      aria-required="true"
                    >
                      <option value="invitation">Invitation</option>
                      <option value="reminder">Reminder</option>
                      <option value="update">Update</option>
                      <option value="cancellation">Cancellation</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label htmlFor="template-subject" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Subject Line
                  </label>
                  <Input
                    id="template-subject"
                    value={newTemplate.subject}
                    onChange={(e) => setNewTemplate({ ...newTemplate, subject: e.target.value })}
                    placeholder="Enter email subject"
                    className="min-h-[44px]"
                    aria-required="true"
                  />
                </div>

                <div>
                  <label htmlFor="template-content" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Email Content
                  </label>
                  <Textarea
                    id="template-content"
                    value={newTemplate.content}
                    onChange={(e) => setNewTemplate({ ...newTemplate, content: e.target.value })}
                    placeholder="Enter email content"
                    rows={4}
                    className="min-h-[100px]"
                    aria-required="true"
                  />
                </div>

                <div className="flex gap-2 pt-2">
                  <Button
                    onClick={handleCreateTemplate}
                    disabled={loading === 'create-template' || !newTemplate.name || !newTemplate.subject}
                    className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 min-h-[44px]"
                  >
                    {loading === 'create-template' ? (
                      <Loader2 className="h-4 w-4 animate-spin mr-2" />
                    ) : null}
                    Create Template
                  </Button>
                  <Button
                    variant="outline"
                    onClick={() => setIsCreatingTemplate(false)}
                    className="min-h-[44px]"
                  >
                    Cancel
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Templates List */}
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {templates.map((template) => (
              <Card key={template.id} className="shadow-md border-[rgb(226,232,240)]">
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between">
                    <div className="space-y-1">
                      <CardTitle className="text-lg text-[rgb(15,23,42)]">
                        {template.name}
                      </CardTitle>
                      <CardDescription className="text-sm">
                        {template.subject}
                      </CardDescription>
                    </div>
                    <Badge variant="secondary" className="bg-[rgb(241,245,249)] text-[rgb(15,23,42)]">
                      {template.type}
                    </Badge>
                  </div>
                </CardHeader>

                <CardContent>
                  <p className="text-sm text-[rgb(100,116,139)] line-clamp-3">
                    {template.content}
                  </p>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

export default function ResendServiceDemo() {
  return <ResendService />
}

