const TERRAIN_ICONS = {
  mountain: Mountain,
  forest: TreePine,
  desert: Navigation,
  coastal: Waves,
  plains: MapPin
}

const DIFFICULTY_COLORS = {
  easy: 'bg-[rgb(34,139,34)]',
  moderate: 'bg-[rgb(245,158,11)]',
  difficult: 'bg-[rgb(239,68,68)]',
  expert: 'bg-[rgb(220,38,38)]'
}

export function LocationService({
  onLocationSelect = () => {},
  onLocationSave = () => {},
  initialSearchQuery = '',
  showFavoritesOnly = false
}: LocationServiceProps = {}) {
  const [locations, setLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [searchQuery, setSearchQuery] = useState(initialSearchQuery)
  const [isLoading, setIsLoading] = useState(false)
  const [selectedTerrain, setSelectedTerrain] = useState<string>('all')
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('all')
  const { toast } = useToast()

  const debounceSearch = useCallback(
    debounce((query: string) => {
      filterLocations(query, selectedTerrain, selectedDifficulty)
    }, 300),
    [selectedTerrain, selectedDifficulty]
  )

  useEffect(() => {
    debounceSearch(searchQuery)
  }, [searchQuery, debounceSearch])

  useEffect(() => {
    filterLocations(searchQuery, selectedTerrain, selectedDifficulty)
  }, [selectedTerrain, selectedDifficulty, locations, showFavoritesOnly])

  const filterLocations = (query: string, terrain: string, difficulty: string) => {
    let filtered = [...locations]

    if (showFavoritesOnly) {
      filtered = filtered.filter(location => location.isFavorite)
    }

    if (query) {
      filtered = filtered.filter(location =>
        location.name.toLowerCase().includes(query.toLowerCase()) ||
        location.description.toLowerCase().includes(query.toLowerCase()) ||
        location.tags.some(tag => tag.toLowerCase().includes(query.toLowerCase()))
      )
    }

    if (terrain !== 'all') {
      filtered = filtered.filter(location => location.terrain === terrain)
    }

    if (difficulty !== 'all') {
      filtered = filtered.filter(location => location.difficulty === difficulty)
    }

    setFilteredLocations(filtered)
  }

  const toggleFavorite = async (locationId: string) => {
    setIsLoading(true)
    try {
      const updatedLocations = locations.map(location =>
        location.id === locationId
          ? { ...location, isFavorite: !location.isFavorite }
          : location
      )
      setLocations(updatedLocations)

      const location = updatedLocations.find(l => l.id === locationId)
      if (location) {
        onLocationSave(location)
        toast({
          title: location.isFavorite ? 'Location Saved' : 'Location Removed',
          description: location.isFavorite 
            ? `${location.name} has been added to your favorites`
            : `${location.name} has been removed from your favorites`
        })
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update location. Please try again.',
        variant: 'destructive'
      })
    } finally {
      setIsLoading(false)
    }
  }

  const handleLocationSelect = (location: Location) => {
    onLocationSelect(location)
    toast({
      title: 'Location Selected',
      description: `${location.name} has been selected for your trip`
    })
  }

  const TerrainIcon = ({ terrain }: { terrain: string }) => {
    const Icon = TERRAIN_ICONS[terrain as keyof typeof TERRAIN_ICONS] || MapPin
    return <Icon className="h-4 w-4" />
  }

  return (
    <div className="w-full max-w-4xl mx-auto p-4 space-y-6">
      {/* Search and Filters */}
      <div className="space-y-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[rgb(100,116,139)] h-4 w-4" />
          <Input
            placeholder="Search locations, terrain, or tags..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10 h-12 text-base font-medium border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-[rgb(34,139,34)]"
            aria-label="Search locations"
          />
        </div>

        <div className="flex flex-wrap gap-2">
          <select
            value={selectedTerrain}
            onChange={(e) => setSelectedTerrain(e.target.value)}
            className="px-3 py-2 border border-[rgb(226,232,240)] rounded-md text-sm font-medium bg-white focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-[rgb(34,139,34)]"
            aria-label="Filter by terrain"
          >
            <option value="all">All Terrain</option>
            <option value="mountain">Mountain</option>
            <option value="forest">Forest</option>
            <option value="desert">Desert</option>
            <option value="coastal">Coastal</option>
            <option value="plains">Plains</option>
          </select>

          <select
            value={selectedDifficulty}
            onChange={(e) => setSelectedDifficulty(e.target.value)}
            className="px-3 py-2 border border-[rgb(226,232,240)] rounded-md text-sm font-medium bg-white focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-[rgb(34,139,34)]"
            aria-label="Filter by difficulty"
          >
            <option value="all">All Difficulty</option>
            <option value="easy">Easy</option>
            <option value="moderate">Moderate</option>
            <option value="difficult">Difficult</option>
            <option value="expert">Expert</option>
          </select>
        </div>
      </div>

      {/* Results Count */}
      <div className="text-sm text-[rgb(100,116,139)] font-medium">
        {filteredLocations.length} location{filteredLocations.length !== 1 ? 's' : ''} found
      </div>

      {/* Location Cards */}
      <div className="grid gap-4 md:grid-cols-2">
        {filteredLocations.map((location) => (
          <Card 
            key={location.id} 
            className="border-[rgb(226,232,240)] shadow-md hover:shadow-lg transition-shadow duration-200 cursor-pointer"
            onClick={() => handleLocationSelect(location)}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault()
                handleLocationSelect(location)
              }
            }}
            aria-label={`Select ${location.name}`}
          >
            <CardHeader className="pb-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)] mb-1">
                    {location.name}
                  </CardTitle>
                  <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
                    <TerrainIcon terrain={location.terrain} />
                    <span className="capitalize">{location.terrain}</span>
                    <span>•</span>
                    <span className="flex items-center gap-1">
                      <Star className="h-3 w-3 fill-[rgb(245,158,11)] text-[rgb(245,158,11)]" />
                      {location.rating}
                    </span>
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={(e) => {
                    e.stopPropagation()
                    toggleFavorite(location.id)
                  }}
                  disabled={isLoading}
                  className="p-2 h-auto hover:bg-[rgb(248,250,252)]"
                  aria-label={location.isFavorite ? 'Remove from favorites' : 'Add to favorites'}
                >
                  {location.isFavorite ? (
                    <Star className="h-5 w-5 fill-[rgb(245,158,11)] text-[rgb(245,158,11)]" />
                  ) : (
                    <StarOff className="h-5 w-5 text-[rgb(100,116,139)]" />
                  )}
                </Button>
              </div>
            </CardHeader>

            <CardContent className="space-y-4">
              <p className="text-sm text-[rgb(71,85,105)] font-medium leading-relaxed">
                {location.description}
              </p>

              <div className="flex flex-wrap gap-2">
                <Badge 
                  className={`${DIFFICULTY_COLORS[location.difficulty]} text-white font-medium`}
                >
                  {location.difficulty}
                </Badge>
                {location.tags.slice(0, 2).map((tag) => (
                  <Badge 
                    key={tag} 
                    variant="secondary" 
                    className="bg-[rgb(248,250,252)] text-[rgb(71,85,105)] font-medium"
                  >
                    {tag}
                  </Badge>
                ))}
              </div>

              <div className="flex items-center justify-between text-sm text-[rgb(100,116,139)]">
                <div className="flex items-center gap-4">
                  {location.distance && (
                    <span className="flex items-center gap-1">
                      <Car className="h-4 w-4" />
                      {location.distance} mi
                    </span>
                  )}
                  {location.estimatedTime && (
                    <span className="flex items-center gap-1">
                      <Clock className="h-4 w-4" />
                      {location.estimatedTime}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-1">
                  <Users className="h-4 w-4" />
                  <span>{Math.floor(Math.random() * 50) + 10} reviews</span>
                </div>
              </div>

              {location.amenities.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {location.amenities.slice(0, 3).map((amenity) => (
                    <span 
                      key={amenity}
                      className="inline-flex items-center px-2 py-1 text-xs bg-[rgb(241,245,249)] text-[rgb(71,85,105)] rounded font-medium"
                    >
                      {amenity === 'wifi' && <Wifi className="h-3 w-3 mr-1" />}
                      {amenity === 'parking' && <Car className="h-3 w-3 mr-1" />}
                      {amenity}
                    </span>
                  ))}
                  {location.amenities.length > 3 && (
                    <span className="inline-flex items-center px-2 py-1 text-xs bg-[rgb(241,245,249)] text-[rgb(71,85,105)] rounded font-medium">
                      +{location.amenities.length - 3} more
                    </span>
                  )}
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Empty State */}
      {filteredLocations.length === 0 && (
        <div className="text-center py-12">
          <MapPin className="h-12 w-12 text-[rgb(148,163,184)] mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">
            No locations found
          </h3>
          <p className="text-[rgb(100,116,139)] font-medium mb-4">
            Try adjusting your search criteria or explore different terrain types.
          </p>
          <Button
            onClick={() => {
              setSearchQuery('')
              setSelectedTerrain('all')
              setSelectedDifficulty('all')
            }}
            className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,52)] text-white font-medium"
          >
            Clear Filters
          </Button>
        </div>
      )}
    </div>
  )
}

function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout
  return (...args: Parameters<T>) => {
    clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }
}

