import { Badge } from '@/components/ui/badge'
import { Separator } from '@/components/ui/separator'
import { toast } from '@/components/ui/use-toast'

interface Invitation {
  id: string
  tripId: string
  recipientEmail: string
  recipientName: string
  status: 'pending' | 'accepted' | 'declined'
  sentAt: Date
  respondedAt?: Date
}

interface TripDetails {
  id: string
  name: string
  location: string
  startDate: Date
  endDate: Date
  description: string
  organizer: string
}

interface InvitationServiceProps {
  tripDetails?: TripDetails
  existingInvitations?: Invitation[]
  onSendInvitation?: (email: string, name: string) => Promise<void>
  onResendInvitation?: (invitationId: string) => Promise<void>
  onCancelInvitation?: (invitationId: string) => Promise<void>
}

export function InvitationService({
  tripDetails = DEFAULT_TRIP,
  existingInvitations = DEFAULT_INVITATIONS,
  onSendInvitation = async (email, name) => {
    console.log('Sending invitation to:', email, name)
    toast({ title: 'Invitation sent successfully!' })
  },
  onResendInvitation = async (id) => {
    console.log('Resending invitation:', id)
    toast({ title: 'Invitation resent!' })
  },
  onCancelInvitation = async (id) => {
    console.log('Cancelling invitation:', id)
    toast({ title: 'Invitation cancelled' })
  }
}: InvitationServiceProps = {}) {
  const [invitations, setInvitations] = useState<Invitation[]>(existingInvitations)
  const [newEmail, setNewEmail] = useState('')
  const [newName, setNewName] = useState('')
  const [customMessage, setCustomMessage] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const handleSendInvitation = async () => {
    if (!newEmail.trim() || !newName.trim()) {
      toast({ 
        title: 'Missing information', 
        description: 'Please enter both email and name',
        variant: 'destructive'
      })
      return
    }

    if (!isValidEmail(newEmail)) {
      toast({ 
        title: 'Invalid email', 
        description: 'Please enter a valid email address',
        variant: 'destructive'
      })
      return
    }

    setIsLoading(true)
    try {
      await onSendInvitation(newEmail, newName)

      const newInvitation: Invitation = {
        id: `inv-${Date.now()}`,
        tripId: tripDetails.id,
        recipientEmail: newEmail,
        recipientName: newName,
        status: 'pending',
        sentAt: new Date()
      }

      setInvitations(prev => [...prev, newInvitation])
      setNewEmail('')
      setNewName('')
      setCustomMessage('')
    } catch (error) {
      toast({ 
        title: 'Failed to send invitation', 
        description: 'Please try again',
        variant: 'destructive'
      })
    } finally {
      setIsLoading(false)
    }
  }

  const handleResendInvitation = async (invitationId: string) => {
    setIsLoading(true)
    try {
      await onResendInvitation(invitationId)
      setInvitations(prev => 
        prev.map(inv => 
          inv.id === invitationId 
            ? { ...inv, sentAt: new Date() }
            : inv
        )
      )
    } catch (error) {
      toast({ 
        title: 'Failed to resend invitation', 
        description: 'Please try again',
        variant: 'destructive'
      })
    } finally {
      setIsLoading(false)
    }
  }

  const handleCancelInvitation = async (invitationId: string) => {
    setIsLoading(true)
    try {
      await onCancelInvitation(invitationId)
      setInvitations(prev => prev.filter(inv => inv.id !== invitationId))
    } catch (error) {
      toast({ 
        title: 'Failed to cancel invitation', 
        description: 'Please try again',
        variant: 'destructive'
      })
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusBadge = (status: Invitation['status']) => {
    switch (status) {
      case 'accepted':
        return <Badge className="bg-[rgb(34,139,34)] text-white"><Check className="w-3 h-3 mr-1" />Accepted</Badge>
      case 'declined':
        return <Badge variant="destructive"><X className="w-3 h-3 mr-1" />Declined</Badge>
      default:
        return <Badge variant="outline"><Clock className="w-3 h-3 mr-1" />Pending</Badge>
    }
  }

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    }).format(date)
  }

  const isValidEmail = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
  }

  const pendingCount = invitations.filter(inv => inv.status === 'pending').length
  const acceptedCount = invitations.filter(inv => inv.status === 'accepted').length
  const declinedCount = invitations.filter(inv => inv.status === 'declined').length

  return (
    <div className="space-y-6 p-4 max-w-4xl mx-auto">
      {/* Trip Overview */}
      <Card className="shadow-md">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 font-medium text-[rgb(15,23,42)]">
            <Calendar className="w-5 h-5 text-[rgb(34,139,34)]" />
            Trip Invitations
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <h3 className="font-medium text-[rgb(15,23,42)]">{tripDetails.name}</h3>
              <div className="flex items-center gap-2 text-sm text-gray-600">
                <MapPin className="w-4 h-4" />
                {tripDetails.location}
              </div>
              <div className="flex items-center gap-2 text-sm text-gray-600">
                <Calendar className="w-4 h-4" />
                {formatDate(tripDetails.startDate)} - {formatDate(tripDetails.endDate)}
              </div>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <div className="text-center p-3 bg-[rgb(248,250,252)] rounded-lg">
                <div className="text-lg font-medium text-[rgb(34,139,34)]">{acceptedCount}</div>
                <div className="text-xs text-gray-600">Accepted</div>
              </div>
              <div className="text-center p-3 bg-[rgb(248,250,252)] rounded-lg">
                <div className="text-lg font-medium text-[rgb(245,158,11)]">{pendingCount}</div>
                <div className="text-xs text-gray-600">Pending</div>
              </div>
              <div className="text-center p-3 bg-[rgb(248,250,252)] rounded-lg">
                <div className="text-lg font-medium text-[rgb(220,38,38)]">{declinedCount}</div>
                <div className="text-xs text-gray-600">Declined</div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Send New Invitation */}
      <Card className="shadow-md">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 font-medium text-[rgb(15,23,42)]">
            <Send className="w-5 h-5 text-[rgb(34,139,34)]" />
            Send Invitation
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label htmlFor="recipient-name" className="text-sm font-medium text-[rgb(15,23,42)]">
                Recipient Name
              </label>
              <Input
                id="recipient-name"
                placeholder="Enter full name"
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
                className="focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                aria-label="Recipient name"
              />
            </div>
            <div className="space-y-2">
              <label htmlFor="recipient-email" className="text-sm font-medium text-[rgb(15,23,42)]">
                Email Address
              </label>
              <Input
                id="recipient-email"
                type="email"
                placeholder="Enter email address"
                value={newEmail}
                onChange={(e) => setNewEmail(e.target.value)}
                className="focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                aria-label="Recipient email address"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label htmlFor="custom-message" className="text-sm font-medium text-[rgb(15,23,42)]">
              Custom Message (Optional)
            </label>
            <Textarea
              id="custom-message"
              placeholder="Add a personal message to the invitation..."
              value={customMessage}
              onChange={(e) => setCustomMessage(e.target.value)}
              className="min-h-[80px] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              aria-label="Custom invitation message"
            />
          </div>

          <Button
            onClick={handleSendInvitation}
            disabled={isLoading || !newEmail.trim() || !newName.trim()}
            className="w-full md:w-auto bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white font-medium min-h-[44px]"
            aria-label="Send invitation"
          >
            <Send className="w-4 h-4 mr-2" />
            {isLoading ? 'Sending...' : 'Send Invitation'}
          </Button>
        </CardContent>
      </Card>

      {/* Invitation List */}
      <Card className="shadow-md">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 font-medium text-[rgb(15,23,42)]">
            <Users className="w-5 h-5 text-[rgb(34,139,34)]" />
            Sent Invitations ({invitations.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          {invitations.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <Mail className="w-12 h-12 mx-auto mb-4 text-gray-300" />
              <p className="text-lg font-medium mb-2">No invitations sent yet</p>
              <p className="text-sm">Send your first invitation to get started!</p>
            </div>
          ) : (
            <div className="space-y-4">
              {invitations.map((invitation, index) => (
                <div key={invitation.id}>
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-4 bg-[rgb(248,250,252)] rounded-lg">
                    <div className="flex-1 space-y-1">
                      <div className="font-medium text-[rgb(15,23,42)]">
                        {invitation.recipientName}
                      </div>
                      <div className="text-sm text-gray-600">
                        {invitation.recipientEmail}
                      </div>
                      <div className="text-xs text-gray-500">
                        Sent {formatDate(invitation.sentAt)}
                        {invitation.respondedAt && (
                          <span> • Responded {formatDate(invitation.respondedAt)}</span>
                        )}
                      </div>
                    </div>

                    <div className="flex items-center gap-3">
                      {getStatusBadge(invitation.status)}

                      {invitation.status === 'pending' && (
                        <div className="flex gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleResendInvitation(invitation.id)}
                            disabled={isLoading}
                            className="min-h-[44px] sm:min-h-auto"
                            aria-label={`Resend invitation to ${invitation.recipientName}`}
                          >
                            <Send className="w-3 h-3 mr-1" />
                            Resend
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleCancelInvitation(invitation.id)}
                            disabled={isLoading}
                            className="text-[rgb(220,38,38)] hover:text-[rgb(220,38,38)] min-h-[44px] sm:min-h-auto"
                            aria-label={`Cancel invitation to ${invitation.recipientName}`}
                          >
                            <X className="w-3 h-3 mr-1" />
                            Cancel
                          </Button>
                        </div>
                      )}
                    </div>
                  </div>
                  {index < invitations.length - 1 && <Separator className="my-2" />}
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

