  showAlerts = true,
  showForecast = true,
  refreshInterval = 300000
}: WeatherAPIProps = {}) {
  const [weather, setWeather] = useState<WeatherData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)

  const fetchWeather = async () => {
    try {
      setError(null)

      // Simulate API call - replace with actual weather service
      await new Promise(resolve => setTimeout(resolve, 1000))

      // Mock weather data based on location
      const mockWeather: WeatherData = {
        ...DEFAULT_WEATHER,
        location: {
          name: `Location ${location.lat.toFixed(2)}, ${location.lng.toFixed(2)}`,
          coordinates: location
        }
      }

      setWeather(mockWeather)
      setLastUpdated(new Date())
      onWeatherUpdate(mockWeather)
    } catch (err) {
      setError('Failed to fetch weather data. Please try again.')
      console.error('Weather API error:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchWeather()

    const interval = setInterval(fetchWeather, refreshInterval)
    return () => clearInterval(interval)
  }, [location.lat, location.lng, refreshInterval])

  const getWeatherIcon = (condition: string) => {
    switch (condition.toLowerCase()) {
      case 'sunny':
      case 'clear':
        return <Sun className="h-6 w-6 text-[rgb(245,158,11)]" />
      case 'partly-cloudy':
      case 'partly cloudy':
        return <Cloud className="h-6 w-6 text-[rgb(107,114,128)]" />
      case 'cloudy':
      case 'overcast':
        return <Cloud className="h-6 w-6 text-[rgb(75,85,99)]" />
      case 'rainy':
      case 'rain':
        return <CloudRain className="h-6 w-6 text-[rgb(59,130,246)]" />
      case 'snowy':
      case 'snow':
        return <CloudSnow className="h-6 w-6 text-[rgb(156,163,175)]" />
      case 'windy':
        return <Wind className="h-6 w-6 text-[rgb(107,114,128)]" />
      default:
        return <Sun className="h-6 w-6 text-[rgb(245,158,11)]" />
    }
  }

  const getSeverityColor = (severity: string) => {
