        return 'bg-[rgb(34,197,94)] text-[rgb(255,255,255)]'
      case 'moderate':
        return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
      case 'high':
        return 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]'
      case 'extreme':
        return 'bg-[rgb(220,38,38)] text-[rgb(255,255,255)]'
      default:
        return 'bg-[rgb(107,114,128)] text-[rgb(255,255,255)]'
    }
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })
  }

  if (loading) {
    return (
      <div className="space-y-4">
        <Card className="border-[rgb(226,232,240)]">
          <CardHeader>
            <Skeleton className="h-6 w-32" />
          </CardHeader>
          <CardContent className="space-y-4">
            <Skeleton className="h-16 w-full" />
            <div className="grid grid-cols-2 gap-4">
              <Skeleton className="h-12 w-full" />
              <Skeleton className="h-12 w-full" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-[rgb(226,232,240)]">
          <CardHeader>
            <Skeleton className="h-6 w-24" />
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2">
              {Array.from({ length: 7 }).map((_, i) => (
                <Skeleton key={i} className="h-20 w-full" />
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  if (error) {
    return (
      <Alert className="border-[rgb(220,38,38)] bg-[rgb(254,242,242)]">
        <AlertTriangle className="h-4 w-4 text-[rgb(220,38,38)]" />
        <AlertDescription className="text-[rgb(15,23,42)]">
          {error}
          <button
            onClick={fetchWeather}
            className="ml-2 text-[rgb(34,139,34)] hover:underline focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 rounded"
            aria-label="Retry fetching weather data"
          >
            Retry
          </button>
        </AlertDescription>
      </Alert>
    )
  }

  if (!weather) return null

  return (
    <div className="space-y-4 font-medium">
      {/* Weather Alerts */}
      {showAlerts && weather.alerts.length > 0 && (
        <div className="space-y-2">
          {weather.alerts.map((alert) => (
            <Alert key={alert.id} className="border-[rgb(245,158,11)] bg-[rgb(255,251,235)]">
              <AlertTriangle className="h-4 w-4 text-[rgb(245,158,11)]" />
              <AlertDescription>
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-semibold text-[rgb(15,23,42)]">{alert.title}</span>
                      <Badge className={getSeverityColor(alert.severity)}>
                        {alert.severity}
                      </Badge>
                    </div>
                    <p className="text-sm text-[rgb(15,23,42)]">{alert.description}</p>
                    <p className="text-xs text-[rgb(107,114,128)] mt-1">
                      Expires: {new Date(alert.expires).toLocaleString()}
                    </p>
                  </div>
                </div>
              </AlertDescription>
            </Alert>
          ))}
        </div>
      )}

      {/* Current Weather */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg text-[rgb(15,23,42)] flex items-center justify-between">
            <span>Current Weather</span>
            <span className="text-sm font-normal text-[rgb(107,114,128)]">
              {weather.location.name}
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              {getWeatherIcon(weather.current.condition)}
              <div>
                <div className="text-3xl font-bold text-[rgb(15,23,42)]">
                  {weather.current.temperature}°F
                </div>
                <div className="text-sm text-[rgb(107,114,128)]">
                  Feels like {weather.current.feelsLike}°F
                </div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-lg text-[rgb(15,23,42)]">{weather.current.condition}</div>
              {lastUpdated && (
                <div className="text-xs text-[rgb(107,114,128)]">
                  Updated {lastUpdated.toLocaleTimeString()}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            <div className="flex items-center gap-2 p-3 bg-[rgb(248,250,252)] rounded-lg">
              <Droplets className="h-4 w-4 text-[rgb(59,130,246)]" />
              <div>
                <div className="text-sm font-semibold text-[rgb(15,23,42)]">{weather.current.humidity}%</div>
                <div className="text-xs text-[rgb(107,114,128)]">Humidity</div>
              </div>
            </div>

            <div className="flex items-center gap-2 p-3 bg-[rgb(248,250,252)] rounded-lg">
              <Wind className="h-4 w-4 text-[rgb(107,114,128)]" />
              <div>
                <div className="text-sm font-semibold text-[rgb(15,23,42)]">{weather.current.windSpeed} mph</div>
                <div className="text-xs text-[rgb(107,114,128)]">Wind</div>
              </div>
            </div>

            <div className="flex items-center gap-2 p-3 bg-[rgb(248,250,252)] rounded-lg">
              <Eye className="h-4 w-4 text-[rgb(107,114,128)]" />
              <div>
                <div className="text-sm font-semibold text-[rgb(15,23,42)]">{weather.current.visibility} mi</div>
                <div className="text-xs text-[rgb(107,114,128)]">Visibility</div>
              </div>
            </div>

            <div className="flex items-center gap-2 p-3 bg-[rgb(248,250,252)] rounded-lg">
              <Thermometer className="h-4 w-4 text-[rgb(239,68,68)]" />
              <div>
                <div className="text-sm font-semibold text-[rgb(15,23,42)]">{weather.current.feelsLike}°F</div>
                <div className="text-xs text-[rgb(107,114,128)]">Feels Like</div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 7-Day Forecast */}
      {showForecast && (
        <Card className="border-[rgb(226,232,240)] shadow-md">
          <CardHeader className="pb-3">
            <CardTitle className="text-lg text-[rgb(15,23,42)]">7-Day Forecast</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2">
              {weather.forecast.map((day, index) => (
                <div
                  key={day.date}
                  className="p-3 bg-[rgb(248,250,252)] rounded-lg text-center hover:bg-[rgb(241,245,249)] transition-colors"
                >
                  <div className="text-xs font-semibold text-[rgb(15,23,42)] mb-2">
                    {index === 0 ? 'Today' : formatDate(day.date)}
                  </div>
                  <div className="flex justify-center mb-2">
                    {getWeatherIcon(day.condition)}
                  </div>
                  <div className="space-y-1">
                    <div className="text-sm font-semibold text-[rgb(15,23,42)]">
