    userId: '2',
    userName: 'Sarah Johnson',
    content: 'Just confirmed my attendance! Can\'t wait to see everyone.',
    timestamp: new Date(Date.now() - 78600000),
    type: 'text'
  }
]

export function ChatAPI({
  tripId = 'trip-1',
  currentUserId = '1',
  onSendMessage = async () => {},
  onTyping = () => {},
  className = ''
}: ChatAPIProps = {}) {
  const [messages, setMessages] = useState<ChatMessage[]>(MOCK_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [isTyping, setIsTyping] = useState(false)
  const [typingUsers, setTypingUsers] = useState<string[]>([])
  const [onlineUsers] = useState<ChatUser[]>(MOCK_USERS)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = async () => {
    if (!newMessage.trim() || isLoading) return

    setIsLoading(true)

    const message: ChatMessage = {
      id: Date.now().toString(),
      userId: currentUserId,
      userName: onlineUsers.find(u => u.id === currentUserId)?.name || 'You',
      content: newMessage.trim(),
      timestamp: new Date(),
      type: 'text'
    }

    // Optimistic update
    setMessages(prev => [...prev, message])
    setNewMessage('')

    try {
      await onSendMessage(newMessage.trim())
    } catch (error) {
      console.error('Failed to send message:', error)
      // Remove optimistic message on error
      setMessages(prev => prev.filter(m => m.id !== message.id))
    } finally {
      setIsLoading(false)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setNewMessage(e.target.value)

    if (!isTyping) {
      setIsTyping(true)
      onTyping(true)

      setTimeout(() => {
        setIsTyping(false)
        onTyping(false)
      }, 1000)
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const renderMessage = (message: ChatMessage) => {
    const isCurrentUser = message.userId === currentUserId
    const isSystem = message.type === 'system'

    if (isSystem) {
      return (
        <div key={message.id} className="flex justify-center my-4">
          <div className="bg-[rgb(241,245,249)] text-[rgb(15,23,42)] px-3 py-2 rounded-full text-sm font-medium flex items-center gap-2">
            {message.type === 'task' && <CheckCircle2 className="w-4 h-4 text-[rgb(34,139,34)]" />}
            {message.type === 'location' && <MapPin className="w-4 h-4 text-[rgb(245,158,11)]" />}
            {message.type === 'meal' && <Utensils className="w-4 h-4 text-[rgb(245,158,11)]" />}
            {message.content}
          </div>
        </div>
      )
    }

    return (
      <div key={message.id} className={`flex gap-3 mb-4 ${isCurrentUser ? 'flex-row-reverse' : ''}`}>
        <Avatar className="w-8 h-8 flex-shrink-0">
          <AvatarImage src={onlineUsers.find(u => u.id === message.userId)?.avatar} />
          <AvatarFallback className="bg-[rgb(34,139,34)] text-white text-xs font-medium">
            {message.userName.split(' ').map(n => n[0]).join('')}
          </AvatarFallback>
        </Avatar>

        <div className={`flex flex-col max-w-[75%] ${isCurrentUser ? 'items-end' : 'items-start'}`}>
          <div className="flex items-center gap-2 mb-1">
            <span className="text-sm font-medium text-[rgb(15,23,42)]">
              {isCurrentUser ? 'You' : message.userName}
            </span>
            <span className="text-xs text-[rgb(100,116,139)]">
              {formatTime(message.timestamp)}
            </span>
          </div>

          <div className={`px-3 py-2 rounded-lg max-w-full break-words ${
            isCurrentUser 
              ? 'bg-[rgb(34,139,34)] text-white' 
              : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
          }`}>
            <p className="text-sm leading-relaxed">{message.content}</p>

            {message.metadata && (
              <div className="mt-2 pt-2 border-t border-white/20">
                {message.metadata.taskTitle && (
                  <Badge variant="secondary" className="text-xs">
                    Task: {message.metadata.taskTitle}
                  </Badge>
                )}
                {message.metadata.location && (
                  <Badge variant="secondary" className="text-xs">
                    📍 {message.metadata.location}
                  </Badge>
                )}
                {message.metadata.mealType && (
                  <Badge variant="secondary" className="text-xs">
                    🍽️ {message.metadata.mealType} - {message.metadata.mealTime}
                  </Badge>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    )
  }

  const groupMessagesByDate = (messages: ChatMessage[]) => {
    const groups: { [key: string]: ChatMessage[] } = {}

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString()
      if (!groups[dateKey]) {
        groups[dateKey] = []
      }
      groups[dateKey].push(message)
    })

    return groups
  }

  const messageGroups = groupMessagesByDate(messages)

  return (
    <div className={`flex flex-col h-full bg-white border border-[rgb(226,232,240)] rounded-lg shadow-md ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Users className="w-5 h-5 text-[rgb(34,139,34)]" />
            <h3 className="font-semibold text-[rgb(15,23,42)]">Trip Chat</h3>
          </div>
          <Badge variant="secondary" className="text-xs">
            {onlineUsers.filter(u => u.isOnline).length} online
          </Badge>
        </div>

        <div className="flex -space-x-2">
          {onlineUsers.slice(0, 4).map(user => (
            <Avatar key={user.id} className="w-8 h-8 border-2 border-white">
              <AvatarImage src={user.avatar} />
              <AvatarFallback className="bg-[rgb(34,139,34)] text-white text-xs">
                {user.name.split(' ').map(n => n[0]).join('')}
              </AvatarFallback>
              {user.isOnline && (
                <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-[rgb(34,139,34)] border-2 border-white rounded-full" />
              )}
            </Avatar>
          ))}
        </div>
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 p-4">
        <div className="space-y-1">
          {Object.entries(messageGroups).map(([dateKey, dayMessages]) => (
            <div key={dateKey}>
              <div className="flex justify-center my-6">
                <span className="bg-[rgb(241,245,249)] text-[rgb(100,116,139)] px-3 py-1 rounded-full text-xs font-medium">
                  {formatDate(new Date(dateKey))}
                </span>
              </div>
              {dayMessages.map(renderMessage)}
            </div>
          ))}

          {typingUsers.length > 0 && (
            <div className="flex items-center gap-2 text-[rgb(100,116,139)] text-sm">
              <div className="flex space-x-1">
                <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
              </div>
              <span>{typingUsers.join(', ')} {typingUsers.length === 1 ? 'is' : 'are'} typing...</span>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      </ScrollArea>

      <Separator />

      {/* Input */}
      <div className="p-4">
        <div className="flex gap-2">
          <Input
            ref={inputRef}
            value={newMessage}
            onChange={handleInputChange}
            onKeyPress={handleKeyPress}
            placeholder="Type a message..."
            className="flex-1 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            disabled={isLoading}
            aria-label="Type a message"
          />
          <Button
            onClick={handleSendMessage}
            disabled={!newMessage.trim() || isLoading}
            className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white px-4 py-2 min-w-[44px] min-h-[44px]"
            aria-label="Send message"
          >
            {isLoading ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Send className="w-4 h-4" />
            )}
          </Button>
        </div>
      </div>
    </div>
  )
}

export default function ChatAPIDemo() {
  const handleSendMessage = async (message: string) => {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1000))
    console.log('Message sent:', message)
  }

  const handleTyping = (isTyping: boolean) => {
    console.log('User typing:', isTyping)
  }

  return (
    <div className="h-screen max-w-4xl mx-auto p-4">
