'use client'

import { useState } from 'react'
import { 
  Home, 
  MapPin, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed,
  Settings,
  Menu,
  X
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet'

interface NavigationItem {
  id: string
  label: string
  icon: React.ComponentType<{ className?: string }>
  href: string
  badge?: number
}

interface MobileNavigationProps {
  currentPath?: string
  onNavigate?: (path: string) => void
  unreadMessages?: number
  pendingRSVPs?: number
}

const DEFAULT_NAV_ITEMS: NavigationItem[] = [
  { id: 'home', label: 'Home', icon: Home, href: '/' },
  { id: 'locations', label: 'Locations', icon: MapPin, href: '/locations' },
  { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
  { id: 'group', label: 'Group', icon: Users, href: '/group' },
  { id: 'chat', label: 'Chat', icon: MessageCircle, href: '/chat', badge: 3 },
  { id: 'menu', label: 'Menu', icon: UtensilsCrossed, href: '/menu' },
  { id: 'settings', label: 'Settings', icon: Settings, href: '/settings' }
]

export function MobileNavigation({
  currentPath = '/',
  onNavigate = (path: string) => console.log('Navigate to:', path),
  unreadMessages = 3,
  pendingRSVPs = 2
}: MobileNavigationProps = {}) {
  const [isOpen, setIsOpen] = useState(false)

  const navItems = DEFAULT_NAV_ITEMS.map(item => ({
    ...item,
    badge: item.id === 'chat' ? unreadMessages : 
           item.id === 'group' ? pendingRSVPs : 
           item.badge
  }))

  const handleNavigate = (path: string) => {
    onNavigate(path)
    setIsOpen(false)
  }

  const isActive = (href: string) => currentPath === href

  return (
    <>
      {/* Bottom Navigation Bar - Mobile */}
      <nav 
        className="fixed bottom-0 left-0 right-0 z-50 bg-white border-t border-[rgb(226,232,240)] md:hidden"
        role="navigation"
        aria-label="Main navigation"
      >
        <div className="flex items-center justify-around px-2 py-2">
          {navItems.slice(0, 4).map((item) => {
            const Icon = item.icon
            const active = isActive(item.href)

            return (
              <Button
                key={item.id}
                variant="ghost"
                size="sm"
                className={`
                  flex flex-col items-center justify-center h-12 w-12 p-1 relative
                  ${active 
                    ? 'text-[rgb(34,139,34)] bg-[rgb(248,250,252)]' 
                    : 'text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)]'
                  }
                `}
                onClick={() => handleNavigate(item.href)}
                aria-label={item.label}
                aria-current={active ? 'page' : undefined}
              >
                <Icon className="h-5 w-5" />
                <span className="text-xs font-medium mt-0.5">{item.label}</span>
                {item.badge && item.badge > 0 && (
                  <span 
                    className="absolute -top-1 -right-1 bg-[rgb(220,38,38)] text-white text-xs rounded-full h-5 w-5 flex items-center justify-center font-medium"
                    aria-label={`${item.badge} notifications`}
                  >
                    {item.badge > 99 ? '99+' : item.badge}
                  </span>
                )}
              </Button>
            )
          })}

          {/* Menu Button */}
          <Sheet open={isOpen} onOpenChange={setIsOpen}>
            <SheetTrigger asChild>
              <Button
                variant="ghost"
                size="sm"
                className="flex flex-col items-center justify-center h-12 w-12 p-1 text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)]"
                aria-label="Open menu"
              >
                <Menu className="h-5 w-5" />
                <span className="text-xs font-medium mt-0.5">More</span>
              </Button>
            </SheetTrigger>
            <SheetContent 
              side="bottom" 
              className="h-auto max-h-[80vh] bg-white border-[rgb(226,232,240)]"
            >
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Menu</h2>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setIsOpen(false)}
                  aria-label="Close menu"
                >
                  <X className="h-5 w-5" />
                </Button>
              </div>

              <div className="grid grid-cols-2 gap-3">
                {navItems.slice(4).map((item) => {
                  const Icon = item.icon
                  const active = isActive(item.href)

                  return (
                    <Button
                      key={item.id}
                      variant="ghost"
                      className={`
                        flex items-center justify-start h-14 px-4 relative
                        ${active 
                          ? 'text-[rgb(34,139,34)] bg-[rgb(248,250,252)]' 
                          : 'text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)]'
                        }
                      `}
                      onClick={() => handleNavigate(item.href)}
                      aria-label={item.label}
                      aria-current={active ? 'page' : undefined}
                    >
                      <Icon className="h-5 w-5 mr-3" />
                      <span className="font-medium">{item.label}</span>
                      {item.badge && item.badge > 0 && (
                        <span 
                          className="absolute top-2 right-2 bg-[rgb(220,38,38)] text-white text-xs rounded-full h-5 w-5 flex items-center justify-center font-medium"
                          aria-label={`${item.badge} notifications`}
                        >
                          {item.badge > 99 ? '99+' : item.badge}
                        </span>
                      )}
                    </Button>
                  )
                })}
              </div>
            </SheetContent>
          </Sheet>
        </div>
      </nav>

      {/* Desktop Sidebar - Hidden on mobile */}
      <nav 
        className="hidden md:flex md:flex-col md:fixed md:left-0 md:top-0 md:h-full md:w-64 md:bg-white md:border-r md:border-[rgb(226,232,240)] md:z-40"
        role="navigation"
        aria-label="Main navigation"
      >
        <div className="p-6">
          <h1 className="text-xl font-bold text-[rgb(34,139,34)]">OffRoad Planner</h1>
        </div>

        <div className="flex-1 px-3">
          {navItems.map((item) => {
            const Icon = item.icon
            const active = isActive(item.href)

            return (
              <Button
                key={item.id}
                variant="ghost"
                className={`
                  w-full justify-start h-12 px-3 mb-1 relative
                  ${active 
                    ? 'text-[rgb(34,139,34)] bg-[rgb(248,250,252)]' 
                    : 'text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)]'
                  }
                `}
                onClick={() => handleNavigate(item.href)}
                aria-label={item.label}
                aria-current={active ? 'page' : undefined}
              >
                <Icon className="h-5 w-5 mr-3" />
                <span className="font-medium">{item.label}</span>
                {item.badge && item.badge > 0 && (
                  <span 
                    className="ml-auto bg-[rgb(220,38,38)] text-white text-xs rounded-full h-5 w-5 flex items-center justify-center font-medium"
                    aria-label={`${item.badge} notifications`}
                  >
                    {item.badge > 99 ? '99+' : item.badge}
                  </span>
                )}
              </Button>
            )
          })}
        </div>
      </nav>

      {/* Spacer for bottom navigation on mobile */}
      <div className="h-16 md:hidden" aria-hidden="true" />
    </>
  )
}

// Demo component for page.tsx
export default function MobileNavigationDemo() {
  const [currentPath, setCurrentPath] = useState('/')

  return (
    <div className="min-h-screen bg-[rgb(248,250,252)]">
      <div className="md:ml-64 p-4">
        <div className="max-w-2xl mx-auto">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-4">
            Mobile Navigation Demo
          </h1>
          <p className="text-[rgb(15,23,42)] mb-6">
            Current path: <span className="font-medium text-[rgb(34,139,34)]">{currentPath}</span>
          </p>
          <div className="bg-white rounded-lg p-6 shadow-md">
            <h2 className="text-lg font-semibold mb-4">Navigation Features</h2>
            <ul className="space-y-2 text-sm">
              <li>• Mobile-first bottom navigation</li>
              <li>• Desktop sidebar navigation</li>
              <li>• Badge notifications for chat and group</li>
              <li>• Active state indicators</li>
              <li>• Accessible keyboard navigation</li>
              <li>• Touch-friendly 44px targets</li>
            </ul>
          </div>
        </div>
      </div>

      <MobileNavigation 
