'use client'

import { useState } from 'react'
import { MapPin, Calendar, Users, Clock, Send, Plus, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'

interface TripMember {
  id: string
  name: string
  email: string
}

interface TripFormData {
  title: string
  description: string
  location: string
  startDate: string
  endDate: string
  members: TripMember[]
  estimatedCost: string
}

interface TripFormProps {
  initialData?: Partial<TripFormData>
  onSubmit?: (data: TripFormData) => void
  isLoading?: boolean
}

export function TripForm({
  initialData = {},
  onSubmit = (data) => console.log('Trip submitted:', data),
  isLoading = false
}: TripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    title: initialData.title || '',
    description: initialData.description || '',
    location: initialData.location || '',
    startDate: initialData.startDate || '',
    endDate: initialData.endDate || '',
    members: initialData.members || [],
    estimatedCost: initialData.estimatedCost || ''
  })

  const [newMemberName, setNewMemberName] = useState('')
  const [newMemberEmail, setNewMemberEmail] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.title.trim()) {
      newErrors.title = 'Trip title is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) > new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const addMember = () => {
    if (newMemberName.trim() && newMemberEmail.trim()) {
      const newMember: TripMember = {
        id: Date.now().toString(),
        name: newMemberName.trim(),
        email: newMemberEmail.trim()
      }
      setFormData(prev => ({
        ...prev,
        members: [...prev.members, newMember]
      }))
      setNewMemberName('')
      setNewMemberEmail('')
    }
  }

  const removeMember = (id: string) => {
    setFormData(prev => ({
      ...prev,
      members: prev.members.filter(member => member.id !== id)
    }))
  }

  const updateField = (field: keyof TripFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  return (
    <div className="w-full max-w-2xl mx-auto p-4 space-y-6">
      <Card className="shadow-md border-[rgb(226,232,240)]">
        <CardHeader className="pb-4">
          <CardTitle className="text-2xl font-bold text-[rgb(15,23,42)] flex items-center gap-2">
            <MapPin className="h-6 w-6 text-[rgb(34,139,34)]" />
            Plan Your Off-Road Adventure
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Trip Title */}
            <div className="space-y-2">
              <Label htmlFor="title" className="text-sm font-medium text-[rgb(15,23,42)]">
                Trip Title *
              </Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) => updateField('title', e.target.value)}
                placeholder="Enter trip title"
                className={`h-12 ${errors.title ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                aria-describedby={errors.title ? 'title-error' : undefined}
              />
              {errors.title && (
                <p id="title-error" className="text-sm text-[rgb(220,38,38)]" role="alert">
                  {errors.title}
                </p>
              )}
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="description" className="text-sm font-medium text-[rgb(15,23,42)]">
                Description
              </Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => updateField('description', e.target.value)}
                placeholder="Describe your off-road adventure..."
                className="min-h-[100px] border-[rgb(226,232,240)]"
                rows={4}
              />
            </div>

            {/* Location */}
            <div className="space-y-2">
              <Label htmlFor="location" className="text-sm font-medium text-[rgb(15,23,42)]">
                Location *
              </Label>
              <Input
                id="location"
                value={formData.location}
                onChange={(e) => updateField('location', e.target.value)}
                placeholder="Enter destination"
                className={`h-12 ${errors.location ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                aria-describedby={errors.location ? 'location-error' : undefined}
              />
              {errors.location && (
                <p id="location-error" className="text-sm text-[rgb(220,38,38)]" role="alert">
                  {errors.location}
                </p>
              )}
            </div>

            {/* Dates */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="startDate" className="text-sm font-medium text-[rgb(15,23,42)]">
                  Start Date *
                </Label>
                <Input
                  id="startDate"
                  type="date"
                  value={formData.startDate}
                  onChange={(e) => updateField('startDate', e.target.value)}
                  className={`h-12 ${errors.startDate ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                  aria-describedby={errors.startDate ? 'start-date-error' : undefined}
                />
                {errors.startDate && (
                  <p id="start-date-error" className="text-sm text-[rgb(220,38,38)]" role="alert">
                    {errors.startDate}
                  </p>
                )}
              </div>
              <div className="space-y-2">
                <Label htmlFor="endDate" className="text-sm font-medium text-[rgb(15,23,42)]">
                  End Date *
                </Label>
                <Input
                  id="endDate"
                  type="date"
                  value={formData.endDate}
                  onChange={(e) => updateField('endDate', e.target.value)}
                  className={`h-12 ${errors.endDate ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'}`}
                  aria-describedby={errors.endDate ? 'end-date-error' : undefined}
                />
                {errors.endDate && (
                  <p id="end-date-error" className="text-sm text-[rgb(220,38,38)]" role="alert">
                    {errors.endDate}
                  </p>
                )}
              </div>
            </div>

            {/* Estimated Cost */}
            <div className="space-y-2">
              <Label htmlFor="estimatedCost" className="text-sm font-medium text-[rgb(15,23,42)]">
                Estimated Cost per Person
              </Label>
              <Input
                id="estimatedCost"
                type="number"
                value={formData.estimatedCost}
                onChange={(e) => updateField('estimatedCost', e.target.value)}
                placeholder="0"
                min="0"
                step="0.01"
                className="h-12 border-[rgb(226,232,240)]"
              />
            </div>

            {/* Group Members */}
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <Users className="h-5 w-5 text-[rgb(34,139,34)]" />
                <Label className="text-sm font-medium text-[rgb(15,23,42)]">
                  Group Members ({formData.members.length})
                </Label>
              </div>

              {/* Add Member Form */}
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                <Input
                  value={newMemberName}
                  onChange={(e) => setNewMemberName(e.target.value)}
                  placeholder="Member name"
                  className="h-12 border-[rgb(226,232,240)]"
                />
                <Input
                  type="email"
                  value={newMemberEmail}
                  onChange={(e) => setNewMemberEmail(e.target.value)}
                  placeholder="Email address"
                  className="h-12 border-[rgb(226,232,240)]"
                />
                <Button
                  type="button"
                  onClick={addMember}
                  disabled={!newMemberName.trim() || !newMemberEmail.trim()}
                  className="h-12 bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Add
                </Button>
              </div>

              {/* Members List */}
              {formData.members.length > 0 && (
                <div className="space-y-2">
                  {formData.members.map((member) => (
                    <div
                      key={member.id}
                      className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]"
                    >
                      <div className="flex-1">
                        <p className="font-medium text-[rgb(15,23,42)]">{member.name}</p>
                        <p className="text-sm text-gray-600">{member.email}</p>
                      </div>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => removeMember(member.id)}
                        className="text-[rgb(220,38,38)] hover:text-[rgb(220,38,38)] hover:bg-red-50"
                        aria-label={`Remove ${member.name} from trip`}
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Submit Button */}
            <Button
              type="submit"
              disabled={isLoading}
              className="w-full h-12 bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white font-medium"
            >
              {isLoading ? (
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 animate-spin" />
                  Creating Trip...
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <Send className="h-4 w-4" />
                  Create Trip
                </div>
              )}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}

