'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, Paperclip, Smile, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { cn } from '@/lib/utils'

interface MessageInputProps {
  onSendMessage?: (message: string, attachments?: File[]) => void
  placeholder?: string
  disabled?: boolean
  maxLength?: number
  allowAttachments?: boolean
  className?: string
}

interface Attachment {
  id: string
  file: File
  preview?: string
}

export function MessageInput({
  onSendMessage = (message: string, attachments?: File[]) => {
    console.log('Sending message:', message, 'with attachments:', attachments)
  },
  placeholder = 'Type your message...',
  disabled = false,
  maxLength = 1000,
  allowAttachments = true,
  className
}: MessageInputProps = {}) {
  const [message, setMessage] = useState('')
  const [attachments, setAttachments] = useState<Attachment[]>([])
  const [isExpanded, setIsExpanded] = useState(false)
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    if (message.trim() || attachments.length > 0) {
      const attachmentFiles = attachments.map(att => att.file)
      onSendMessage(message.trim(), attachmentFiles.length > 0 ? attachmentFiles : undefined)
      setMessage('')
      setAttachments([])
      setIsExpanded(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSubmit(e)
    }
  }

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || [])

    files.forEach(file => {
      const id = Math.random().toString(36).substr(2, 9)
      const newAttachment: Attachment = { id, file }

      if (file.type.startsWith('image/')) {
        const reader = new FileReader()
        reader.onload = (e) => {
          setAttachments(prev => prev.map(att => 
            att.id === id ? { ...att, preview: e.target?.result as string } : att
          ))
        }
        reader.readAsDataURL(file)
      }

      setAttachments(prev => [...prev, newAttachment])
    })

    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
  }

  const removeAttachment = (id: string) => {
    setAttachments(prev => prev.filter(att => att.id !== id))
  }

  const canSend = message.trim().length > 0 || attachments.length > 0

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`
    }
  }, [message])

  return (
    <div className={cn(
      'w-full bg-white border border-[rgb(226,232,240)] rounded-lg shadow-md',
      'focus-within:ring-2 focus-within:ring-[rgb(34,139,34)] focus-within:ring-offset-2',
      className
    )}>
      {/* Attachments Preview */}
      {attachments.length > 0 && (
        <div className="p-3 border-b border-[rgb(226,232,240)]">
          <div className="flex flex-wrap gap-2">
            {attachments.map((attachment) => (
              <div
                key={attachment.id}
                className="relative bg-[rgb(241,245,249)] rounded-md p-2 flex items-center gap-2 max-w-[200px]"
              >
                {attachment.preview ? (
                  <img
                    src={attachment.preview}
                    alt={attachment.file.name}
                    className="w-8 h-8 object-cover rounded"
                  />
                ) : (
                  <div className="w-8 h-8 bg-[rgb(226,232,240)] rounded flex items-center justify-center">
                    <Paperclip className="w-4 h-4 text-[rgb(15,23,42)]" />
                  </div>
                )}
                <span className="text-sm text-[rgb(15,23,42)] truncate font-medium">
                  {attachment.file.name}
                </span>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="h-6 w-6 p-0 hover:bg-[rgb(220,38,38)] hover:text-white"
                  onClick={() => removeAttachment(attachment.id)}
                  aria-label={`Remove ${attachment.file.name}`}
                >
                  <X className="w-3 h-3" />
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex items-end gap-2 p-3">
        <div className="flex-1">
          <Textarea
            ref={textareaRef}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyDown={handleKeyDown}
            onFocus={() => setIsExpanded(true)}
            placeholder={placeholder}
            disabled={disabled}
            maxLength={maxLength}
            className={cn(
              'min-h-[44px] max-h-32 resize-none border-0 shadow-none',
              'focus-visible:ring-0 focus-visible:ring-offset-0',
              'placeholder:text-[rgb(148,163,184)] font-medium',
              'text-[rgb(15,23,42)]'
            )}
            aria-label="Message input"
          />

          {/* Character count */}
          {isExpanded && (
            <div className="text-xs text-[rgb(148,163,184)] mt-1 text-right">
              {message.length}/{maxLength}
            </div>
          )}
        </div>

        <div className="flex items-center gap-1">
          {/* Attachment button */}
          {allowAttachments && (
            <>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                onChange={handleFileSelect}
                className="hidden"
                accept="image/*,.pdf,.doc,.docx,.txt"
                aria-label="Attach files"
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className={cn(
                  'h-10 w-10 p-0 hover:bg-[rgb(241,245,249)]',
                  'text-[rgb(148,163,184)] hover:text-[rgb(34,139,34)]'
                )}
                onClick={() => fileInputRef.current?.click()}
                disabled={disabled}
                aria-label="Attach file"
              >
                <Paperclip className="w-5 h-5" />
              </Button>
            </>
          )}

          {/* Emoji button */}
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className={cn(
              'h-10 w-10 p-0 hover:bg-[rgb(241,245,249)]',
              'text-[rgb(148,163,184)] hover:text-[rgb(245,158,11)]'
            )}
            disabled={disabled}
            aria-label="Add emoji"
          >
            <Smile className="w-5 h-5" />
          </Button>

          {/* Send button */}
          <Button
            type="submit"
            size="sm"
            disabled={!canSend || disabled}
            className={cn(
              'h-10 w-10 p-0 bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90',
              'text-white shadow-sm',
              'disabled:bg-[rgb(226,232,240)] disabled:text-[rgb(148,163,184)]',
              'disabled:cursor-not-allowed'
            )}
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </Button>
        </div>
      </form>
    </div>
  )
}

