function getWeatherIcon(iconType: string, className: string = 'w-6 h-6') {
  switch (iconType) {
    case 'sunny':
      return <Sun className={className} style={{ color: 'rgb(245, 158, 11)' }} />
    case 'partly-cloudy':
      return <Cloud className={className} style={{ color: 'rgb(107, 114, 128)' }} />
    case 'cloudy':
      return <Cloud className={className} style={{ color: 'rgb(75, 85, 99)' }} />
    case 'rainy':
      return <CloudRain className={className} style={{ color: 'rgb(59, 130, 246)' }} />
    case 'snowy':
      return <CloudSnow className={className} style={{ color: 'rgb(156, 163, 175)' }} />
    default:
      return <Sun className={className} style={{ color: 'rgb(245, 158, 11)' }} />
  }
}

function WeatherAlert({ alert }: { alert: WeatherData['alerts'][0] }) {
  const severityColors = {
    low: 'rgb(34, 139, 34)',
    moderate: 'rgb(245, 158, 11)',
