interface Message {
  id: string
  content: string
  senderId: string
  senderName: string
  senderAvatar?: string
  timestamp: Date
  type: 'text' | 'image' | 'file'
  isRead: boolean
}

interface GroupMember {
  id: string
  name: string
  avatar?: string
  isOnline: boolean
  role?: string
}

interface ChatComponentProps {
  messages?: Message[]
  members?: GroupMember[]
  currentUserId?: string
  tripName?: string
  onSendMessage?: (content: string) => void
  onTyping?: (isTyping: boolean) => void
  className?: string
}

export function ChatComponent({
  messages = DEFAULT_MESSAGES,
  members = DEFAULT_MEMBERS,
  currentUserId = 'user-1',
  tripName = 'Moab Adventure 2024',
  onSendMessage = (content: string) => console.log('Send message:', content),
  onTyping = (isTyping: boolean) => console.log('Typing:', isTyping),
  className = ''
}: ChatComponentProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      onSendMessage(newMessage.trim())
      setNewMessage('')
      setIsTyping(false)
      onTyping(false)
    }
  }

  const handleInputChange = (value: string) => {
    setNewMessage(value)
    if (value.trim() && !isTyping) {
      setIsTyping(true)
      onTyping(true)
    } else if (!value.trim() && isTyping) {
      setIsTyping(false)
      onTyping(false)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const groupMessagesByDate = (messages: Message[]) => {
    const groups: { [key: string]: Message[] } = {}

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString()
      if (!groups[dateKey]) {
        groups[dateKey] = []
      }
      groups[dateKey].push(message)
    })

    return Object.entries(groups).map(([dateKey, msgs]) => ({
      date: new Date(dateKey),
      messages: msgs
    }))
  }

  const onlineMembers = members.filter(member => member.isOnline)

  return (
    <div className={`flex flex-col h-full bg-white border border-[rgb(226,232,240)] rounded-lg shadow-md ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Users className="w-5 h-5 text-[rgb(34,139,34)]" />
            <h2 className="font-semibold text-[rgb(15,23,42)] text-lg">{tripName}</h2>
          </div>
          <Badge variant="secondary" className="bg-[rgb(34,139,34)] text-white">
            {onlineMembers.length} online
          </Badge>
        </div>
        <Button
          variant="ghost"
          size="sm"
          className="text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]"
          aria-label="Chat options"
        >
          <MoreVertical className="w-4 h-4" />
        </Button>
      </div>

      {/* Members Bar */}
      <div className="flex items-center gap-2 p-3 border-b border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <ScrollArea className="w-full">
          <div className="flex gap-2">
            {members.map((member) => (
              <div key={member.id} className="flex items-center gap-1 shrink-0">
                <div className="relative">
                  <Avatar className="w-6 h-6">
                    <AvatarImage src={member.avatar} alt={member.name} />
                    <AvatarFallback className="text-xs bg-[rgb(34,139,34)] text-white">
                      {member.name.charAt(0)}
                    </AvatarFallback>
                  </Avatar>
                  {member.isOnline && (
                    <div className="absolute -bottom-0.5 -right-0.5 w-2 h-2 bg-[rgb(34,139,34)] rounded-full border border-white" />
                  )}
                </div>
                <span className="text-xs text-[rgb(15,23,42)] font-medium">{member.name}</span>
              </div>
            ))}
          </div>
        </ScrollArea>
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 p-4">
        <div className="space-y-4">
          {groupMessagesByDate(messages).map((group) => (
            <div key={group.date.toISOString()}>
              {/* Date Separator */}
              <div className="flex items-center justify-center my-4">
                <div className="bg-[rgb(241,245,249)] px-3 py-1 rounded-full">
                  <span className="text-xs text-[rgb(15,23,42)] font-medium">
                    {formatDate(group.date)}
                  </span>
                </div>
              </div>

              {/* Messages for this date */}
              <div className="space-y-3">
                {group.messages.map((message) => {
                  const isOwnMessage = message.senderId === currentUserId
                  const sender = members.find(m => m.id === message.senderId)

                  return (
                    <div
                      key={message.id}
                      className={`flex gap-3 ${isOwnMessage ? 'flex-row-reverse' : 'flex-row'}`}
                    >
                      {!isOwnMessage && (
                        <Avatar className="w-8 h-8 shrink-0">
                          <AvatarImage src={sender?.avatar} alt={message.senderName} />
                          <AvatarFallback className="bg-[rgb(34,139,34)] text-white text-sm">
                            {message.senderName.charAt(0)}
                          </AvatarFallback>
                        </Avatar>
                      )}

                      <div className={`flex flex-col max-w-[80%] ${isOwnMessage ? 'items-end' : 'items-start'}`}>
                        {!isOwnMessage && (
                          <span className="text-xs text-[rgb(15,23,42)] font-medium mb-1">
                            {message.senderName}
                          </span>
                        )}

                        <div
                          className={`px-3 py-2 rounded-lg ${
                            isOwnMessage
                              ? 'bg-[rgb(34,139,34)] text-white'
                              : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
                          }`}
                        >
                          <p className="text-sm leading-relaxed break-words">{message.content}</p>
                        </div>

                        <span className="text-xs text-[rgb(15,23,42)] opacity-60 mt-1">
                          {formatTime(message.timestamp)}
                        </span>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>
      </ScrollArea>

      {/* Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <div className="flex items-end gap-2">
          <Button
            variant="ghost"
            size="sm"
            className="text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)] shrink-0"
            aria-label="Attach file"
          >
            <Paperclip className="w-4 h-4" />
          </Button>

          <div className="flex-1 relative">
            <Input
              ref={inputRef}
              value={newMessage}
              onChange={(e) => handleInputChange(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="pr-10 bg-white border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
              aria-label="Type your message"
            />
            <Button
              variant="ghost"
              size="sm"
              className="absolute right-1 top-1/2 -translate-y-1/2 text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]"
              aria-label="Add emoji"
            >
              <Smile className="w-4 h-4" />
            </Button>
          </div>

          <Button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white shrink-0 min-h-[44px] min-w-[44px]"
            aria-label="Send message"
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </div>
  )
}

