'use client'

import { useState, useEffect, useCallback } from 'react'
import { Search, MapPin, Star, Bookmark, Navigation, Mountain, Trees, Waves, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { useToast } from '@/components/ui/use-toast'

interface Location {
  id: string
  name: string
  coordinates: {
    lat: number
    lng: number
  }
  description: string
  terrain: 'mountain' | 'forest' | 'desert' | 'coastal' | 'plains'
  difficulty: 'easy' | 'moderate' | 'difficult' | 'expert'
  rating: number
  distance?: number
  amenities: string[]
  isFavorite: boolean
  imageUrl?: string
}

interface LocationPickerProps {
  onLocationSelect?: (location: Location) => void
  onLocationSave?: (location: Location) => void
  savedLocations?: Location[]
  currentLocation?: { lat: number; lng: number }
  searchRadius?: number
}

const MOCK_LOCATIONS: Location[] = [
  {
    id: '1',
    name: 'Moab Desert Trail',
    coordinates: { lat: 38.5733, lng: -109.5498 },
    description: 'Stunning red rock formations with challenging terrain perfect for experienced off-roaders.',
    terrain: 'desert',
    difficulty: 'difficult',
    rating: 4.8,
    distance: 12.5,
    amenities: ['Camping', 'Restrooms', 'Water'],
    isFavorite: true,
    imageUrl: '/api/placeholder/300/200'
  },
  {
    id: '2',
    name: 'Pine Ridge Forest',
    coordinates: { lat: 40.7589, lng: -111.8883 },
    description: 'Dense forest trails with moderate difficulty and beautiful scenic views.',
    terrain: 'forest',
    difficulty: 'moderate',
    rating: 4.5,
    distance: 8.2,
    amenities: ['Camping', 'Fire Pits', 'Hiking Trails'],
    isFavorite: false,
    imageUrl: '/api/placeholder/300/200'
  },
  {
    id: '3',
    name: 'Rocky Mountain Pass',
    coordinates: { lat: 39.7392, lng: -104.9903 },
    description: 'High altitude mountain trails with breathtaking views and technical challenges.',
    terrain: 'mountain',
    difficulty: 'expert',
    rating: 4.9,
    distance: 15.7,
    amenities: ['Scenic Overlooks', 'Wildlife Viewing'],
    isFavorite: true,
    imageUrl: '/api/placeholder/300/200'
  },
  {
    id: '4',
    name: 'Coastal Dunes Adventure',
    coordinates: { lat: 36.7783, lng: -119.4179 },
    description: 'Sandy coastal dunes with easy access and family-friendly trails.',
    terrain: 'coastal',
    difficulty: 'easy',
    rating: 4.2,
    distance: 5.3,
    amenities: ['Beach Access', 'Parking', 'Restrooms', 'Picnic Areas'],
    isFavorite: false,
    imageUrl: '/api/placeholder/300/200'
  }
]

const TERRAIN_ICONS = {
  mountain: Mountain,
  forest: Trees,
  desert: Navigation,
  coastal: Waves,
  plains: MapPin
}

const DIFFICULTY_COLORS = {
  easy: 'bg-[#22c55e] text-white',
  moderate: 'bg-[#f59e0b] text-white',
  difficult: 'bg-[#ef4444] text-white',
  expert: 'bg-[#7c3aed] text-white'
}

export function LocationPicker({
  onLocationSelect = () => console.log('Location selected'),
  onLocationSave = () => console.log('Location saved'),
  savedLocations = [],
  currentLocation,
  searchRadius = 50
}: LocationPickerProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [favorites, setFavorites] = useState<Location[]>(MOCK_LOCATIONS.filter(loc => loc.isFavorite))
  const [selectedTerrain, setSelectedTerrain] = useState<string>('all')
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('all')
  const [isLoading, setIsLoading] = useState(false)
  const { toast } = useToast()

  const debounce = useCallback((func: Function, delay: number) => {
    let timeoutId: NodeJS.Timeout
    return (...args: any[]) => {
      clearTimeout(timeoutId)
      timeoutId = setTimeout(() => func.apply(null, args), delay)
    }
  }, [])

  const debouncedSearch = useCallback(
    debounce((query: string) => {
      setIsLoading(true)
      setTimeout(() => {
        const filtered = MOCK_LOCATIONS.filter(location =>
          location.name.toLowerCase().includes(query.toLowerCase()) ||
          location.description.toLowerCase().includes(query.toLowerCase())
        )
        setFilteredLocations(filtered)
        setIsLoading(false)
      }, 300)
    }, 300),
    []
  )

  useEffect(() => {
    if (searchQuery) {
      debouncedSearch(searchQuery)
    } else {
      setFilteredLocations(MOCK_LOCATIONS)
    }
  }, [searchQuery, debouncedSearch])

  useEffect(() => {
    let filtered = searchQuery 
      ? filteredLocations 
      : MOCK_LOCATIONS

    if (selectedTerrain !== 'all') {
      filtered = filtered.filter(loc => loc.terrain === selectedTerrain)
    }

    if (selectedDifficulty !== 'all') {
      filtered = filtered.filter(loc => loc.difficulty === selectedDifficulty)
    }

    setFilteredLocations(filtered)
  }, [selectedTerrain, selectedDifficulty, searchQuery])

  const handleToggleFavorite = (location: Location) => {
    const updatedLocation = { ...location, isFavorite: !location.isFavorite }

    if (updatedLocation.isFavorite) {
      setFavorites(prev => [...prev, updatedLocation])
      toast({
        title: "Location saved",
        description: `${location.name} added to favorites`,
      })
    } else {
      setFavorites(prev => prev.filter(fav => fav.id !== location.id))
      toast({
        title: "Location removed",
        description: `${location.name} removed from favorites`,
      })
    }

    onLocationSave(updatedLocation)
  }

  const handleLocationSelect = (location: Location) => {
    onLocationSelect(location)
    toast({
      title: "Location selected",
      description: `Selected ${location.name} for your trip`,
    })
  }

  const LocationCard = ({ location }: { location: Location }) => {
    const TerrainIcon = TERRAIN_ICONS[location.terrain]

    return (
      <Card className="w-full shadow-md hover:shadow-lg transition-shadow duration-200 border border-[#e2e8f0]">
        <CardHeader className="pb-3">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <CardTitle className="text-lg font-semibold text-[#0f172a] mb-2">
                {location.name}
              </CardTitle>
              <div className="flex items-center gap-2 mb-2">
                <TerrainIcon className="h-4 w-4 text-[#228b22]" />
                <Badge 
                  variant="secondary" 
                  className={`text-xs ${DIFFICULTY_COLORS[location.difficulty]}`}
                >
                  {location.difficulty}
                </Badge>
                <div className="flex items-center gap-1">
                  <Star className="h-4 w-4 fill-[#f59e0b] text-[#f59e0b]" />
                  <span className="text-sm font-medium text-[#0f172a]">
                    {location.rating}
                  </span>
                </div>
              </div>
              {location.distance && (
                <p className="text-sm text-[#64748b] mb-2">
                  {location.distance} miles away
                </p>
              )}
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => handleToggleFavorite(location)}
              className="p-2 h-auto"
              aria-label={location.isFavorite ? "Remove from favorites" : "Add to favorites"}
            >
              <Bookmark 
                className={`h-5 w-5 ${
                  location.isFavorite 
                    ? 'fill-[#228b22] text-[#228b22]' 
                    : 'text-[#64748b]'
                }`} 
              />
            </Button>
          </div>
        </CardHeader>
        <CardContent className="pt-0">
          <p className="text-sm text-[#64748b] mb-4 line-clamp-2">
            {location.description}
          </p>

          <div className="flex flex-wrap gap-2 mb-4">
            {location.amenities.slice(0, 3).map((amenity) => (
              <Badge 
                key={amenity} 
                variant="outline" 
                className="text-xs border-[#e2e8f0] text-[#64748b]"
              >
                {amenity}
              </Badge>
            ))}
            {location.amenities.length > 3 && (
              <Badge 
                variant="outline" 
                className="text-xs border-[#e2e8f0] text-[#64748b]"
              >
                +{location.amenities.length - 3} more
              </Badge>
            )}
          </div>

          <Button 
            onClick={() => handleLocationSelect(location)}
            className="w-full bg-[#228b22] hover:bg-[#1e7e1e] text-white font-medium"
            size="sm"
          >
            <MapPin className="h-4 w-4 mr-2" />
            Select Location
          </Button>
        </CardContent>
      </Card>
    )
  }

  const LoadingSkeleton = () => (
    <div className="space-y-4">
      {[1, 2, 3].map((i) => (
        <Card key={i} className="w-full">
          <CardHeader>
            <div className="animate-pulse">
              <div className="h-4 bg-[#f1f5f9] rounded w-3/4 mb-2"></div>
              <div className="h-3 bg-[#f1f5f9] rounded w-1/2"></div>
            </div>
          </CardHeader>
          <CardContent>
            <div className="animate-pulse">
              <div className="h-3 bg-[#f1f5f9] rounded w-full mb-2"></div>
              <div className="h-3 bg-[#f1f5f9] rounded w-2/3"></div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  )

  return (
    <div className="w-full max-w-4xl mx-auto p-4 space-y-6">
      <div className="space-y-4">
        <h1 className="text-2xl font-bold text-[#0f172a]">Choose Your Adventure</h1>

        {/* Search Bar */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-[#64748b]" />
          <Input
            placeholder="Search locations..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10 border-[#e2e8f0] focus:ring-2 focus:ring-[#228b22] focus:border-[#228b22]"
            aria-label="Search locations"
          />
          {searchQuery && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setSearchQuery('')}
              className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1 h-auto"
              aria-label="Clear search"
            >
              <X className="h-4 w-4" />
            </Button>
          )}
        </div>

        {/* Filters */}
        <div className="flex flex-wrap gap-3">
          <select
            value={selectedTerrain}
            onChange={(e) => setSelectedTerrain(e.target.value)}
            className="px-3 py-2 border border-[#e2e8f0] rounded-md text-sm focus:ring-2 focus:ring-[#228b22] focus:border-[#228b22]"
            aria-label="Filter by terrain"
          >
            <option value="all">All Terrain</option>
            <option value="mountain">Mountain</option>
            <option value="forest">Forest</option>
            <option value="desert">Desert</option>
            <option value="coastal">Coastal</option>
            <option value="plains">Plains</option>
          </select>

          <select
            value={selectedDifficulty}
            onChange={(e) => setSelectedDifficulty(e.target.value)}
            className="px-3 py-2 border border-[#e2e8f0] rounded-md text-sm focus:ring-2 focus:ring-[#228b22] focus:border-[#228b22]"
            aria-label="Filter by difficulty"
          >
            <option value="all">All Difficulty</option>
            <option value="easy">Easy</option>
            <option value="moderate">Moderate</option>
            <option value="difficult">Difficult</option>
            <option value="expert">Expert</option>
          </select>
        </div>
      </div>

      <Tabs defaultValue="search" className="w-full">
        <TabsList className="grid w-full grid-cols-2 bg-[#f8fafc] border border-[#e2e8f0]">
          <TabsTrigger 
            value="search" 
            className="data-[state=active]:bg-[#228b22] data-[state=active]:text-white"
          >
            Search Results
          </TabsTrigger>
          <TabsTrigger 
            value="favorites"
            className="data-[state=active]:bg-[#228b22] data-[state=active]:text-white"
          >
            Favorites ({favorites.length})
          </TabsTrigger>
        </TabsList>

        <TabsContent value="search" className="mt-6">
          {isLoading ? (
            <LoadingSkeleton />
          ) : filteredLocations.length > 0 ? (
            <div className="grid gap-4 md:grid-cols-2">
              {filteredLocations.map((location) => (
                <LocationCard key={location.id} location={location} />
              ))}
            </div>
          ) : (
            <div className="text-center py-12">
              <MapPin className="h-12 w-12 text-[#64748b] mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-[#0f172a] mb-2">
                No locations found
              </h3>
              <p className="text-[#64748b] mb-4">
                Try adjusting your search criteria or filters
              </p>
              <Button 
                onClick={() => {
                  setSearchQuery('')
                  setSelectedTerrain('all')
                  setSelectedDifficulty('all')
                }}
                variant="outline"
                className="border-[#228b22] text-[#228b22] hover:bg-[#228b22] hover:text-white"
              >
                Clear Filters
              </Button>
            </div>
          )}
        </TabsContent>

        <TabsContent value="favorites" className="mt-6">
          {favorites.length > 0 ? (
            <div className="grid gap-4 md:grid-cols-2">
              {favorites.map((location) => (
                <LocationCard key={location.id} location={location} />
              ))}
            </div>
          ) : (
            <div className="text-center py-12">
              <Bookmark className="h-12 w-12 text-[#64748b] mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-[#0f172a] mb-2">
                No favorite locations yet
              </h3>
              <p className="text-[#64748b]">
                Save locations by clicking the bookmark icon to access them quickly later
              </p>
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  )
}

export default function LocationPickerDemo() {
  return <LocationPicker />
}

